INSERT INTO program_snapshots (snapshot_id, school_id, verified_at) VALUES ('1-20261118', '1', '2026-11-18T20:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f1', 'overview', 'On-campus research MS', 'The on-campus Computer Science M.S. is described as research-focused training in theory, systems, and applications.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'The on-campus Master of Science program in computer science provides rigorous, research-focused training in theory, systems and applications, preparing you to advance the frontiers of computing', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f2', 'overview', 'Distinct from the MCS', 'The page distinguishes this research M.S. from the industry-oriented Master of Computer Science.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Unlike the industry-oriented Master of Computer Science program, the MS program in computer science emphasizes fundamental and applied research.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f3', 'overview', 'Location and college', 'The degree is listed at the Tempe campus in the Ira A. Fulton Schools of Engineering.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Ira A. Fulton Schools of Engineering', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f4', 'overview', '30 credit hours', 'The program is listed as 30 credit hours.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', '30 credit hours', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f5', 'overview', 'Thesis or nonthesis option', 'Students may choose a thesis or nonthesis culminating experience.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'You may pursue either a thesis or nonthesis option as your culminating experience and can explore advanced topics such as:', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f6', 'overview', 'Advanced topic areas', 'Listed topic areas include AI, cybersecurity, quantum computing, and related areas.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'including artificial intelligence, cybersecurity, quantum computing and other novel paradigms.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f7', 'overview', 'STEM-OPT eligible', 'The program page marks the degree as STEM-OPT extension eligible.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'STEM-OPT extension eligible: Yes', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f8', 'overview', 'STEM-OPT length', 'The page says F-1 students can extend U.S. work experience by 24 months.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'International students (F1) can extend U.S. work experience by 24 months.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f9', 'overview', 'Handbook program summary', 'The 2026-2027 M.S. handbook describes a 30-credit program with a computing and AI foundation.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'The Master of Science in Computer Science is a 30-credit hour program that provides students with a comprehensive foundation in computer science and AI', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f10', 'overview', 'Six concentrations', 'The handbook lists a generic program plus five named concentrations.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'The MS in CS program offers six concentrations:', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f11', 'requirement', 'Graduate College and Fulton requirements', 'Applicants must meet Graduate College and Ira A. Fulton Schools of Engineering requirements.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Applicants must fulfill the requirements of both the Graduate College and the Ira A. Fulton Schools of Engineering.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f12', 'requirement', 'Prior degree field', 'Applicants need a bachelor''s or master''s in computer science, computer engineering, or a closely related area.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Applicants are eligible to apply to the program if they have earned a bachelor''s or master''s degree in computer science, computer engineering or a closely related area from a regionally accredited institution.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f13', 'requirement', 'GPA 3.25', 'The degree page requires a minimum 3.25 GPA in the last 60 hours of the first bachelor''s degree or in an applicable master''s program.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Applicants must have a minimum cumulative GPA of 3.25 (scale is 4.00 = "A") in the last 60 hours of their first bachelor''s degree program or a minimum cumulative GPA of 3.25 (scale is 4.00 = "A") in an applicable master''s degree program.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f14', 'requirement', 'Application materials', 'Required materials include the graduate application and fee, official transcripts, a statement of purpose, and proof of English proficiency.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'All applicants must submit:', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f15', 'requirement', 'Calculus prerequisite', 'Students must have completed two semesters or six credit hours of calculus, equivalent to Calculus I and II, before applying.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Before applying to the program, students must have completed two semesters or six credit hours of calculus, equivalent to Calculus I and II.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f16', 'requirement', 'Discrete math recommended on degree page', 'The degree page recommends a discrete math course before admission.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Completion of a discrete math course is also recommended before admission.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f18', 'requirement', 'Deficiency courses', 'Assigned additional undergraduate courses may include CSE 230, CSE 310, CSE 330, and CSE 340 or CSE 355.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'CSE 230 Computer Organization and Assembly Language Programming', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f19', 'requirement', 'Deficiency grade and timing', 'Assigned additional coursework must be completed with a C or higher within two semesters of admission, according to the degree page.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Students assigned any additional coursework upon admission must complete those classes with a grade of "C" (scale is 4.00 = "A") or higher within two semesters of admission.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f20', 'requirement', 'Letters of recommendation not required', 'The SCAI graduate CS page says letters of recommendation are not required for the Computer Science MCS/MS program.', 'https://scai.engineering.asu.edu/graduate-computer-science/', 'Letters of Recommendation are not required for students applying to the Computer Science MCS/MS program.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f21', 'requirement', 'GRE not required', 'The 2026-2027 handbook states GRE scores are not required.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'GRE scores are not required.', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f22', 'requirement', 'Handbook GPA', 'The handbook requires a minimum 3.25 GPA in the last 60 undergraduate credit hours.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'To be considered for the MS program, we require a minimum cumulative GPA of 3.25 in the last 60 credit hours of the undergraduate degree.', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f23', 'requirement', 'English proficiency', 'The handbook lists English proficiency minimums, including IELTS 6.5.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'Applicants demonstrate proficiency by scoring at least 80 (if taken before January 21, 2026) or 4 (if taken on or after January 21, 2026) on the TOEFL iBT, 6.5 on the IELTS, or 105 on the Duolingo English test.', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f24', 'course', 'Program options', 'The degree can be completed as a course-based master''s, with a thesis, or with the applied project course CSE 593.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', '30 credit hours - course-based master''s, or 30 credit hours and a thesis, or 30 credit hours including the required applied project course (CSE 593)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f25', 'course', 'Required core areas', 'All options require 9 credit hours in the core areas of applications, foundations, and systems.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Required Core Areas (9 credit hours)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f26', 'course', 'Course-based electives', 'The course-based option includes 21 credit hours of electives.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Students in the course-based option take 21 credit hours of electives.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f27', 'course', 'Thesis electives', 'Thesis students take 15 credit hours of electives.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Students in the thesis option take 15 credit hours of electives.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f28', 'course', 'Applied project electives', 'Applied project students take 18 credit hours of electives.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Applied project students take 18 credit hours of electives.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f29', 'course', 'CSE 593 Applied Project', 'The applied project culminating course is CSE 593 (3 credit hours).', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'CSE 593 Applied Project (3)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f30', 'course', 'CSE 599 Thesis', 'The thesis culminating course is CSE 599 (6 credit hours).', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'CSE 599 Thesis (6)', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f31', 'course', '500-level CSE minimum', 'At least 24 of the 30 credit hours must be 500-level CSE courses at ASU.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'At least 24 of these credit hours must be 500-level CSE courses at ASU.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f32', 'course', '400-level limit', 'Up to six credit hours of 400-level courses may be applied to the plan of study.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Up to six credit hours of 400-level courses may be applied to the plan of study.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f33', 'course', 'AI concentration courses', 'The handbook lists CSE 571, CSE 575, CSE 576, and CSE 574 as required AI concentration courses.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'CSE 571 Artificial Intelligence (3)', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f34', 'course', 'Cybersecurity concentration course', 'The handbook requires CSE 543 Information Assurance and Security in the cybersecurity concentration.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'CSE 543: Information Assurance and Security (3)', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f35', 'deadline', 'Fall priority deadline', 'The degree page lists a Fall in-person priority deadline of 12/01.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', '12/01', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f36', 'deadline', 'Spring priority deadline', 'The degree page lists a Spring in-person priority deadline of 08/01.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', '08/01', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f37', 'deadline', 'Priority deadline meaning', 'Applications completed before the priority deadline receive priority consideration; later applications are reviewed in order and on a space-available basis.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'A priority deadline means that applications submitted and completed before the priority deadline will receive priority consideration.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f38', 'deadline', 'Handbook deadlines', 'The 2026-2027 handbook lists December 1 for a Fall start and August 1 for a Spring start.', 'https://scai.engineering.asu.edu/wp-content/uploads/sites/31/2026/06/MS-CS-Handbook-2026-27.pdf', 'December 1 for Fall start', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f39', 'deadline', 'SCAI deadline table', 'The SCAI graduate CS page lists December 1 for the M.S. or M.C.S. Fall deadline.', 'https://scai.engineering.asu.edu/graduate-computer-science/', 'December 1 (MS or MCS) or', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f40', 'deadline', 'TA application for master''s students', 'The assistantships page says master''s students may apply for Spring 2027 TA, IA, or Grader positions, with a November 7 priority deadline.', 'https://scai.engineering.asu.edu/teaching-research-assistantships-fellowships-awards/', 'The application for spring 2027 TA, IA or Grader positions available for graduate students are now open. Priority deadline is November 7.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f41', 'deadline', 'TA awards emphasis', 'The same page states that TA positions are awarded to highly qualified PhD students.', 'https://scai.engineering.asu.edu/teaching-research-assistantships-fellowships-awards/', 'TA positions are awarded to highly qualified PhD students.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f42', 'faculty', 'MS thesis chair list', 'A September 2026 list names faculty currently approved to chair a Computer Science M.S. thesis. The FSE faculty directory page did not return a usable name list without JavaScript.', 'https://docs.google.com/spreadsheets/d/1SpL7-42ZH0EuwMNZf515_hpVd2Jy0_yLz6_PM67ZwLQ/edit?gid=0#gid=0', 'This list below are the faculty who are currently approved to chair a MS thesis for the Computer Science MS programs.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f43', 'faculty', 'Adil Ahmad', 'ASU directory profile (research interests): Computer Security, Systems, and Architecture', 'https://search.asu.edu/profile/4355376', 'Computer Security, Systems, and Architecture', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f44', 'faculty', 'Gail-Joon Ahn', 'ASU directory profile (research interests): Security analytics and big data driven security intelligence Formal Models for Computer Security Network and Distributed Systems Security Vulnerability and Risk Assessment Cyber Crime Analysis His research has been supported by National Science Foundation, National Security Agency, Department of', 'https://search.asu.edu/profile/1258895', 'Security analytics and big data driven security intelligence Formal Models for Computer Security Network and Distributed Systems Security Vulnerability and Risk Assessment Cyber Crime Analysis His research has been supported by National Science Foundation, National Security Agency, Department of', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f45', 'faculty', 'Chitta Baral', 'ASU directory profile (research interests): My current research focus is in on cognition and intelligence; in particular on understanding natural language, visual objects, and multi-modal documents; using knowledge in that understanding; and applying that understanding to cybersecurity, robotics, and biological and health sciences.', 'https://search.asu.edu/profile/231973', 'My current research focus is in on cognition and intelligence; in particular on understanding natural language, visual objects, and multi-modal documents; using knowledge in that understanding; and applying that understanding to cybersecurity, robotics, and biological and health sciences.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f46', 'faculty', 'Rida Bazzi', 'ASU directory profile (research interests): Distributed Computing, Blockchain, Fault Tolerance, Security', 'https://search.asu.edu/profile/15427', 'Distributed Computing, Blockchain, Fault Tolerance, Security', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f47', 'faculty', 'Hani Ben Amor', 'ASU directory profile (short bio): Ben Amor''s research topics focus on artificial intelligence, machine learning, human-robot interaction, robot vision, and automatic motor skill acquisition.', 'https://search.asu.edu/profile/2736878', 'Ben Amor''s research topics focus on artificial intelligence, machine learning, human-robot interaction, robot vision, and automatic motor skill acquisition.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f48', 'faculty', 'Kasim Candan', 'ASU directory profile (research interests): Research areas: Database/query processing & indexing techniques - algorithms and system-level research on query processing, advanced indexing, and optimization for non-traditional data Multimedia data management & retrieval - storage, indexing, similarity-based search and retrieval for', 'https://search.asu.edu/profile/20861', 'Research areas: Database/query processing & indexing techniques - algorithms and system-level research on query processing, advanced indexing, and optimization for non-traditional data Multimedia data management & retrieval - storage, indexing, similarity-based search and retrieval for', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f49', 'faculty', 'Adam Doupé', 'ASU directory profile (research interests): Cyber security, cybercrime, binary analysis, fuzzing, web security, automated vulnerability analysis, mobile app security, static analysis, program analysis, hacking competitions, and pentesting.', 'https://search.asu.edu/profile/2412296', 'Cyber security, cybercrime, binary analysis, fuzzing, web security, automated vulnerability analysis, mobile app security, static analysis, program analysis, hacking competitions, and pentesting.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f50', 'faculty', 'Stephanie Forrest', 'ASU directory profile (research interests): Forrest''s research studies the biology of computation and the computation of biology, including work on computational immunology, computer security, automated software repair, evolutionary computation, complex systems, and biological modeling.', 'https://search.asu.edu/profile/3182641', 'Forrest''s research studies the biology of computation and the computation of biology, including work on computational immunology, computer security, automated software repair, evolutionary computation, complex systems, and biological modeling.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f51', 'faculty', 'Charles Colbourn', 'ASU directory profile (research interests): My research concentrates on areas in which combinatorics and computer science interact in an elegant way. Two main directions are: combinatorial design theory applications in computer science: erasure correction, error correction, combinatorial cryptography, computational biology.', 'https://search.asu.edu/profile/384970', 'My research concentrates on areas in which combinatorics and computer science interact in an elegant way. Two main directions are: combinatorial design theory applications in computer science: erasure correction, error correction, combinatorial cryptography, computational biology.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f52', 'faculty', 'Ajay Bansal', 'ASU directory profile (research interests): Dr. Ajay Bansal''s research focuses on semantics and implementation of declarative programming languages, specifically in the areas of Logic Programming and Answer Set Programming, Knowledge Representation and Reasoning, Common Sense Reasoning, Machine learning, and Question Answering Systems.', 'https://search.asu.edu/profile/1736009', 'Dr. Ajay Bansal''s research focuses on semantics and implementation of declarative programming languages, specifically in the areas of Logic Programming and Answer Set Programming, Knowledge Representation and Reasoning, Common Sense Reasoning, Machine learning, and Question Answering Systems.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f53', 'faculty', 'Srividya Bansal', 'ASU directory profile (research interests): Semantic Computing; Big Data Integration; semantics-based solutions for outcome-based instruction design in STEM education; delivery models for Software Engineering Education; Web service description, discovery, and composition.', 'https://search.asu.edu/profile/1629159', 'Semantic Computing; Big Data Integration; semantics-based solutions for outcome-based instruction design in STEM education; delivery models for Software Engineering Education; Web service description, discovery, and composition.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f54', 'faculty', 'Jedidiah Crandall', 'ASU directory profile lists no research interests or research bio (only a personal website link).', 'https://search.asu.edu/profile/3584805', 'Jedidiah Crandall', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f55', 'faculty', 'Hasan Davulcu', 'ASU directory profile (research interests): Sociocultural Modeling and Persuasive AI Social Media and Web Mining Information Extraction and Database Systems Behavioral Analytics for Detecting Fraud', 'https://search.asu.edu/profile/515694', 'Sociocultural Modeling and Persuasive AI Social Media and Web Mining Information Extraction and Database Systems Behavioral Analytics for Detecting Fraud', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f56', 'faculty', 'Pooyan Fazli', 'ASU directory profile (research interests): Artificial Intelligence, Robot Learning, Vision and Language, Multimodal Learning, Video Understanding', 'https://search.asu.edu/profile/4408705', 'Artificial Intelligence, Robot Learning, Vision and Language, Multimodal Learning, Video Understanding', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e1', 'faculty', 'Subbarao Kambhampati', 'ASU directory profile (short bio): Kambhampati''s expertise areas include artificial intelligence, human-AI interaction, automated planning and machine learning. He is a former president of AAAI and fellow of AAAI/AAAS/ACM.', 'https://search.asu.edu/profile/95646', 'Kambhampati''s expertise areas include artificial intelligence, human-AI interaction, automated planning and machine learning. He is a former president of AAAI and fellow of AAAI/AAAS/ACM.', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e2', 'faculty', 'Aman Arora', 'ASU directory profile (research interests): Reconfigurable Computing FPGAs Hardware Acceleration of Machine Learning (ML) and Artificial Intelligence (AI) FPGA applications in areas such as quantum computing and medical Processing-In-Memory Using Machine Learning (ML) and Artificial Intelligence (AI) for CAD/EDA', 'https://search.asu.edu/profile/4860216', 'Reconfigurable Computing FPGAs Hardware Acceleration of Machine Learning (ML) and Artificial Intelligence (AI) FPGA applications in areas such as quantum computing and medical Processing-In-Memory Using Machine Learning (ML) and Artificial Intelligence (AI) for CAD/EDA', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e3', 'faculty', 'Tiffany Bao', 'ASU directory profile (bio): Her research focuses on cyber autonomy, and her work spans the areas of binary analysis techniques and game-theoretical strategy. She''s the recipient of the Carnegie Mellon University Presidential Fellowship and NSA''s Best Scientific Cybersecurity Paper.', 'https://search.asu.edu/profile/3322259', 'Her research focuses on cyber autonomy, and her work spans the areas of binary analysis techniques and game-theoretical strategy. She''s the recipient of the Carnegie Mellon University Presidential Fellowship and NSA''s Best Scientific Cybersecurity Paper.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e4', 'faculty', 'Christopher Bryan', 'ASU directory profile (research interests): Data Visualization Human-Computer Interaction Data Storytelling Explainable Machine Learning and Artificial Intelligence Virtual Reality', 'https://search.asu.edu/profile/3335256', 'Data Visualization Human-Computer Interaction Data Storytelling Explainable Machine Learning and Artificial Intelligence Virtual Reality', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e5', 'faculty', 'Zhichao Cao', 'ASU directory profile (research interests): Intelligent Data Infrastructure for AI: High-Performance Tokenization for LLMs, LLM-driven system automatic tuning and optimizations, GPU-centric data systems, LLM-serving optimizations (multi-level caching, CXL-based offloading, and indexing), failure protection for LLMs (bitflip protection, ECC', 'https://search.asu.edu/profile/4082902', 'Intelligent Data Infrastructure for AI: High-Performance Tokenization for LLMs, LLM-driven system automatic tuning and optimizations, GPU-centric data systems, LLM-serving optimizations (multi-level caching, CXL-based offloading, and indexing), failure protection for LLMs (bitflip protection, ECC', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e6', 'faculty', 'YooJung Choi', 'ASU directory profile (short bio): Choi''s research interests lie in probabilistic machine learning, tractable probabilistic modeling and inference, knowledge representation and reasoning, as well as trustworthy AI.', 'https://search.asu.edu/profile/4355375', 'Choi''s research interests lie in probabilistic machine learning, tractable probabilistic modeling and inference, knowledge representation and reasoning, as well as trustworthy AI.', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e7', 'faculty', 'Joshua Daymude', 'ASU directory profile (research interests): Programmable matter, active matter, self-organization, distributed algorithms, randomized algorithms, bio-inspired algorithms, swarm intelligence, stochastic processes, markov chain analysis.', 'https://search.asu.edu/profile/1903590', 'Programmable matter, active matter, self-organization, distributed algorithms, randomized algorithms, bio-inspired algorithms, swarm intelligence, stochastic processes, markov chain analysis.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e8', 'faculty', 'Nakul Gopalan', 'ASU directory profile (short bio): Gopalan has developed algorithms and methods that allow robots to be trained by leveraging demonstrations and natural language descriptions.', 'https://search.asu.edu/profile/4293865', 'Gopalan has developed algorithms and methods that allow robots to be trained by leveraging demonstrations and natural language descriptions.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e9', 'faculty', 'Sandeep Gupta', 'ASU directory profile (short bio): Gupta''s areas of expertise include cyber-physical systems, green and sustainable computing, mobile and pervasive computing, and parallel and distributed computing.', 'https://search.asu.edu/profile/313263', 'Gupta''s areas of expertise include cyber-physical systems, green and sustainable computing, mobile and pervasive computing, and parallel and distributed computing.', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e10', 'faculty', 'Hannah Kerner', 'ASU directory profile (short bio): Kerner''s research focuses on developing AI and machine learning advances needed to address the world''s most pressing challenges, including food security, climate change and space exploration.', 'https://search.asu.edu/profile/2608200', 'Kerner''s research focuses on developing AI and machine learning advances needed to address the world''s most pressing challenges, including food security, climate change and space exploration.', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e11', 'faculty', 'Hokeun Kim', 'ASU directory profile (short bio): He primarily studies cyber-physical systems, computing systems interacting with humans and the physical world, especially safety and security aspects.', 'https://search.asu.edu/profile/4842939', 'He primarily studies cyber-physical systems, computing systems interacting with humans and the physical world, especially safety and security aspects.', '2026-11-19T05:30:04.360Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e12', 'course', 'CSE 571', 'CSE 571 Artificial Intelligence, ASU Engage (poweredby.asu.edu) AI course page: a rigorous graduate-level study of core AI principles covering intelligent agents, reasoning under uncertainty, machine learning, and advanced problem-solving techniques.', 'https://engage.poweredby.asu.edu/ai/', 'CSE 571 A rigorous graduate-level study of core AI principles - covering intelligent agents, reasoning under uncertainty, machine learning, and advanced problem-solving techniques.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f57', 'overview', 'Plan code ESCOMSCMS', 'The ASU Computer Science M.S. degree page lists plan code ESCOMSCMS.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Plan code: ESCOMSCMS', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f58', 'overview', 'Higher Learning Commission accreditation', 'The degree page states that the program is accredited by the Higher Learning Commission, and that all ASU graduate and undergraduate academic programs are fully accredited by the Higher Learning Commission.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Accredited by the Higher Learning Commission.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f59', 'overview', 'Advanced topic areas (full list, first half)', 'The degree page''s advanced-topic list, only partly captured in existing fact f6, includes AI, machine learning and statistical modeling; big data and data mining; computational biology; computer design, architecture and compilers; and computer security, cybersecurity and cryptography. A companion fact (f60) records the rest of the same list. This is a fuller rendering of the same page, not a change to f6.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'AI, machine learning and statistical modeling big data and data mining computational biology computer design, architecture and compilers computer security, cybersecurity and cryptography', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f60', 'overview', 'Advanced topic areas (full list, second half)', 'The rest of the same advanced-topic list is: computer systems, including networking and operating systems; cyber-physical systems, Internet of Things and robotics; distributed computing and consensus protocols; novel computing paradigms, including biocomputing and quantum computation; theory, algorithms and optimization; and visualization and graphics.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'computer systems, including networking and operating systems cyber-physical systems, Internet of Things and robotics distributed computing and consensus protocols novel computing paradigms, including biocomputing and quantum computation theory, algorithms and optimization visualization and graphics', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f61', 'requirement', 'Core courses may not also count as electives', 'Courses selected as part of the core (applications, foundations, or systems) may not be used as other elective coursework on the same plan of study. Students should see the academic unit for the list of courses approved for each core area.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Courses selected as part of the core may not be used as other elective coursework on the same plan of study.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'f62', 'requirement', 'Thesis electives must be in a chosen research area', 'For the thesis option, electives must be courses in a chosen research area and approved by the student''s academic advisor.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Electives must be courses in a chosen research area and approved by the student''s academic advisor.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e13', 'course', 'CSE 590 Reading and Conference', 'Up to six credit hours can be independent study in CSE 590 Reading and Conference.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Up to six credit hours can be independent study in CSE 590 Reading and Conference.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e14', 'requirement', 'Primary admission factors', 'The degree page says the applicant''s undergraduate GPA and depth of preparation in computer science and engineering are the primary factors affecting admission.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'The applicant''s undergraduate GPA and depth of preparation in computer science and engineering are the primary factors affecting admission.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e15', 'requirement', 'English proficiency regardless of residency', 'An applicant whose native language is not English must provide proof of English proficiency regardless of their current residency.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'An applicant whose native language is not English must provide proof of English proficiency regardless of their current residency.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e16', 'overview', 'Accelerated bachelor''s plus master''s partner programs', 'The Computer Science M.S. is offered as an accelerated bachelor''s plus master''s degree, described as obtainable in as little as five years, with these undergraduate partner programs named on the page: Computer Science, BS; Computer Science (Artificial Intelligence), BS; Computer Science (Cybersecurity), BS; Computer Science (Software Engineering), BS; Computer Systems Engineering, BSE; Computer Systems Engineering (Cybersecurity), BSE; and Software Engineering, BS. Approval to pursue the accelerated master''s is typically granted during the junior year of the bachelor''s program.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'This program is offered as an accelerated bachelor''s plus master''s degree with: Computer Science, BS', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e17', 'requirement', 'Accelerated master''s approval in the junior year', 'Approval to pursue the accelerated master''s is typically granted during the junior year of the bachelor''s degree program.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Approval to pursue the accelerated master''s is typically granted during the junior year of your bachelor''s degree program.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e18', 'overview', 'Career examples', 'The degree page says graduates are prepared to pursue careers in research and education, including academia, government and industry. Career examples listed are computer network architect; computer system analyst; computer systems engineer; data scientist or engineer; machine learning, AI or computer vision engineer; software developer; and software engineer.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'Career examples include: computer network architect computer system analyst computer systems engineer data scientist or engineer machine learning, AI or computer vision engineer software developer software engineer', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('1-20261118', 'e19', 'overview', 'STEM-OPT is a 24-month extension of 12-month OPT, not for ASU Online', 'The degree page''s STEM-OPT explanation says F-1 students who earn an approved STEM degree may be eligible for a 24-month extension of the standard 12-month Optional Practical Training period, usable twice in a lifetime. It also says the STEM-OPT extension is only available to students on an F-1 visa and is not available to students completing a degree through ASU Online. This adds detail to existing facts f7 and f8 from the same page.', 'https://degrees.asu.edu/masters-phd/major/ASU00/ESCOMSCMS/computer-science-ms', 'The STEM-OPT extension is only available to students on an F-1 visa and is not available to students completing a degree through ASU Online.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_snapshots (snapshot_id, school_id, verified_at) VALUES ('13-20261118', '13', '2026-11-18T20:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f1', 'overview', 'Program and specializations', 'ECE department MSCompE page: specializations include VLSI systems, computer networks, embedded systems, machine learning, and scientific computing.', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'The areas of specialization include (but are not limited to) VLSI Systems, Computer Networks, Embedded Systems, Machine Learning and Scientific Computing.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f2', 'requirement', '30 units, Plan A or Plan B', 'Each student must complete 30 units under Plan A (thesis) or Plan B (project).', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'Each student must complete 30 units either by selecting Plan A (Thesis) or Plan B (Project).', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f3', 'requirement', '600/700-level unit split', 'Eighteen of the 30 units should be 600- and 700-numbered courses; the remaining 12 may be 500-, 600-, or 700-level department courses.', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'Eighteen of the thirty units should be 600 and 700-numbered courses. The remaining twelve units can be from 500, 600 or 700-level courses offered by the department.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f4', 'requirement', 'Outside-department course limit', 'No more than two courses may be taken from other College of Engineering or College of Sciences departments, with prior Graduate Advisor approval.', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'No more than two courses can be taken from other departments in the College of Engineering or from the College of Sciences to satisfy these requirements, with the prior approval of the Graduate Advisor.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f5', 'requirement', 'Minimum 3.0 GPA to complete the degree', 'A minimum average GPA of 3.0 is required to complete the degree.', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'A minimum average GPA of 3.0 is required to successfully complete the degree.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f6', 'requirement', 'Plan A thesis units', 'Plan A: 21 units of coursework, 6 units of COMPE 797 Research, and 3 units of COMPE 799A Thesis.', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'Students opting for Plan A must complete 21 units of course work (7 courses), 6 units of COMPE 797 "Research" (typically as two 3-unit COMPE 797 “Research”, taken in two different semesters) and 3 units of COMPE 799A "Thesis" under supervision of a full-time ECE faculty.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f7', 'requirement', 'Plan B project units', 'Plan B: at least 18 units of depth-area courses and 3 units of COMPE 798 as the project.', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'Students opting for Plan B or the Project option are required to pick an area of specialization and complete a minimum of 18 units of “Depth Area Courses” and 3 units of COMPE 798 as the project.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f8', 'requirement', 'International in-person enrollment', 'International students needing an I-20 must enroll in at least 6 units of in-person instruction per semester and may not take more than 3 units fully online.', 'https://electrical.sdsu.edu/programs/graduate/ms-computer-engineering', 'International Students requiring an I-20 immigration document from SDSU must be enrolled in a minimum of 6 units of in-person course instruction on campus, per semester. International students may not take more than 3 units of fully online course instruction, per semester.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f9', 'course', 'Computer Networks core options', 'May 11, 2026 course-guidelines PDF, CompE table: Computer Networks core may be COMPE 560, EE 602, or EE 603.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'COMPE 560: Computer Networks', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f10', 'course', 'Embedded Systems core', 'Course-guidelines PDF: Embedded Systems core is COMPE 571 Embedded Operating Systems.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'COMPE 571: Embedded Operating', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f11', 'course', 'Machine Learning and Scientific Computing core', 'Course-guidelines PDF: core course is COMPE 510 Machine Learning for Engineering.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'COMPE 510: Machine Learning for Engineering', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f12', 'course', 'VLSI Systems core', 'Course-guidelines PDF: VLSI Systems core is COMPE 572 VLSI Circuit Design.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'VLSI Systems COMPE 572: VLSI Circuit Design', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f13', 'course', 'COMPE 560', 'COMPE 560 Computer and Data Networks, SDSU 2026-27 catalog: Wide area and local area networks, multi-layered protocols, telephone systems, modems, and network applications.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88922', 'Wide area and local area networks, multi-layered protocols, telephone systems, modems, and network applications.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f14', 'course', 'COMPE 510', 'COMPE 510 Machine Learning for Engineers, SDSU 2026-27 catalog: Selected topics from linear regression, logistic regression, neural networks, support vector machine, decision trees, clustering, Naive Bayes, dimension reduction, and ensemble learning.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93432', 'Selected topics from linear regression, logistic regression, neural networks, support vector machine, decision trees, clustering, Naive Bayes, dimension reduction, and ensemble learning.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f15', 'course', 'COMPE 571', 'COMPE 571 Embedded Operating Systems, SDSU 2026-27 catalog: COMPE 375 . Real-time kernel, basic kernel services, threading and synchronization, preemptive multithreading, mutexes, spin locks, critical sections, priority scheduling, interrupts, RTOS implementation, memory management, task management, intertask communications.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88926', 'COMPE 375 . Real-time kernel, basic kernel services, threading and synchronization, preemptive multithreading, mutexes, spin locks, critical sections, priority scheduling, interrupts, RTOS implementation, memory management, task management, intertask communications.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f16', 'course', 'COMPE 572', 'COMPE 572 VLSI Circuit Design, SDSU 2026-27 catalog: E E 330 . Design of digital integrated circuits based on CMOS technology; characterization of field effect transistors, transistor level design and simulation of logic gates and subsystems; chip layout, design rules, introduction to processing; ALU architecture.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88927', 'E E 330 . Design of digital integrated circuits based on CMOS technology; characterization of field effect transistors, transistor level design and simulation of logic gates and subsystems; chip layout, design rules, introduction to processing; ALU architecture.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f17', 'course', 'COMPE 525', 'COMPE 525 Cyber-Physical Systems, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): COMPE 571 or graduate standing.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93427', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): COMPE 571 or graduate standing.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f18', 'requirement', 'Five 500-level courses allowed for MSCOMPE', 'Course-guidelines instructions: four 500-level courses are accepted for MSEE and five are allowed for MSCOMPE.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'Four 500-level courses are accepted for the MSEE graduate program and five are allowed for the MSCOMPE program.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f19', 'requirement', 'Domestic classified admission', 'Department admission page (covers MSEE and MSCompE): domestic classified standing requires a bachelor''s in Electrical or Computer Engineering from an ABET-accredited U.S. program and a 2.85 GPA in the last 60 semester (90 quarter) units of technical coursework.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'Bachelor''s degree in Electrical or Computer Engineering from an ABET accredited engineering program in the USA.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f20', 'requirement', 'Domestic technical GPA', 'Domestic classified standing also requires a minimum 2.85 GPA in the last 60 semester or 90 quarter units of technical coursework.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'A minimum grade point average of 2.85 (based on 4.0 scale) in the last 60 semester (90 quarter) units of technical course work.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f21', 'requirement', 'International classified admission', 'International classified standing requires a bachelor''s in Electrical, Electronics, Instrumentation, or Computer Engineering from a recognized program and an equivalent technical GPA of 3.0 or higher.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'An equivalent grade point average of 3.0 (based on 4.0 scale) or higher in all technical course work.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f22', 'requirement', 'International English score', 'Program minimum TOEFL is 85 or IELTS 6.5, which the page says is higher than the university minimum.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'A minimum TOEFL score of 85 or minimum IELTS score of 6.5. Please note that the minimum TOEFL score required by the program is higher than the minimum required score of the university.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f23', 'requirement', 'GRE not required (department admissions page)', 'Department admissions page: GRE scores are not required. The 2026–2027 catalog program page could not be fetched (AWS WAF), so a catalog GRE statement could not be compared.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'GRE scores are not required.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f24', 'requirement', 'Statement of purpose not considered', 'The Electrical Engineering program statement on this shared MSEE & MSCompE admissions page says an SOP is not required and is not used in admission decisions.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'The Electrical Engineering program does not require a Statement of Purpose (SOP) as it is not taken into consideration with making admission decisions. Please do not send an SOP.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f25', 'requirement', 'Unofficial transcripts and one letter of recommendation', 'Unofficial transcripts and one mandatory LOR are required for both MSEE and MSCompE applicants.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'Unofficial transcripts and one mandatory LOR are required for both the MSEE and MSCompE degree applicants.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f26', 'deadline', 'Department page Fall 2026 application window', 'Department admissions page: the application window for Fall 2026 is October 1, 2025 to February 1, 2026. This disagrees in cycle/year with the university master''s-degrees page for Fall 2027, quoted separately; both are reported, no winner is chosen.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'The application window for Fall 2026 will be from October 1, 2025 to February 1, 2026.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f27', 'deadline', 'Department Cal State Apply date for that window', 'Department page: complete the university Cal State Apply application by February 1, 2026.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'Complete the University Online Application via Cal State Apply – Must be completed by February 1, 2026.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f28', 'deadline', 'Department official documents date', 'Department page: official test scores and transcripts must be received by February 15, 2026.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'Send official test scores and transcripts to Graduate Admissions – Must be received by February 15, 2026.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f29', 'deadline', 'Scholarship consideration date', 'Department page: applications received after January 15 will not be considered for resident tuition-waiver scholarships.', 'https://electrical.sdsu.edu/programs/graduate/admission', 'Applications received after JANUARY 15th will not be considered for scholarships.', '2026-11-14T07:29:27.152108Z');
