INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f47', 'faculty', 'Dr. Tharm Ratnarajah', 'SDSU ECE faculty profile: research interests include signal processing and information-theoretic aspects of beyond 5G cellular networks, full-duplex radio, mmWave communications, random matrix theory, big data analytics and machine learning for wireless networks, statistical and array signal processing, physical-layer', 'https://electrical.sdsu.edu/people/tharm-ratnarajah', 'research interests include signal processing and information-theoretic aspects of beyond 5G cellular networks, full-duplex radio, mmWave communications, random matrix theory, big data analytics and machine learning for wireless networks, statistical and array signal processing, physical-layer', '2026-11-18T12:00:00.000Z');
