INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f51', 'faculty', 'Dr. Satish Sharma', 'SDSU ECE faculty profile: research interests are primarily in antenna theory and design, microwave passive devices, and novel electromagnetic materials. He received NSF''s prestigious CAREER award in the year 2009. He received the IEEE AP-Society''s prestigious Harold A.', 'https://electrical.sdsu.edu/people/satish-sharma', 'research interests are primarily in antenna theory and design, microwave passive devices, and novel electromagnetic materials. He received NSF''s prestigious CAREER award in the year 2009. He received the IEEE AP-Society''s prestigious Harold A.', '2026-11-18T12:00:00.000Z');
