INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f61', 'faculty', 'Flavio Ponzina', 'Profile: research interests include HW-SW co-design for edge AI, unsupervised/ensemble/distributed learning, energy-efficient systems, and processing in-memory.', 'https://electrical.sdsu.edu/people/flavio-ponzina', 'research interests include HW-SW co-design optimizations for edge AI, unsupervised, ensemble, and distributed learning, energy-efficient systems, and processing in-memory acceleration on emerging memory technologies.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f62', 'faculty', 'Computer Networks faculty', 'Course-guidelines PDF lists Computer Networks faculty. Department-wide ECE areas, used here because they teach the CompE depth area.', 'https://electrical.sdsu.edu/_resources/files/guidelineforcourses-ece-5-11-26.pdf', 'Computer Networks: Dr. Sunil Kumar, Dr. Yusuf Ozturk, Dr. Christopher Paolini, Dr. Mahasweta Sarkar, Dr. Junfei Xie', '2026-11-19T05:30:26.654Z');
