INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f66', 'overview', 'Catalog heading and plan codes', 'The 2026-2027 University Catalog program heading is Computer Engineering, M.S. The page also lists Academic Plan Codes for SDSU Global Campus and SDSU Global Campus-Flex.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Computer Engineering, M.S. (Major Code: 09094) (Academic Plan Code: 445003MSS) (Academic Plan Code: 445004MSE - SDSU Global Campus) (Academic Plan Code: 445004MSF - SDSU Global Campus-Flex)', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f67', 'overview', 'Four focus areas', 'The department offers the M.S. in computer engineering with graduate courses in Computer Networks, Embedded Systems, VLSI systems, and Machine Learning/Scientific Computing.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'The program seeks to provide students with core knowledge through graduate courses offered in the four focus areas of Computer Networks, Embedded Systems, Very Large-Scale Integration (VLSI) systems and Machine Learning/ Scientific Computing.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f68', 'requirement', 'Admission GPA by student type', 'The catalog asks for a bachelor''s in computer engineering, computer science, electrical engineering, or a closely related area, with a GPA of 3.0 or better for international students and 2.85 for domestic students, on a 4.0 scale. An earlier department-page fact described the 2.85 figure as applying to the last 60 semester units of technical coursework; this catalog sentence does not add that restriction. Both quotes are kept and no winner is chosen.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Bachelor''s degree in computer engineering, computer science, electrical engineering, or closely related areas with a grade point average of 3.0 or better for international students and a minimum grade point average of 2.85 for domestic students, based on 4.0 scale;', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f69', 'requirement', 'International English scores', 'International students must have a minimum TOEFL score of 85 or a minimum IELTS score of 6.5.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'A minimum TOEFL score of 85 or a minimum IELTS score of 6.5 for international students;', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f71', 'requirement', 'One letter of recommendation', 'The catalog admissions list requires one letter of recommendation.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'One letter of recommendation.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f73', 'requirement', 'Plan A thesis or Plan B project', 'Students must have a graduate-advisor-approved program of study that meets core, depth, and breadth requirements, and must choose Plan A (Thesis) or Plan B (Project).', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Students must also choose one of two pathways: Plan A (Thesis) or Plan B (Project), for degree completion.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f74', 'requirement', 'Depth and breadth areas', 'Students select a depth area and complete approved courses from that area, plus a set of approved courses from other areas in consultation with the graduate advisor. In this paragraph the page names the areas Computer Networks, Embedded operating systems, Machine Learning and Scientific Computing, and VLSI Circuit Design.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'The offered areas are Computer Networks, Embedded operating systems, Machine Learning and Scientific Computing and VLSI Circuit Design.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f75', 'requirement', 'Computer Networks core choice', 'For the Computer Networks area, students take one of COMPE 560, E E 602, or E E 603 as core, and at least 3 courses from the Computer Networks depth list.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Students are required to take one of these courses as core: COMPE 560 - Computer and Data Networks Units: 3 or E E 602 - Stochastic Signals and Systems Units: 3 or E E 603 - Engineering Optimization Units: 3', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f76', 'requirement', 'Embedded Systems core', 'For Embedded Systems, students take the core course COMPE 571 and at least 3 courses from that area''s depth list.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Embedded Systems Students are required to take the core course: COMPE 571 - Embedded Operating Systems Units: 3', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f77', 'requirement', 'Machine Learning and Scientific Computing core', 'For Machine Learning and Scientific Computing, students take the core course COMPE 510 and at least 3 courses from that area''s depth list. The catalog text repeats the word ''the'' in this sentence; the quote is kept as written.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Machine Learning and Scientific Computing Students are required to take the the core course: COMPE 510 - Machine Learning for Engineers Units: 3', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f78', 'requirement', 'VLSI Systems core', 'For VLSI Systems, students take the core course COMPE 572 and at least 3 courses from that area''s depth list.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'VLSI Systems Students are required to take the core course: COMPE 572 - VLSI Circuit Design Units: 3', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f79', 'requirement', 'Depth-course minimum of three', 'In each depth area, the page says students must take at least 3 of the listed depth courses.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Students must take at least 3 of these courses:', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f80', 'requirement', 'Plan A thesis units', 'Plan A students take COMPE 797 Research for 6 units and COMPE 799A Thesis for 3 units. Credit for COMPE 797 is given only after COMPE 799A is successfully completed.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Requirements for Plan A (Thesis) Students are required to take COMPE 797 - Research Units: 3-6 (6 units) Cr/NC/RP COMPE 799A - Thesis Units: 3 (3 units)', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f81', 'requirement', 'COMPE 797 credit after thesis', 'Credit for COMPE 797 is given only after the student successfully completes COMPE 799A.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Credit for COMPE 797 will be given only after successfully completing COMPE 799A.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f82', 'requirement', 'Plan B project timing and course', 'Plan B students may enroll in COMPE 798 after 18 units, but must do so in the semester immediately after completing 27 units. The project is 3 units of COMPE 798 Special Study, graded Cr/NC/RP. The department determines the evaluation process, enforced by the graduate advisor.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'Students may enroll in the project course, COMPE 798 after completion of 18 units, but must do so in the semester immediately following completion of 27 units.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f83', 'requirement', 'Remaining units from depth or breadth', 'Remaining units may come from the selected depth area or from breadth areas; the page then lists approved courses.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'The remaining units can be taken from the selected depth area or from breadth areas. The following courses have been approved:', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f85', 'course', 'E E 602', 'E E 602 Stochastic Signals and Systems, SDSU 2026-27 catalog: Random signals, correlation functions, power spectral densities, the Gaussian process, narrow band processes. Applications to communication systems.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91984', 'Random signals, correlation functions, power spectral densities, the Gaussian process, narrow band processes. Applications to communication systems.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f86', 'course', 'E E 603', 'E E 603 Engineering Optimization, SDSU 2026-27 catalog: Unconstrained and constrained optimization problems. Convex sets, functions, analysis, and optimization problems. Least-squares, linear, and quadratic programs. Optimality conditions, duality theory.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93102', 'Unconstrained and constrained optimization problems. Convex sets, functions, analysis, and optimization problems. Least-squares, linear, and quadratic programs. Optimality conditions, duality theory.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f90', 'course', 'COMPE 797', 'COMPE 797 Research, SDSU 2026-27 catalog: Open only to Plan A Thesis. Research in computer engineering.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93568', 'Open only to Plan A Thesis. Research in computer engineering.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f91', 'course', 'COMPE 799A', 'COMPE 799A Thesis, SDSU 2026-27 catalog: Preparation of a thesis for the Master''s degree.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93569', 'Preparation of a thesis for the Master''s degree.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f92', 'course', 'COMPE 798', 'Plan B project course, Special Study, 3 units, graded Cr/NC/RP.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'COMPE 798 - Special Study Units: 3 (3 units) Cr/NC/RP', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f93', 'course', 'COMPE 561', 'COMPE 561 Windows Database and Web Programming, SDSU 2026-27 catalog: Programming applications involving file systems, relational databases, Structured Query Language (SQL), ADO.NET, client-server architecture, multithreading sockets, web servers, web browsers, web services, ASP.NET, Hypertext Markup Language (HTML), and Extensible Markup Language (XML).', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88923', 'Programming applications involving file systems, relational databases, Structured Query Language (SQL), ADO.NET, client-server architecture, multithreading sockets, web servers, web browsers, web services, ASP.NET, Hypertext Markup Language (HTML), and Extensible Markup Language (XML).', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f94', 'course', 'COMPE 565', 'COMPE 565 Multimedia Communication Systems, SDSU 2026-27 catalog: Design and implementation of multimedia communication systems. Image compression, JPEG, VQ, cell-B standards. Video and audio compression standards, MPEG, MPEG-2, H.26X, G.72X. Data storage systems and multimedia requirements. Networking requirements and networks as multimedia carriers.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88924', 'Design and implementation of multimedia communication systems. Image compression, JPEG, VQ, cell-B standards. Video and audio compression standards, MPEG, MPEG-2, H.26X, G.72X. Data storage systems and multimedia requirements. Networking requirements and networks as multimedia carriers.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f95', 'course', 'COMPE 660', 'COMPE 660 High Speed Networks: Design Principles and Recent Advances, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): COMPE 560 or Graduate Standing Provides students with knowledge of recent developments in area of computer networks. Current research in high speed computer networks. Formerly numbered: E E 660', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91997', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): COMPE 560 or Graduate Standing Provides students with knowledge of recent developments in area of computer networks. Current research in high speed computer networks. Formerly numbered: E E 660', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f96', 'course', 'COMPE 662', 'COMPE 662 Wireless Sensor Networks, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): COMPE 560 or Graduate Standing Sensor platforms, wireless channel characteristics, time synchronization, medium access control, topology control, routing protocols, localization, coverage and placement', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91998', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): COMPE 560 or Graduate Standing Sensor platforms, wireless channel characteristics, time synchronization, medium access control, topology control, routing protocols, localization, coverage and placement', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f97', 'course', 'COMPE 665', 'COMPE 665 Multimedia Wireless Networks, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): COMPE 560 or Graduate Standing Cross-layer protocol design, multimedia QoS-aware 4G, 5G, CRN, WLAN networks;', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91999', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): COMPE 560 or Graduate Standing Cross-layer protocol design, multimedia QoS-aware 4G, 5G, CRN, WLAN networks;', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f99', 'course', 'COMPE 570', 'COMPE 570 VLSI System Design, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): COMPE 470 with a grade of C (2.0) or better.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88925', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): COMPE 470 with a grade of C (2.0) or better.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f100', 'course', 'E E 503', 'E E 503 Biomedical Instrumentation, SDSU 2026-27 catalog: Note: Prerequisites will be enforced in all undergraduate electrical engineering courses numbered 100 through 596. A copy of an official transcript will be accepted as proof. For corequisites, an enrollment confirmation form will be accepted.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=89150', 'Note: Prerequisites will be enforced in all undergraduate electrical engineering courses numbered 100 through 596. A copy of an official transcript will be accepted as proof. For corequisites, an enrollment confirmation form will be accepted.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f101', 'course', 'E E 522', 'E E 522 Digital Control Systems, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 420 . Digital controls systems;', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=89151', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 420 . Digital controls systems;', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f102', 'course', 'E E 533', 'E E 533 Neuromorphic Computing, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 330 with a grade of C (2.0) or better, or graduate standing. Ultra-low power computing electronics concepts mimicking computing by biological neurons.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93426', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 330 with a grade of C (2.0) or better, or graduate standing. Ultra-low power computing electronics concepts mimicking computing by biological neurons.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f103', 'course', 'COMPE 671', 'COMPE 671 VLSI Testing, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): COMPE 470 or Graduate Standing Theory and techniques for testing VLSI circuits and systems.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93103', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): COMPE 470 or Graduate Standing Theory and techniques for testing VLSI circuits and systems.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f104', 'course', 'E E 530', 'E E 530 Analog Integrated Circuit Design, SDSU 2026-27 catalog: Advanced treatment of transistor pairs, device mismatches, differential amplifiers, current mirrors, active loads, level shifting, and output stages. Parasitic and distributed device parameters. Economics of IC fabrication and impact on design.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=89152', 'Advanced treatment of transistor pairs, device mismatches, differential amplifiers, current mirrors, active loads, level shifting, and output stages. Parasitic and distributed device parameters. Economics of IC fabrication and impact on design.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f105', 'course', 'E E 634', 'E E 634 RF Circuit Design, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 540 . RF component and circuit design in frequency domain and scattering parameter terms.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91986', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 540 . RF component and circuit design in frequency domain and scattering parameter terms.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f106', 'course', 'E E 674', 'E E 674 Signal and Power Integrity, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 440 and COMPE 572 . Interconnect and power distribution network design in very-large- scale integration systems packaging. High-speed transmission lines and crosstalk, macromodeling of interconnects.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=92001', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 440 and COMPE 572 . Interconnect and power distribution network design in very-large- scale integration systems packaging. High-speed transmission lines and crosstalk, macromodeling of interconnects.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f107', 'course', 'COMPE 798', 'Listed as a depth-area and/or remaining-units approved course on the 2026-2027 catalog program page.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12546', 'COMPE 798 - Special Study Units: 3', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f108', 'course', 'E E 502', 'E E 502 Electronic Devices for Rehabilitation, SDSU 2026-27 catalog: Two lectures and three hours of laboratory. Prerequisite(s): E E 330 with a grade of C- (1.7) or better. Recent developments in electronic assistive devices and microcomputers for persons with various disabilities; assessment of disabled persons for suitable technological assistive devices.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=89149', 'Two lectures and three hours of laboratory. Prerequisite(s): E E 330 with a grade of C- (1.7) or better. Recent developments in electronic assistive devices and microcomputers for persons with various disabilities; assessment of disabled persons for suitable technological assistive devices.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f109', 'course', 'E E 540', 'E E 540 Microwave Devices and Systems, SDSU 2026-27 catalog: Applications of Maxwell''s equations to wave propagation. Microwave network parameters; guided wave transmission and reflection. Design of filters, couplers, power dividers and amplifiers. Applications in radar and telecommunications systems.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=89154', 'Applications of Maxwell''s equations to wave propagation. Microwave network parameters; guided wave transmission and reflection. Design of filters, couplers, power dividers and amplifiers. Applications in radar and telecommunications systems.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f110', 'course', 'E E 558', 'E E 558 Digital Communications, SDSU 2026-27 catalog: Design of baseband digital communication systems; noise characterization, sampling, quantization, matched filter receivers, bit-error performance, inter-symbol interference, link budget analysis.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=89156', 'Design of baseband digital communication systems; noise characterization, sampling, quantization, matched filter receivers, bit-error performance, inter-symbol interference, link budget analysis.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f111', 'course', 'E E 581', 'E E 581 Power System Dynamics, SDSU 2026-27 catalog: Three-phase faults, symmetrical components, unsymmetrical faults, protective relay operating principles, economic dispatch of thermal power generation units, power system controls, voltage and power stability.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=89157', 'Three-phase faults, symmetrical components, unsymmetrical faults, protective relay operating principles, economic dispatch of thermal power generation units, power system controls, voltage and power stability.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f112', 'course', 'E E 584', 'E E 584 Power Electronics, SDSU 2026-27 catalog: Design and analysis of power electronic devices. Permanent-magnet and pulse-width modulation ac-to-ac converters, dc-to-ac inverters, power electronics applications, power semiconductor switches, and switch-mode power supplies. Formerly numbered: Electrical Engineering 484.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=89158', 'Design and analysis of power electronic devices. Permanent-magnet and pulse-width modulation ac-to-ac converters, dc-to-ac inverters, power electronics applications, power semiconductor switches, and switch-mode power supplies. Formerly numbered: Electrical Engineering 484.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f113', 'course', 'E E 586', 'E E 586 Distributed Energy Resources and Smart Grid Technologies, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): Credit or concurrent registration in E E 480 ; Graduate standing.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93162', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): Credit or concurrent registration in E E 480 ; Graduate standing.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f114', 'course', 'E E 601', 'E E 601 Linear System Theory and Design, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 420 . State models and solutions of the state equations, stability, controllability and observability, realizability and minimal realizations, linear state and output feedback control, introduction', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91983', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 420 . State models and solutions of the state equations, stability, controllability and observability, realizability and minimal realizations, linear state and output feedback control, introduction', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f115', 'course', 'E E 641', 'E E 641 RF Wireless Systems, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 440 , E E 558 , E E 602 .', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91987', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 440 , E E 558 , E E 602 .', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f116', 'course', 'E E 645', 'E E 645 Antennas and Propagation, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 440 . Antenna radiation mechanism, antenna types, fundamental antenna parameters, microstrip patch antennas, theory and design of various array and wire antennas, antenna measurement techniques and', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91988', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 440 . Antenna radiation mechanism, antenna types, fundamental antenna parameters, microstrip patch antennas, theory and design of various array and wire antennas, antenna measurement techniques and', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f117', 'course', 'E E 650', 'E E 650 Modern Communication Theory, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 558 and E E 602 . Wireless digital communication; bandpass modulation and demodulation, multiple access techniques, broadband signaling techniques, spread spectrum techniques;', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91989', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 558 and E E 602 . Wireless digital communication; bandpass modulation and demodulation, multiple access techniques, broadband signaling techniques, spread spectrum techniques;', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f118', 'course', 'E E 652', 'E E 652 Principles and Applications of Information Theory, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 558 and E E 602 . Information measure of data sources; Shannon''s theorem and capacity of communication links; rate-distortion theory and performance of source codes.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91990', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 558 and E E 602 . Information measure of data sources; Shannon''s theorem and capacity of communication links; rate-distortion theory and performance of source codes.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f119', 'course', 'E E 653', 'E E 653 Coding Theory, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 558 . Error control for digital information; arithmetic of Galois fields; block, cyclic, convolutional and turbo encoding and decoding; applications in digital communication and computer systems.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91991', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 558 . Error control for digital information; arithmetic of Galois fields; block, cyclic, convolutional and turbo encoding and decoding; applications in digital communication and computer systems.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f120', 'course', 'E E 654', 'E E 654 Adaptive Filter Design, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 450 and E E 602 . Constrained and unconstrained Wiener filters. Performance surfaces and gradient-based search methods. LMS and RLS algorithms. Lattice filters.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91992', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 450 and E E 602 . Constrained and unconstrained Wiener filters. Performance surfaces and gradient-based search methods. LMS and RLS algorithms. Lattice filters.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f121', 'course', 'E E 655', 'E E 655 Modem Design, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 450 and E E 558 . System level and DSP design of modems for wireless and wireline communications. Study modems for QAM, OFDM, CDMA, and T-1 modulation.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91993', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 450 and E E 558 . System level and DSP design of modems for wireless and wireline communications. Study modems for QAM, OFDM, CDMA, and T-1 modulation.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f122', 'course', 'E E 658', 'E E 658 Advanced Digital Signal Processing, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 450 and E E 602 . Advanced topics in FIR and IIR filter design. Quantization effects in digital filters. Sigma-delta modulation. Signal modeling. Parametric and non-parametric spectral estimation.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91996', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 450 and E E 602 . Advanced topics in FIR and IIR filter design. Quantization effects in digital filters. Sigma-delta modulation. Signal modeling. Parametric and non-parametric spectral estimation.', '2026-11-19T05:30:26.654Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('13-20261118', 'f123', 'course', 'E E 684', 'E E 684 Advanced Power Electronics, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 584 and E E 601 . Advanced modeling strategies for bidirectional converters, DC/ DC converters, design and integration of power electronics interfaces into smart girds, multi-level inverters', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=92002', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): E E 584 and E E 601 . Advanced modeling strategies for bidirectional converters, DC/ DC converters, design and integration of power electronics interfaces into smart girds, multi-level inverters', '2026-11-19T05:30:26.654Z');
