INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f1', 'overview', 'M.S. study areas and culminating options', 'Department degree-programs page: the M.S. includes advanced study and research in areas such as AI, machine learning, and software engineering, with a thesis project or a comprehensive exam.', 'https://cs.sdsu.edu/computer-science-degree-programs/', 'Graduates of the Master of Science in Computer Science program at San Diego State University engage in advanced study and research in various computing domains, including artificial intelligence, machine learning, and software engineering.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f2', 'requirement', 'Thesis or comprehensive exam', 'Students may complete a thesis project with faculty or a comprehensive exam.', 'https://cs.sdsu.edu/computer-science-degree-programs/', 'Students may choose to either complete a thesis project, collaborating closely with faculty on innovative research that addresses real-world problems, or opt for a comprehensive exam to fulfill their degree requirements.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f3', 'requirement', 'No letters, SOP, or resumes', 'University master''s-degrees page, Computer Science, M.S. section: the department does not require or consider letters of recommendation, statements of purpose, or resumes.', 'https://admissions.sdsu.edu/grad-programs/masters', 'The Computer Science Department does not require nor take into consideration letters of recommendation, statements of purpose, or resumes.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f4', 'deadline', 'Fall 2027 Cal State Apply', 'Computer Science, M.S. section: Fall 2027 Cal State Apply deadline is February 1.', 'https://admissions.sdsu.edu/grad-programs/masters', 'resumes. Fall 2027 Deadlines Submit Cal State Apply Application: February 1', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f5', 'deadline', 'Fall 2027 documents', 'Computer Science, M.S. section: documents to Graduate Admissions are due February 15.', 'https://admissions.sdsu.edu/grad-programs/masters', 'Submit Documents to Graduate Admissions: February 15 Spring 2027 Deadlines Not currently accepting applications for spring semester Contact Information Department of Computer Science', '2026-11-14T07:29:27.152108Z');
