INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f34', 'faculty', 'Joann Qiongna Chen', 'SDSU CS faculty profile: research interests center around Differential Privacy (DP), privacy-enhancing technologies, and privacy in machine learning.', 'https://cs.sdsu.edu/people/joann-chen/', 'research interests center around Differential Privacy (DP), privacy-enhancing technologies, and privacy in machine learning.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f35', 'faculty', 'Salimeh Sekeh', 'SDSU CS faculty profile: Areas of Expertise Machine Learning, Computer Vision, Artificial Intelligence, Large Scale Data Science', 'https://cs.sdsu.edu/people/salimeh-sekeh/', 'Areas of Expertise Machine Learning, Computer Vision, Artificial Intelligence, Large Scale Data Science', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f36', 'faculty', 'Jianshu Liu', 'SDSU CS faculty profile: research interest lies in performance and scalability analysis of various cloud systems, with the aim of achieving good performance and high resource efficiency for evolving systems in cloud environments. His works appear in IPDPS, ICDCS, Middleware, SoCC, etc.', 'https://cs.sdsu.edu/people/jianshu-liu/', 'research interest lies in performance and scalability analysis of various cloud systems, with the aim of achieving good performance and high resource efficiency for evolving systems in cloud environments. His works appear in IPDPS, ICDCS, Middleware, SoCC, etc.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f37', 'faculty', 'Yifan Zhang', 'SDSU CS faculty profile: research interests encompass security and privacy concerns within software supply chains, mobile systems, and Internet of Things (IoT) systems. I am committed to identifying novel attack vectors and emerging privacy issues in these domains.', 'https://cs.sdsu.edu/people/yifan-zhang/', 'research interests encompass security and privacy concerns within software supply chains, mobile systems, and Internet of Things (IoT) systems. I am committed to identifying novel attack vectors and emerging privacy issues in these domains.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f38', 'faculty', 'Tao Xie', 'SDSU CS faculty profile: Areas of Expertise High Performance Computing, Storage Systems, Cluster and Grid Computing, Parallel Processing, Distributed Systems, Real- Time/Embedded Systems, Dynamic Resource Management, Performance Evaluation.', 'https://cs.sdsu.edu/people/tao-xie', 'Areas of Expertise High Performance Computing, Storage Systems, Cluster and Grid Computing, Parallel Processing, Distributed Systems, Real- Time/Embedded Systems, Dynamic Resource Management, Performance Evaluation.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f39', 'overview', 'Catalog heading', 'The 2026-2027 University Catalog program heading is Computer Science, M.S., with Major Code 07011 and Academic Plan Code 773801MSS.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Computer Science, M.S. (Major Code: 07011) (Academic Plan Code: 773801MSS)', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f40', 'requirement', 'Classified graduate standing required', 'The page requires classified graduate standing and the basic master''s-degree requirements described elsewhere in the catalog, plus the departmental requirements on this page. This page does not itself spell out those general classified-standing rules.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'In addition to meeting the requirements for classified graduate standing and the basic requirements for the master''s degree as described in Requirements for Master''s Degrees , the student must meet the following departmental requirements:', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f41', 'requirement', 'Minimum 31 units', 'Students must complete a minimum of 31 units of 500-, 600-, and 700-level courses selected with advisor approval. Earlier department-page facts did not state a unit total.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Complete a minimum of 31 units of 500-, 600-, and 700-level courses selected with the approval of the advisor.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f42', 'requirement', 'CS 798 internship units may be added to the 31', 'One to three units of Computer Science 798 may be added to the 31-unit minimum when used for an internship or practical training.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'One to three units of Computer Science 798 may be added to the 31 minimum units required, when used for an internship or practical training.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f43', 'requirement', 'At least 24 units from computer science and mathematics', 'All programs must include at least 24 units chosen from computer science and mathematics.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'All programs must include at least 24 units chosen from computer science and mathematics.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f45', 'requirement', 'Plan A thesis GPA of 3.3 (second statement)', 'In the Advancement to Candidacy paragraph, the same page says selecting Plan A is contingent on a minimum 3.3 GPA in courses applicable to the master''s degree and on finding a full-time computer science faculty member to supervise the thesis. The earlier paragraph on this page said 3 GPA. Both sentences are quoted and no winner is chosen.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Selecting Plan A is contingent upon having a minimum 3.3 GPA in courses applicable to the master''s degree and finding a full-time computer science faculty member to supervise the thesis.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f46', 'requirement', 'Advancement to candidacy', 'All students must satisfy the general catalog requirements for advancement to candidacy and must select Plan A (Thesis) or Plan B (Comprehensive Examinations).', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'All students must satisfy the general requirements for advancement to candidacy as described in Requirements for Master''s Degrees .', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f47', 'requirement', 'Required courses 16 units', 'Both Plan A and Plan B require the same 16 units of required courses.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Required Courses (16 units) The following courses are required for both Plan A and Plan B.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f48', 'course', 'CS 514', 'CS 514 Database Theory and Implementation, SDSU 2026-27 catalog: Storage structures and access techniques. Relational model, relational algebra and calculus, normalization of relations, hierarchical and network models. Current database systems.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88947', 'Storage structures and access techniques. Relational model, relational algebra and calculus, normalization of relations, hierarchical and network models. Current database systems.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f49', 'course', 'CS 549', 'CS 549 Machine Learning, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 210 and MATH 254 . Algorithms and computer methods for machine learning.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93050', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 210 and MATH 254 . Algorithms and computer methods for machine learning.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f50', 'course', 'CS 576', 'CS 576 Computer Networks and Distributed Systems, SDSU 2026-27 catalog: Basic networking concepts to include seven-layer reference model, transmission media, addressing, subnetting and supernetting, networking devices, LANs and WANs, internetworking, distributed processing, and client-server model.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88965', 'Basic networking concepts to include seven-layer reference model, transmission media, addressing, subnetting and supernetting, networking devices, LANs and WANs, internetworking, distributed processing, and client-server model.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f51', 'course', 'CS 577', 'CS 577 Principles and Techniques of Data Science, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): STAT 119 or STAT 250; and CS 210 , MATH 254 Data classification, cleaning, common representation and operations, dimensionality reduction, hypothesis testing, life cycle, regression, statistical', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93053', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): STAT 119 or STAT 250; and CS 210 , MATH 254 Data classification, cleaning, common representation and operations, dimensionality reduction, hypothesis testing, life cycle, regression, statistical', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f52', 'course', 'CS 601', 'CS 601 Graduate Seminar, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): Admission to the M.S. degree program in Computer Science.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93390', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): Admission to the M.S. degree program in Computer Science.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f53', 'course', 'CS 660', 'CS 660 Algorithm Analysis and Design, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 460 . Algorithm design techniques. Approximation algorithms and reductions among NP-complete problems. Greedy and divide and conquer algorithms. Linear and dynamic programming.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91548', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 460 . Algorithm design techniques. Approximation algorithms and reductions among NP-complete problems. Greedy and divide and conquer algorithms. Linear and dynamic programming.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f54', 'requirement', 'Plan A elective units', 'Plan A students take 9 units of computer science electives from groups CSY, ISY, and DSC, including at least 6 units of 600- or 700-level computer science courses, excluding CS 790 through CS 799. Three units of 600-level mathematics and statistics from group MST may replace one 600-level computer science course. No more than 3 units of CS 696 and CS 798 can count toward those 9 elective units.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', '9 units of computer science elective courses from the groups CSY, ISY, and DSC listed below of which at least 6 units must be computer science 600-level or 700-level courses, excluding CS 790 through CS 799.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f55', 'requirement', 'Plan A MST substitution and special-topics cap', 'Three units of 600-level mathematics and statistical courses from group MST may replace one 600-level computer science course. No more than 3 units of CS 696 and CS 798 can count toward the 9 Plan A elective units.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Three units of 600-level mathematics and statistical courses from the group MST listed below may replace one 600-level computer science course. No more than 3 units of CS 696 and CS 798 can be counted towards the 9 units of elective courses.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f56', 'requirement', 'Plan A thesis and research units', 'Plan A students must take 3 units of CS797-Research and 3 units of CS799A-Thesis. The thesis requires a report and a defense. CS 799B Thesis or Project Extension, 0 units, may be used if needed.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Plan A students must take 3 units of CS797-Research and 3 units of CS799A-Thesis. The thesis requires report writing and defense.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f57', 'requirement', 'Plan B elective units', 'Plan B students take 15 units from groups CSY, ISY, and DSC, including at least 12 units of 600- or 700-level computer science courses, excluding CS 790 through CS 799. Three units of 600-level mathematics from group MST may replace three units of 600-level computer science. No more than 3 units from the Special Topics Courses section count toward those 12 units.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', '15 units from groups CSY, ISY, DSC listed below with at least 12 units of which must be computer science 600 or 700-level courses, excluding CS 790 through CS 799.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f58', 'requirement', 'Plan B comprehensive exam', 'Plan B students must pass a comprehensive exam covering the required courses and must finish the required courses before taking the exam.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Plan B students must pass the comprehensive exam covering the required courses. Students must complete the required courses before taking the exam.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f59', 'requirement', 'International Plan B progress rule', 'Full-time international students on Plan B who have finished their required coursework must show progress in at least two areas of study each semester until they have completed all but one, either by qualifying examinations or by additional coursework preapproved by the graduate adviser.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Full-time international students on Plan B who have completed all their required coursework must show progress in at least two areas of study each semester (until they have completed all but one).', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f60', 'requirement', 'Elective area 600-level unit reminders', 'Electives may come from one or more of the listed areas. In this later paragraph the page says six units must be Computer Sciences 600-level courses for Plan A students, and ''12 Twelve'' units must be Computer Science 600-level courses for Plan B students. The wording is quoted as written.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'Six units must be Computer Sciences 600-level courses (for Plan A students). 12 Twelve units must be Computer Science 600-level courses (for Plan B students).', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f61', 'course', 'CS 797', 'CS 797 Research, SDSU 2026-27 catalog: Research in computer science.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91557', 'Research in computer science.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f62', 'course', 'CS 799A', 'CS 799A Thesis or Project, SDSU 2026-27 catalog: Preparation of a project or thesis for the master''s degree.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91559', 'Preparation of a project or thesis for the master''s degree.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f63', 'course', 'CS 799B', 'CS 799B Thesis or Project Extension, SDSU 2026-27 catalog: Registration required in any semester or term following assignment of RP in Course 799A in which the student expects to use the facilities and resources of the university; also student must be registered in the course when the completed thesis or project is granted final approval.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91560', 'Registration required in any semester or term following assignment of RP in Course 799A in which the student expects to use the facilities and resources of the university; also student must be registered in the course when the completed thesis or project is granted final approval.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f64', 'course', 'CS 562', 'CS 562 Automata Theory, SDSU 2026-27 catalog: Definition of finite automata. Classification of finite automaton definable languages. Minimization of finite automata. Nondeterministic finite automata. Sequential machines with output. Regular sets and expressions. Introduction to grammars.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88961', 'Definition of finite automata. Classification of finite automaton definable languages. Minimization of finite automata. Nondeterministic finite automata. Sequential machines with output. Regular sets and expressions. Introduction to grammars.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f65', 'course', 'CS 572', 'CS 572 Microprocessor Architecture, SDSU 2026-27 catalog: Architecture of state-of-the-art microprocessor. Internal pipeline, internal cache, external cache, and memory management. Programming a uniprocessor. Communication among computers in a distributed environment. Architecture and programming of a multiprocessor system.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88963', 'Architecture of state-of-the-art microprocessor. Internal pipeline, internal cache, external cache, and memory management. Programming a uniprocessor. Communication among computers in a distributed environment. Architecture and programming of a multiprocessor system.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f66', 'course', 'CS 574', 'CS 574 Computer Security, SDSU 2026-27 catalog: Principles of computer security and application of principles to operating systems, database systems, and computer networks. Topics include encryption techniques, access controls, and information flow controls.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88964', 'Principles of computer security and application of principles to operating systems, database systems, and computer networks. Topics include encryption techniques, access controls, and information flow controls.', '2026-11-18T12:00:00.000Z');
