INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f81', 'course', 'CS 556', 'CS 556 Robotics, SDSU 2026-27 catalog: Spatial descriptions and transformations. Kinematics and inverse kinematics of robots. Robotic programming and simulation environments to include Matlab Robotics Toolbox. Mobile robots. Trajectory tracking and control. Path planning.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88957', 'Spatial descriptions and transformations. Kinematics and inverse kinematics of robots. Robotic programming and simulation environments to include Matlab Robotics Toolbox. Mobile robots. Trajectory tracking and control. Path planning.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f82', 'course', 'CS 559', 'CS 559 Computer Vision, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 210 and MATH 254 . Algorithms and computer methods for processing of images, edge detection and filtering in spatial domain, FFT and filtering, frequency domain analysis of images, image compression', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88959', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 210 and MATH 254 . Algorithms and computer methods for processing of images, edge detection and filtering in spatial domain, FFT and filtering, frequency domain analysis of images, image compression', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f83', 'course', 'CS 561', 'CS 561 Deep Learning for Natural Language Processing, SDSU 2026-27 catalog: Approaches on deep neural networks. Common tasks, modern programming frameworks, and state-of-the-art models.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93052', 'Approaches on deep neural networks. Common tasks, modern programming frameworks, and state-of-the-art models.', '2026-11-18T12:00:00.000Z');
