INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f85', 'course', 'CS 653', 'CS 653 Data Mining, SDSU 2026-27 catalog: Foundations of data mining and knowledge discovery. Diverse methods, algorithms, design techniques and application practice including statistical and Bayesian methods, pattern recognition, clustering, knowledge discovery in data sets, machine learning, neural networks, rough and fuzzy sets.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91545', 'Foundations of data mining and knowledge discovery. Diverse methods, algorithms, design techniques and application practice including statistical and Bayesian methods, pattern recognition, clustering, knowledge discovery in data sets, machine learning, neural networks, rough and fuzzy sets.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f86', 'course', 'CS 656', 'CS 656 Advanced Robotics, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 556 . Robot kinematics to include Jacobians and velocity. Robot dynamics and joint-space/task-space tracking and control. Genetic algorithms and clustering for inverse kinematics.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91546', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 556 . Robot kinematics to include Jacobians and velocity. Robot dynamics and joint-space/task-space tracking and control. Genetic algorithms and clustering for inverse kinematics.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f87', 'course', 'CS 657', 'CS 657 Intelligent Systems, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 450 and CS 460 . Genetic and evolutionary algorithms and applications, fuzzy logic and approximate reasoning, rule-based inference engines, intelligent path planning and applications to robotics', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91547', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 450 and CS 460 . Genetic and evolutionary algorithms and applications, fuzzy logic and approximate reasoning, rule-based inference engines, intelligent path planning and applications to robotics', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f88', 'course', 'CS 659', 'CS 659 Visual Perception and Learning, SDSU 2026-27 catalog: Computer algorithms and methods for computer vision. Edge detection, histogram of gradients, image filtering, machine learning, robust matching and model fitting, scale-invariant feature transform, stereo vision and 3D scene reconstruction. Object detection, recognition, and visual tracking.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93100', 'Computer algorithms and methods for computer vision. Edge detection, histogram of gradients, image filtering, machine learning, robust matching and model fitting, scale-invariant feature transform, stereo vision and 3D scene reconstruction. Object detection, recognition, and visual tracking.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f89', 'course', 'CS 652', 'CS 652 Foundations of Deep Learning, SDSU 2026-27 catalog: DL Optimization, DL Generalization, Neural Tangent Kernels, Robustness for DL, Deep Generative Models, Self-supervised DL, Transformers, Domain adaptation and generalization, Explainable DL, and Meta-Learning. Project-oriented implementing advanced algorithms.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93579', 'DL Optimization, DL Generalization, Neural Tangent Kernels, Robustness for DL, Deep Generative Models, Self-supervised DL, Transformers, Domain adaptation and generalization, Explainable DL, and Meta-Learning. Project-oriented implementing advanced algorithms.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f90', 'course', 'CS 654', 'CS 654 Reinforcement Learning, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 549, graduate standing, or consent of the instructor. Reinforcement Learning studies sequential decision-making to maximize cumulative rewards.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93573', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 549, graduate standing, or consent of the instructor. Reinforcement Learning studies sequential decision-making to maximize cumulative rewards.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f91', 'course', 'CS 668', 'CS 668 Applied Large Language Models, SDSU 2026-27 catalog: Prerequisite(s): CS 450 or CS 549 or consent of instructor Large language Models (LLM), understanding how an LLM works, training and refining LLMs, preparing data to train an LLM, testing and debugging LLMS, hardening LLMs against attacks, prompt engineering', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93574', 'Prerequisite(s): CS 450 or CS 549 or consent of instructor Large language Models (LLM), understanding how an LLM works, training and refining LLMs, preparing data to train an LLM, testing and debugging LLMS, hardening LLMs against attacks, prompt engineering', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f92', 'course', 'CS 759', 'CS 759 Advanced Computer Vision, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): Graduate standing and either CS 553, or CS 559, or CS 652 or consent of instructor.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=102019', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): Graduate standing and either CS 553, or CS 559, or CS 652 or consent of instructor.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f93', 'course', 'CY 541', 'CY 541 AI in Cybersecurity, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CY 302 and CS 450 or CS 549; or Graduate standing in CS or AIT; or instructor consent Explores the intersection of Artificial Intelligence (AI) and Cybersecurity.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=101977', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CY 302 and CS 450 or CS 549; or Graduate standing in CS or AIT; or instructor consent Explores the intersection of Artificial Intelligence (AI) and Cybersecurity.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f94', 'course', 'CY 632', 'CY 632 Privacy and Security in Modern Computing, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 549 or instructor consent Anonymity and re-identification, network privacy, differential privacy algorithms, privacy-preserving machine learning and AI, cryptographic protocols, fairness and ethics', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=102034', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 549 or instructor consent Anonymity and re-identification, network privacy, differential privacy algorithms, privacy-preserving machine learning and AI, cryptographic protocols, fairness and ethics', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f95', 'course', 'CS 558', 'CS 558 Computer Simulation, SDSU 2026-27 catalog: Methodology of simulation for discrete and continuous dynamic systems. State-of-the-art programming techniques and languages. Statistical aspects of simulation. Students will design, program, execute, and document a simulation of their choice.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88958', 'Methodology of simulation for discrete and continuous dynamic systems. State-of-the-art programming techniques and languages. Statistical aspects of simulation. Students will design, program, execute, and document a simulation of their choice.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f96', 'course', 'CS 581', 'CS 581 Computational Linguistics, SDSU 2026-27 catalog: Applications to parsing, natural language understanding, and large language models.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88966', 'Applications to parsing, natural language understanding, and large language models.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f97', 'course', 'CS 582', 'CS 582 Introduction to Speech Processing, SDSU 2026-27 catalog: Fundamentals of speech processing and speech recognition. Physical aspects of speech production and perception. Mathematical models for speech recognition. Corpus development: data collection, processing, and evaluation. Applications of speech processing and associated research topics.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=88967', 'Fundamentals of speech processing and speech recognition. Physical aspects of speech production and perception. Mathematical models for speech recognition. Corpus development: data collection, processing, and evaluation. Applications of speech processing and associated research topics.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f98', 'course', 'CS 605', 'CS 605 Scientific Computing, SDSU 2026-27 catalog: Parallel programming using message passing to include high performance computing and MPI language extensions.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91536', 'Parallel programming using message passing to include high performance computing and MPI language extensions.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f99', 'course', 'CS 615', 'CS 615 Spatial Database, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 514 . Recommended: CS 460 . Strategies for databases in which locations are prominent. Access strategies such as quadtrees and R-trees. Topological and other spatial extensions to query languages.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91538', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 514 . Recommended: CS 460 . Strategies for databases in which locations are prominent. Access strategies such as quadtrees and R-trees. Topological and other spatial extensions to query languages.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f100', 'course', 'CS 662', 'CS 662 Theory of Parallel Algorithms, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 460 , and MATH 254 . Models for parallel computation. Parallel algorithms for several common problems including sorting, searching, graph problems, and matrix problems.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91549', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 460 , and MATH 254 . Models for parallel computation. Parallel algorithms for several common problems including sorting, searching, graph problems, and matrix problems.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f101', 'course', 'CS 682', 'CS 682 Speech Processing, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): Graduate standing, CS 210 , MATH 254 , STAT 551A . Algorithms and methods for processing of speech.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91552', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): Graduate standing, CS 210 , MATH 254 , STAT 551A . Algorithms and methods for processing of speech.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f102', 'course', 'CS 663', 'CS 663 Algorithms for Big Data, SDSU 2026-27 catalog: This course covers the design and analysis of algorithms and machine learning in computational models that capture the computation of massive data such as streaming, sublinear, and parallel models.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93583', 'This course covers the design and analysis of algorithms and machine learning in computational models that capture the computation of massive data such as streaming, sublinear, and parallel models.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f103', 'course', 'CS 677', 'CS 677 Data Quality Assurance, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 577 or CS 549, graduate standing or consent of instructor. Introduction to the principles of data quality assurance, including data profiling, cleansing, anomaly detection, and quality constraints.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=93575', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): CS 577 or CS 549, graduate standing or consent of instructor. Introduction to the principles of data quality assurance, including data profiling, cleansing, anomaly detection, and quality constraints.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f104', 'course', 'CS 649', 'CS 649 Big Data Tools and Methods, SDSU 2026-27 catalog: Analyze, curate, search, and visualize big data. Apache MapReduce and Spark, distributed databases and messaging/streaming, electronic notebooks, NoSQL databases, programming languages, statistics.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=92973', 'Analyze, curate, search, and visualize big data. Apache MapReduce and Spark, distributed databases and messaging/streaming, electronic notebooks, NoSQL databases, programming languages, statistics.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f105', 'course', 'CS 696', 'CS 696 Selected Topics in Computer Science, SDSU 2026-27 catalog: Intensive study in specific areas of computer science. May Be Repeated:', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=91553', 'Intensive study in specific areas of computer science. May Be Repeated:', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f106', 'course', 'CS 798', 'Listed among elective area courses (CSY, ISY, DSC, STC, or MST) on the 2026-2027 catalog program page.', 'https://catalog.sdsu.edu/preview_program.php?catoid=12&poid=12288', 'CS 798 - Special Study Units: 1-3', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f107', 'course', 'MATH 625', 'MATH 625 Algebraic Coding Theory, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): MATH 525 and MATH 520 or MATH 522 with a grade of C (2.0) or better in each course. Algebraic theory of error correction codes and decoding algorithms used in modern communications systems.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=92270', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): MATH 525 and MATH 520 or MATH 522 with a grade of C (2.0) or better in each course. Algebraic theory of error correction codes and decoding algorithms used in modern communications systems.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f108', 'course', 'MATH 626', 'MATH 626 Cryptography, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): MATH 320 and MATH 522 with a grade of C (2.0) or better in each course. Design of secure cryptosystems with applications. Classical and public key cryptosystems.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=92271', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): MATH 320 and MATH 522 with a grade of C (2.0) or better in each course. Design of secure cryptosystems with applications. Classical and public key cryptosystems.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f109', 'course', 'MATH 668', 'MATH 668 Applied Fourier Analysis, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): MATH 330 , MATH 524 ; MATH 530 or MATH 532 with a grade of C (2.0) or better in each course. Discrete and continuous Fourier transform methods with applications to statistics and communication systems.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=92284', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): MATH 330 , MATH 524 ; MATH 530 or MATH 532 with a grade of C (2.0) or better in each course. Discrete and continuous Fourier transform methods with applications to statistics and communication systems.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f110', 'course', 'MATH 693A', 'MATH 693A Advanced Numerical Methods: Computational Optimization, SDSU 2026-27 catalog: The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): MATH 340 and MATH 524 and with a grade of C (2.0) or better in each course. Numerical optimization: Newton, Truncated-Newton, and Quasi- Newton methods for unconstrained optimization;', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=92285', 'The class will be offered for letter grade with no option to take it for Cr/NC Prerequisite(s): MATH 340 and MATH 524 and with a grade of C (2.0) or better in each course. Numerical optimization: Newton, Truncated-Newton, and Quasi- Newton methods for unconstrained optimization;', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f111', 'course', 'STAT 610', 'STAT 610 Linear Regression Models, SDSU 2026-27 catalog: Methods for diagnostic tools, matrix forms for multiple regression, model fitting and validation, simple and multiple regression models, and variable selection. Applications of methods with R, SAS, and SPSS software. Formerly numbered: Statistics 510.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=92797', 'Methods for diagnostic tools, matrix forms for multiple regression, model fitting and validation, simple and multiple regression models, and variable selection. Applications of methods with R, SAS, and SPSS software. Formerly numbered: Statistics 510.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('14-20261118', 'f112', 'course', 'STAT 676', 'STAT 676 Bayesian Statistics, SDSU 2026-27 catalog: Bayes'' theorem; conjugate priors; likelihood principle; posterior probability intervals; Bayes factors; prior elicitation; reference priors; computational techniques; hierarchical models; empirical and approximate Bayesian inference; posterior sensitivity analysis; decision theory.', 'https://catalog.sdsu.edu/preview_course_nopop.php?catoid=12&coid=92802', 'Bayes'' theorem; conjugate priors; likelihood principle; posterior probability intervals; Bayes factors; prior elicitation; reference priors; computational techniques; hierarchical models; empirical and approximate Bayesian inference; posterior sensitivity analysis; decision theory.', '2026-11-19T05:31:05.985Z');
INSERT INTO program_snapshots (snapshot_id, school_id, verified_at) VALUES ('2-20261118', '2', '2026-11-18T20:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f1', 'overview', 'Program aim', 'The M.S. is described as deepening hardware and software themes and stressing technical competence and independent work.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/index.shtml', 'The Master of Science program in Computer Science provides an opportunity for students to enhance their understanding of the principal hardware and software themes.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f2', 'overview', 'Evening classes', 'The FAQ says the program offers evening classes across a wide range of computer science topics.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/frequently-asked-questions.shtml', 'Evening classes with a wide range of topics in computer science', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f3', 'overview', 'Department also plans an online M.S.', 'The department home page announces an Online Master of Science in Computer Science coming up in Fall 2026; that is a different program from this on-campus M.S.', 'https://www.cpp.edu/sci/computer-science/', 'Online Master of Science in Computer Science', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f4', 'requirement', 'Undergraduate CS presumption', 'Admission presumes an undergraduate computer science degree or equivalent core coursework; students without that preparation cannot be admitted.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', 'The graduate program is based on the presumption that the student has an undergraduate degree with a major in computer science, or equivalent coursework in the principal computer science and mathematics subjects required', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f5', 'requirement', 'Admission is competitive', 'Meeting minimum requirements does not guarantee admission.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', 'These are minimum requirements for the program admission. Admission is competitive and meeting minimum requirement does not guarantee admission to the program.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f6', 'requirement', 'Unconditional GPA', 'Unconditional admission requires a bachelor''s in CS or a closely related field with a GPA of 3.0 or better in all courses or in the most recent 60 semester units.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', 'Applicants seeking unconditional admission must have a bachelor''s degree in Computer Science or closely related field with a GPA of 3.0 or better in all courses or the most recent 60 semester units attempted', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f7', 'requirement', 'Unconditional topic coverage', 'Required background includes calculus, probability and statistics, object-oriented programming, discrete structures, data structures, computer organization, algorithms, computer architecture, operating systems, and software engineering.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', '10-12 semester units including Calculus and Probability and Statistics', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f8', 'requirement', 'Conditional admission', 'Applicants with a bachelor''s degree and a GPA above 3.0 who do not meet unconditional requirements may seek conditional admission, with priority given to unconditional admissions first.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', 'Applicants who do not meet unconditional admission but have a bachelor''s degree with a GPA above 3.0 may seek conditional admission. However, priority will be given to unconditional admissions first.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f9', 'requirement', 'International students not conditionally admitted', 'International students who need an I-20 will not be conditionally admitted and must meet all requirements before admission.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', 'However, per CSU Admissions and SEVIS Policy, international students attending the University on a visa requiring issuance of an I-20 will NOT be conditionally admitted and must meet all requirements prior to gaining admission to the University.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f10', 'requirement', 'Conditional students and aid', 'Students in conditional standing do not qualify for federal financial aid until they are in unconditional standing.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', 'Students in conditional standing do not qualify for federal financial aid until they are in unconditional standing.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f11', 'requirement', 'English language requirement', 'Applicants whose native language is not English and whose bachelor''s instruction was not in English must meet IELTS 6.5 or TOEFL 213 computer / 550 paper / 80 internet.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/admission-requirements.shtml', 'must have passed the International English Language Testing System (IELTS) exam with a minimum score of 6.5 or the Test of English as a Foreign Language (TOEFL) exam with a minimum score of 213 on the computer-based, or 550 on the paper-based, or 80 on the Internet-based TOEFL.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f12', 'requirement', 'Supplemental application form', 'A program supplemental form is required and applications missing it may be declined without review.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/application-procedures.shtml', 'This Program Application form is REQUIRED and applications missing this completed form uploaded to Cal State Mentor site may be declined without review.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f13', 'requirement', 'SOP, resume, letters, unofficial transcript', 'Applicants must also submit a statement of purpose, resume/CV, two letters of recommendation, and an unofficial PDF transcript on Cal State Apply.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/application-procedures.shtml', 'applicants are REQUIRED to submit a statement of purpose (why applying to CPP CS MS program and how it will help to achieve your career objectives), resume/CV, two letters of recommendation and unoffical pdf transcript on Cal State Apply.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f14', 'requirement', 'GRE not required', 'The department does not require the GRE, but recommends it if the major GPA does not meet 3.0.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/frequently-asked-questions.shtml', 'The department does not require the GRE. However, it is recommended that you take it if your major GPA does not meet the 3.0 requirement.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f15', 'requirement', 'GPA to maintain', 'A 3.0 GPA or better must be maintained in all upper-division undergraduate and all graduate courses.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'A grade point average of 3.0 (B) or better must be maintained in all upper-division undergraduate and all graduate courses.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f16', 'requirement', 'Transfer unit cap', 'No more than 9 semester units of acceptable graduate credit may be transferred from another graduate institution.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'No more than 9 semester units of acceptable graduate credit may be transferred from another graduate institution.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f17', 'requirement', 'Combined transfer limit', 'A total limit of 9 semester units of transfer, Extended University, and/or petitioned units may be included on a master''s contract, with a 7-year time limit.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'A total limit of 9 semester units of transfer, Extended University, and/or units petitioned for graduate credit may be included on a master''s contract. The stipulated time limit of 7 years applies to all of the above.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f18', 'course', 'Total units', 'The program requires 30 units in total.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'TOTAL UNITS REQUIRED: 30 units', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f19', 'course', 'CS 5250', 'CS 5250 Advanced Computer Architecture (3), Cal Poly Pomona 2026-27 catalog: Architecture and organization of high performance computers. Principles of instruction sets. Pipelining, instruction level parallelism and multiprocessor. Memory, storage, and interconnection. Quantitative analysis and evaluation of design alternatives. Historical developments.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435688', 'Architecture and organization of high performance computers. Principles of instruction sets. Pipelining, instruction level parallelism and multiprocessor. Memory, storage, and interconnection. Quantitative analysis and evaluation of design alternatives. Historical developments.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f20', 'course', 'CS 5300', 'CS 5300 Advanced Algorithm Design and Analysis (3), Cal Poly Pomona 2026-27 catalog: Advanced problem domains, including graph problems, pattern matching, compression, network flow and transforms. Amortized and average case analysis. Lower bounds. Approximation techniques. Probabilistic algorithms. Prerequisite(s): CS 331 or CS 3310 .', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435689', 'Advanced problem domains, including graph problems, pattern matching, compression, network flow and transforms. Amortized and average case analysis. Lower bounds. Approximation techniques. Probabilistic algorithms. Prerequisite(s): CS 331 or CS 3310 .', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f21', 'course', 'CS 5800', 'CS 5800 Advanced Software Engineering (3), Cal Poly Pomona 2026-27 catalog: Software metrics and models. Software development methodologies. Advanced topics in object-oriented software engineering. Formal methods for modeling and specification. Software architecture. Software testing. Survey of trending software engineering tools and researches.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435699', 'Software metrics and models. Software development methodologies. Advanced topics in object-oriented software engineering. Formal methods for modeling and specification. Software architecture. Software testing. Survey of trending software engineering tools and researches.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f22', 'course', 'CS 6640', 'CS 6640 Graduate Seminar (1), Cal Poly Pomona 2026-27 catalog: Topics chosen according to the interests and needs of the students. Prerequisite(s): Unconditional standing.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435701', 'Topics chosen according to the interests and needs of the students. Prerequisite(s): Unconditional standing.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f24', 'course', 'CS 6950 project', 'The master''s project course is CS 6950 (1 unit).', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'CS 6950 Master''s Degree Project (1 unit)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f27', 'course', '4000-level electives', 'M.S. students may use up to 6 semester units of CS 4000-level electives, with listed exclusions, and may not repeat undergraduate classes already taken.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'Computer Science MS students can take up to 6 semester units of CS 4000+ levels elective classes to satisfy their elective courses requirement, excluding the following courses: CS 4000, CS 4310, CS 4610, CS 4620, CS 4630, and CS 4800.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f29', 'course', 'Evening graduate courses', 'Graduate courses traditionally meet in late afternoons and evenings.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/program-information.shtml', 'Graduate courses traditionally meet in late afternoons and evenings.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f30', 'deadline', 'Fall 2027 on-campus CS M.S.', 'The university graduate deadlines table lists the on-campus Computer Science M.S. Fall 2027 application deadline as 4/1/2027 and the intent-to-enroll deadline as 7/1/2027.', 'https://www.cpp.edu/admissions/graduate/masters-explore.shtml', 'Computer Science', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f31', 'deadline', 'Spring 2027 on-campus CS M.S.', 'The same table lists the on-campus Computer Science M.S. Spring 2027 application deadline as 10/1/2026 and the intent-to-enroll deadline as 1/12/2027.', 'https://www.cpp.edu/admissions/graduate/masters-explore.shtml', '10/1/2026', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f32', 'deadline', 'Spring 2027 applications open', 'Spring 2027 applications open July 1, 2026.', 'https://www.cpp.edu/admissions/graduate/masters-explore.shtml', 'Spring 2027 applications open July 1, 2026', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f33', 'deadline', 'Fall 2027 applications open', 'Fall 2027 applications open on August 1, 2026.', 'https://www.cpp.edu/admissions/graduate/masters-explore.shtml', 'Fall 2027 applications open on August 1, 2026', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f34', 'deadline', 'International 5/1 rule', 'If a program''s Fall deadline is after 5/1, international applicants must apply no later than 5/1 for visa timing. The on-campus CS M.S. Fall 2027 deadline is 4/1/2027, which is before that cutoff.', 'https://www.cpp.edu/admissions/graduate/masters-explore.shtml', 'International applicants: For graduate programs that have a Fall application deadline beyond 5/1, international applicants must submit an application no later than 5/1 to ensure sufficient time to obtain a visa.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f35', 'deadline', 'Applications accepted except summer', 'Applications are accepted semester by semester except Summer, and applicants are encouraged to apply in the initial filing period.', 'https://www.cpp.edu/sci/computer-science/prospective-graduate-students/application-procedures.shtml', 'Applications are accepted semester by semester except Summer.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f36', 'faculty', 'Graduate coordinator', 'Tingting Chen is listed as Professor and Graduate Coordinator. This is a department-wide faculty listing, not limited to this one program.', 'https://www.cpp.edu/sci/computer-science/faculty-and-staff/permanent-faculty.shtml', 'Professor & Graduate Coordinator', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f37', 'faculty', 'Department chair', 'Amar Raheja is listed as Professor and Chair on the department permanent faculty page.', 'https://www.cpp.edu/sci/computer-science/faculty-and-staff/permanent-faculty.shtml', 'Professor & Chair', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f38', 'faculty', 'Abdelfattah Amamra research', 'His faculty profile states research interests in cyber security, big data analysis, and machine learning. Department faculty listing, not program-specific.', 'https://www.cpp.edu/faculty/aamamra/index.shtml', 'Dr. Amamra research intersts include Cyber Security, Big Data Analysis, and Machine Learning.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f39', 'faculty', 'Tingting Chen research', 'Her profile describes current research in data privacy, health informatics, and AI applications in medical systems.', 'https://www.cpp.edu/faculty/tingtingchen/index.shtml', 'My current research interests include data privacy, health informatics and AI applications in medical systems.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f40', 'faculty', 'Hao Ji research', 'His profile lists large-scale numerical methods, high-performance computing, machine learning, computer vision, and physically-based animation.', 'https://www.cpp.edu/faculty/hji/index.shtml', 'His research interests include Large-scale Numerical Methods, High-performance Computing, Machine Learning, Computer Vision, and Physically-based Animation.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f41', 'faculty', 'Amar Raheja research', 'His profile lists image processing, computer vision, and machine learning, with interdisciplinary AI applications.', 'https://www.cpp.edu/faculty/raheja/index.shtml', 'My research interests are in the area of image processing, computer vision and machine learning.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f42', 'faculty', 'Wendy Shi research', 'Her profile, noting she joined in August 2025, describes HCI, computing education, and data science.', 'https://www.cpp.edu/faculty/wendyshi/index.shtml', 'Her research explores the intersection of human-computer interaction, computing education, and data science, with a focus on understanding how technology can support learning, collaboration, and meaningful work.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f43', 'faculty', 'Yunsheng Wang research', 'His profile lists AIoT, connected and autonomous driving, edge computing, cybersecurity, and social networks.', 'https://www.cpp.edu/faculty/yunshengwang/index.shtml', 'His research interests include Artificial Intelligence of Things (AIoT), connected and autonomous driving, edge computing, cybersecurity, and social networks.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f44', 'faculty', 'Yu Sun role', 'His profile says he directs the Software Engineering and Mobile Cloud Computing Lab (SoftCom Lab).', 'https://www.cpp.edu/faculty/yusun/index.shtml', 'where he serves as the director of the Software Engineering and Mobile Cloud Computing Lab (SoftCom Lab).', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f45', 'faculty', 'Daisy Tang research', 'Her profile describes doctoral research on multi-robot systems.', 'https://www.cpp.edu/faculty/ftang/index.shtml', 'performing her research on multi-robot systems.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f46', 'faculty', 'Ericsson Santana Marin research', 'His profile describes research in AI for Threat Intelligence.', 'https://www.cpp.edu/faculty/santanamarin/index.shtml', 'My research focuses on AI for Threat Intelligence (ATI), which develops predictive and adaptive learning models to anticipate emerging threats in adversarial online environments.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f47', 'faculty', 'Ben Steichen research lab', 'His profile says he leads the hapii lab on human-centered, adaptive, and personalized information interaction.', 'https://www.cpp.edu/faculty/bsteichen/index.shtml', 'Dr. Steichen leads the hapii lab (human-centered, adaptive, and personalized information interaction), which researches novel information access solutions that support each individual person.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f48', 'faculty', 'Mohammad Husain expertise (listing)', 'The department research-interests page, which is department-wide, lists systems and network security and related areas.', 'https://www.cpp.edu/sci/computer-science/faculty-and-staff/faculty-research-int.shtml', 'Expertise: Systems and network security, digital forensics in embedded systems and cloud computing, smartphone security and social applications, power-aware secure computing', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f49', 'faculty', 'Brianna Posadas expertise (listing)', 'The department research-interests page lists HCI, usable security, accessibility, and applied computing in agriculture, among other areas. No individual cpp.edu/faculty profile page was found (404).', 'https://www.cpp.edu/sci/computer-science/faculty-and-staff/faculty-research-int.shtml', 'Expertise: Human-computer interaction, user-centered design and technology adoption, usable security, accessibility and inclusive design, applied computing in agriculture and other real-world domains, data science and big data analysis, remote sensing (UAVs), computing education', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f50', 'faculty', 'John Korah expertise (listing)', 'The department research-interests page lists parallel and distributed algorithm design, HPC, and related areas.', 'https://www.cpp.edu/sci/computer-science/faculty-and-staff/faculty-research-int.shtml', 'Expertise: Parallel & distributed algorithm design, high performance computing, large & dynamic network analysis, computational social systems, cybersecurity, parallel/distributed information retrieval, modeling & simulation', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f51', 'overview', 'Catalog heading and unit total', 'The 2026-2027 University Catalog program heading is Computer Science, M.S.: 30 units.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Computer Science, M.S.: 30 units', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f52', 'requirement', 'Major required units', 'The catalog lists 13 units of major required courses. Earlier department-page facts used a required list without CS 5215 and a different elective-unit split; both sources are kept and no winner is chosen.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Major Required: 13 units', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f53', 'course', 'CS 5215', 'CS 5215 Advanced Machine Learning and AI (3), Cal Poly Pomona 2026-27 catalog: Core principles of machine learning and deep learning. Theoretical foundations of optimization, probabilistic modeling, and representation learning. Modern strategies include contrastive, positive-unlabeled, and reinforcement learning with applications across domains.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=451029', 'Core principles of machine learning and deep learning. Theoretical foundations of optimization, probabilistic modeling, and representation learning. Modern strategies include contrastive, positive-unlabeled, and reinforcement learning with applications across domains.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f58', 'requirement', 'Major elective unit range', 'The catalog sets major electives at 12-15 units.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Major Electives: 12-15 units', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f59', 'requirement', 'Elective units with project vs thesis', 'Students select 15 semester units of electives with the Master''s Degree Project or 12 semester units with the Master''s Degree Thesis. Earlier department-page fact f26 quoted 18 units with the project or 15 with the thesis; both quotes are kept and no winner is chosen.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Select 15 semester units (with Master''s Degree Project) or 12 semester units (with Master''s Degree Thesis)', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f60', 'requirement', 'Culminating experience unit range and options', 'Students choose Option 1 (2 units) or Option 2 (5 units) for the culminating experience.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Culminating Experience: 2-5 units Choose Option 1 (2 units) or Option 2 (5 units).', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f61', 'requirement', 'Project vs thesis recommendation', 'The page recommends the MS Project for students seeking industry placement right after graduation, and the MS Thesis for research labs or advanced education such as a Ph.D.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'In general, MS Project is recommended for students seeking industry placement right after graduation. MS Thesis option is recommended for students seeking placement at research labs and/or advanced education such as PhD.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f62', 'requirement', 'Option 1 project units', 'Option 1 requires 1 unit of CS 6910 Directed Research and 1 unit of CS 6950 Master''s Degree Project. The catalog titles CS 6910 Directed Research; an earlier department-page fact called it Directed Study. Both quotes are kept and no winner is chosen.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Option 1: 2 units CS 6910 - Directed Research (1-3) (1 unit required) CS 6950 - Master''s Degree Project (1) (1 unit required)', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f63', 'requirement', 'Option 2 thesis units', 'Option 2 requires 2 units of CS 6910 Directed Research and 3 units of CS 6960 Master''s Degree Thesis.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Option 2: 5 units CS 6910 - Directed Research (1-3) (2 units required) CS 6960 - Master''s Degree Thesis (1-3) (3 units required)', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f64', 'requirement', '4000-level elective cap and excluded courses', 'Up to 6 semester units of CS 4000+ electives may count, excluding CS 4000, 4310, 4610, 4620, 4630, and 4800.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Computer Science MS students can take up to 6 semester units of CS 4000+ level elective classes to satisfy their elective courses requirement, excluding the following courses: CS 4000 , CS 4310 , CS 4610 , CS 4620 , CS 4630 , and CS 4800 .', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f65', 'requirement', 'No repeat of undergraduate 4000-level classes', 'Those 4000+ classes cannot be ones the student already took as an undergraduate.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'However, these 4000+ level classes cannot be classes that a CS MS student already took in their undergraduate curriculum.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f66', 'requirement', 'CS 4990 and CS 5990 unit caps', 'A master''s contract may include at most 6 semester units of CS 4990 and 6 semester units of CS 5990.', 'https://catalog.cpp.edu/preview_program.php?catoid=78&poid=24271', 'Therefore, in a master''s contract, a CS MS student can have a maximum of 6 semester units of CS 4990 and 6 semester units of CS 5990 course credits.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f67', 'course', 'CS 6910', 'CS 6910 Directed Research (1-3), Cal Poly Pomona 2026-27 catalog: Individual research in a specialized area, under the direction of a graduate faculty member; work does not pertain directly to the thesis. Total credit limited to 6 units, with a maximum of 3 units per semester.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=438204', 'Individual research in a specialized area, under the direction of a graduate faculty member; work does not pertain directly to the thesis. Total credit limited to 6 units, with a maximum of 3 units per semester.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f68', 'course', 'CS 6950', 'CS 6950 Master’s Degree Project (1), Cal Poly Pomona 2026-27 catalog: Independent work on practical application of an existing methodology or procedure under supervision of a project advisor. Credit assigned upon successful completion of project and oral presentation. Total credit limited to 1 unit, but may be repeated until completion.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435702', 'Independent work on practical application of an existing methodology or procedure under supervision of a project advisor. Credit assigned upon successful completion of project and oral presentation. Total credit limited to 1 unit, but may be repeated until completion.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f69', 'course', 'CS 6960', 'CS 6960 Master’s Degree Thesis (1-3), Cal Poly Pomona 2026-27 catalog: Independent investigation intended to be an extension of an existing body of knowledge. Reporting of research results in an oral presentation and acceptable written form. Credit assigned upon successful completion of thesis and oral presentation.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435703', 'Independent investigation intended to be an extension of an existing body of knowledge. Reporting of research results in an oral presentation and acceptable written form. Credit assigned upon successful completion of thesis and oral presentation.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f70', 'course', 'CPU 5003', 'CPU 5003 Cal Poly Pomona Graduate Sponsored Summer Experience (0), Cal Poly Pomona 2026-27 catalog: Enrollment in this 0-unit course allows students to receive university services while participating in a Cal Poly Pomona sponsored summer experience.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=439398', 'Enrollment in this 0-unit course allows students to receive university services while participating in a Cal Poly Pomona sponsored summer experience.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f71', 'course', 'CS 5170', 'CS 5170 Advanced Natural Language Processing (3), Cal Poly Pomona 2026-27 catalog: Advanced study of natural language processing focusing on deep and state-of-the-art methods. Topics include full lexical, syntactic, and semantic analysis; neural models such as RNNs, LSTMs, GRUs, and transformers; contextual embeddings (e.g., BERT, GPT);', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435669', 'Advanced study of natural language processing focusing on deep and state-of-the-art methods. Topics include full lexical, syntactic, and semantic analysis; neural models such as RNNs, LSTMs, GRUs, and transformers; contextual embeddings (e.g., BERT, GPT);', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f72', 'course', 'CS 5180', 'CS 5180 Information Retrieval (3), Cal Poly Pomona 2026-27 catalog: Theory, design, and implementation of text-based information retrieval systems. Overview of information retrieval system. Statistical characteristics of text, representation of information needs and documents, retrieval models, search evaluation, clustering and classification algorithms.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=437630', 'Theory, design, and implementation of text-based information retrieval systems. Overview of information retrieval system. Statistical characteristics of text, representation of information needs and documents, retrieval models, search evaluation, clustering and classification algorithms.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f73', 'course', 'CS 5190', 'CS 5190 Computer Vision (3), Cal Poly Pomona 2026-27 catalog: Dual Listed as: CS 4190 Core principles of computer vision, focusing on image formation, representation, and feature extraction as the basis for visual understanding. Theoretical foundations include camera models, geometric reasoning, illumination, and feature learning.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435686', 'Dual Listed as: CS 4190 Core principles of computer vision, focusing on image formation, representation, and feature extraction as the basis for visual understanding. Theoretical foundations include camera models, geometric reasoning, illumination, and feature learning.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f74', 'course', 'CS 5240', 'CS 5240 Software for Intelligent Robotics (3), Cal Poly Pomona 2026-27 catalog: Dual Listed as: CS 4240 Design and development of software systems for intelligent robotics. Emphasis on software architectures, algorithms, and frameworks that enable robotic autonomy.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435687', 'Dual Listed as: CS 4240 Design and development of software systems for intelligent robotics. Emphasis on software architectures, algorithms, and frameworks that enable robotic autonomy.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f75', 'course', 'CS 5220', 'CS 5220 Distributed Intelligence in Robotics (3), Cal Poly Pomona 2026-27 catalog: Multi-robot architecture, multi-robot taxonomies, multi-robot communication, and the state-of-the-art research issues in this field, such as swarm intelligence, multi-vehicle collaboration, task allocation, multi-robot or human-robot teaming, and reconfigurable robotics.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=437815', 'Multi-robot architecture, multi-robot taxonomies, multi-robot communication, and the state-of-the-art research issues in this field, such as swarm intelligence, multi-vehicle collaboration, task allocation, multi-robot or human-robot teaming, and reconfigurable robotics.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f76', 'course', 'CS 5230', 'CS 5230 Connected and Autonomous Vehicles (3), Cal Poly Pomona 2026-27 catalog: Examines Connected Vehicle (CV) and Autonomous Vehicle (AV) technologies, including vehicle-to-vehicle (V2V), vehicle-to-infrastructure (V2I), and vehicle-to-everything (V2X) communication systems.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=439518', 'Examines Connected Vehicle (CV) and Autonomous Vehicle (AV) technologies, including vehicle-to-vehicle (V2V), vehicle-to-infrastructure (V2I), and vehicle-to-everything (V2X) communication systems.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f77', 'course', 'CS 5310', 'CS 5310 Computability and Complexity Theory (3), Cal Poly Pomona 2026-27 catalog: Formalizing problems and algorithms. Characterizations and properties of complexity classes, undecidability. Cook-Levin Theorem, NP-complete problems, proof of NP-completeness. Prerequisite(s): CS 311 or CS 3110 ; and CS 331 or CS 3310 .', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435690', 'Formalizing problems and algorithms. Characterizations and properties of complexity classes, undecidability. Cook-Levin Theorem, NP-complete problems, proof of NP-completeness. Prerequisite(s): CS 311 or CS 3110 ; and CS 331 or CS 3310 .', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f78', 'course', 'CS 5350', 'CS 5350 Parallel and Distributed Algorithms (3), Cal Poly Pomona 2026-27 catalog: Models of parallel and distributed computation. Design and analysis of algorithms for parallel and distributed systems. Basic techniques, classic problems. Parallel and distributed complexity classes. Hardware and software issues involved in parallel and distributed problem solving.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435691', 'Models of parallel and distributed computation. Design and analysis of algorithms for parallel and distributed systems. Basic techniques, classic problems. Parallel and distributed complexity classes. Hardware and software issues involved in parallel and distributed problem solving.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f79', 'course', 'CS 5370', 'CS 5370 Scheduling Algorithms (3), Cal Poly Pomona 2026-27 catalog: The alpha/beta/gamma notation. Scheduling theory. Deterministic scheduling. Basic scheduling algorithms. Single machine models. Parallel machine models. Other scheduling models. Real-time scheduling. Applications. Prerequisite(s): CS 530 or CS 5300 .', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435692', 'The alpha/beta/gamma notation. Scheduling theory. Deterministic scheduling. Basic scheduling algorithms. Single machine models. Parallel machine models. Other scheduling models. Real-time scheduling. Applications. Prerequisite(s): CS 530 or CS 5300 .', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f80', 'course', 'CS 5400', 'CS 5400 Topics in Compiler Design (3), Cal Poly Pomona 2026-27 catalog: Code generation and optimization. Data flow analysis. Syntax-directed translation. Parallelizing compiler. Automatic compiler generation. Prerequisite(s): CS 411 or CS 4110 .', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435693', 'Code generation and optimization. Data flow analysis. Syntax-directed translation. Parallelizing compiler. Automatic compiler generation. Prerequisite(s): CS 411 or CS 4110 .', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f81', 'course', 'CS 5500', 'CS 5500 Advanced Information Security (3), Cal Poly Pomona 2026-27 catalog: Information security overview. Information security attacks and defenses case studies in systems, networking, web application and cloud computing. Prerequisite(s): CS 380 or CS 3800 .', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=437631', 'Information security overview. Information security attacks and defenses case studies in systems, networking, web application and cloud computing. Prerequisite(s): CS 380 or CS 3800 .', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f82', 'course', 'CS 5550', 'CS 5550 Digital Image Processing (3), Cal Poly Pomona 2026-27 catalog: Mathematical preliminaries for digital image processing. Digital image fundamentals sampling and quantization. Image enhancement spatial and frequency domain filtering. Image compression. Color image processing. Multiresolution processing. Prerequisite(s): CS 331 or CS 3310 ;', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435694', 'Mathematical preliminaries for digital image processing. Digital image fundamentals sampling and quantization. Image enhancement spatial and frequency domain filtering. Image compression. Color image processing. Multiresolution processing. Prerequisite(s): CS 331 or CS 3310 ;', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f83', 'course', 'CS 5510', 'CS 5510 Data Privacy and Security (3), Cal Poly Pomona 2026-27 catalog: Privacy Policies. Challenges of sensitive data leakage. Definitions of data privacy. Privacy enhancing techniques: cryptographic approaches and non-crypto approaches. Metadata privacy. Anonymous communication systems. Machine learning and privacy. Block-chain and data integrity. Big data privacy.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=439321', 'Privacy Policies. Challenges of sensitive data leakage. Definitions of data privacy. Privacy enhancing techniques: cryptographic approaches and non-crypto approaches. Metadata privacy. Anonymous communication systems. Machine learning and privacy. Block-chain and data integrity. Big data privacy.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f84', 'course', 'CS 5520', 'CS 5520 Machine Learning for Cyber Security (3), Cal Poly Pomona 2026-27 catalog: The fundamentals of Machine Learning algorithms, building Machine learning information security models, Malware detection system, spam email detection system, botnet detection system, network security, security application for deep learning, and anomaly detection system.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=439322', 'The fundamentals of Machine Learning algorithms, building Machine learning information security models, Malware detection system, spam email detection system, botnet detection system, network security, security application for deep learning, and anomaly detection system.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f85', 'course', 'CS 5560', 'CS 5560 Game Theory and its Applications in Communication Networks (3), Cal Poly Pomona 2026-27 catalog: Fundamentals in game theory, strategic games, extensive games, coalitional games, Nash equilibrium and other solution concepts. Packet forwarding games, medium access games for 802.11 WLAN, power control games in CDMA systems. Prerequisite(s): CS 3800 or CS 380, or consent of instructor.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=439066', 'Fundamentals in game theory, strategic games, extensive games, coalitional games, Nash equilibrium and other solution concepts. Packet forwarding games, medium access games for 802.11 WLAN, power control games in CDMA systems. Prerequisite(s): CS 3800 or CS 380, or consent of instructor.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f86', 'course', 'CS 5650', 'CS 5650 Advanced Computer Networks (3), Cal Poly Pomona 2026-27 catalog: Issues in network architectures and standards. Network design. Performance evaluation and monitoring. Network management and security. High-speed networking technologies. Wireless networks and mobile computing. System architecture and network programming. Prerequisite(s): CS 380 or CS 3800 .', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435695', 'Issues in network architectures and standards. Network design. Performance evaluation and monitoring. Network management and security. High-speed networking technologies. Wireless networks and mobile computing. System architecture and network programming. Prerequisite(s): CS 380 or CS 3800 .', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f87', 'course', 'CS 5660', 'CS 5660 Distributed Computing Systems (3), Cal Poly Pomona 2026-27 catalog: Distributed systems models. Distributed naming. Synchronization. Consistency. Fault tolerance. Security. Grid computing. Computational Cloud. Distributed storage systems. Peer-to-Peer systems. Software defined Networks. Prerequisite(s): CS 380 or CS 3800 .', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435696', 'Distributed systems models. Distributed naming. Synchronization. Consistency. Fault tolerance. Security. Grid computing. Computational Cloud. Distributed storage systems. Peer-to-Peer systems. Software defined Networks. Prerequisite(s): CS 380 or CS 3800 .', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f88', 'course', 'CS 5670', 'CS 5670 Computational Social Systems (3), Cal Poly Pomona 2026-27 catalog: In-depth exploration of computational techniques for representing, modeling, processing, and analyzing social information.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=439519', 'In-depth exploration of computational techniques for representing, modeling, processing, and analyzing social information.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f89', 'course', 'CS 5700', 'CS 5700 Human Computer Interaction (3), Cal Poly Pomona 2026-27 catalog: Principles of human factors, computer technology, and their interactions. Theory and practice of user interface design and evaluation.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435697', 'Principles of human factors, computer technology, and their interactions. Theory and practice of user interface design and evaluation.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f90', 'course', 'CS 5750', 'CS 5750 Topics in Database Systems (3), Cal Poly Pomona 2026-27 catalog: Advanced SQL programming. Trigger and stored procedure. Object-relational and semi-structured modeling and databases. Physical database design. Techniques and algorithms for database design. XML and Web data. Distributed databases. Information integration. Data warehouses. Data mining.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435698', 'Advanced SQL programming. Trigger and stored procedure. Object-relational and semi-structured modeling and databases. Physical database design. Techniques and algorithms for database design. XML and Web data. Distributed databases. Information integration. Data warehouses. Data mining.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f91', 'course', 'CS 5850', 'CS 5850 Software Verification and Validation (3), Cal Poly Pomona 2026-27 catalog: Techniques for evaluating software quality and integrity. Quality assessment, proof of correctness, testing methods and tools. Survey of trending researches in software testing and verification.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=435700', 'Techniques for evaluating software quality and integrity. Quality assessment, proof of correctness, testing methods and tools. Survey of trending researches in software testing and verification.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f92', 'course', 'CS 5860', 'CS 5860 Software Metrics and Models (3), Cal Poly Pomona 2026-27 catalog: Measuring internal product attributes (size and structure). Program decomposition (control-flow graph, prime components, sequencing and nesting). Hierarchical measures. Test coverage measures. Basis coverage du-path coverage. Complexity measures. Modularity and information flow measures.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=437816', 'Measuring internal product attributes (size and structure). Program decomposition (control-flow graph, prime components, sequencing and nesting). Hierarchical measures. Test coverage measures. Basis coverage du-path coverage. Complexity measures. Modularity and information flow measures.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f93', 'course', 'CS 5990', 'CS 5990 Special Topics for Graduate Students (1-3), Cal Poly Pomona 2026-27 catalog: Group study at a graduate level of a selected well-defined topic or area not covered by a regularly offered course. Prerequisite(s): Graduate Standing.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=438201', 'Group study at a graduate level of a selected well-defined topic or area not covered by a regularly offered course. Prerequisite(s): Graduate Standing.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f94', 'course', 'CS 6990', 'CS 6990 Master’s Degree Continuation (0), Cal Poly Pomona 2026-27 catalog: Enrollment in this course allows candidates that have enrolled in the maximum number of thesis or project units to maintain resident status in order to receive university services.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=438206', 'Enrollment in this course allows candidates that have enrolled in the maximum number of thesis or project units to maintain resident status in order to receive university services.', '2026-11-19T05:31:12.635Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('2-20261118', 'f95', 'course', 'CS 5440', 'CS 5440 Advanced Data Mining (3), Cal Poly Pomona 2026-27 catalog: Advanced methods for extracting patterns in large data sets that blend traditional data analysis with machine learning algorithms.', 'https://catalog.cpp.edu/preview_course_nopop.php?catoid=78&coid=451026', 'Advanced methods for extracting patterns in large data sets that blend traditional data analysis with machine learning algorithms.', '2026-11-19T05:31:12.635Z');
