INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('22-20261119', 'f6', 'requirement', 'Breadth 12 units', 'Three courses; letter grade B- or higher.', 'https://cse.ucsd.edu/graduate/degree-programs/ms-program', 'three graduate courses (twelve units) to satisfy this requirement. Courses must be taken for a letter grade and completed with grade of B- or higher.', '2026-11-06T22:44:50.552Z');
