INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('22-20261119', 'f8', 'requirement', 'GPA 3.0 standing', 'Maintain minimum overall GPA 3.0.', 'https://cse.ucsd.edu/graduate/degree-programs/ms-program', 'minimum overall GPA of 3.0 at UC San Diego.', '2026-11-06T22:44:50.552Z');
