INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f41', 'faculty', 'Jan "Matt" Pedersen', 'UNLV faculty profile: research interests include compiler constructions, languages, formal verification, debugging, and concurrent/parallel computing. He recently authored the book "Practical Compiler Construction using Java and the JVM", which is also used at UNLV.', 'https://www.unlv.edu/people/matt-pedersen', 'research interests include compiler constructions, languages, formal verification, debugging, and concurrent/parallel computing. He recently authored the book "Practical Compiler Construction using Java and the JVM", which is also used at UNLV.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f42', 'faculty', 'Bryar Shareef, Ph.D.', 'UNLV faculty profile: research interests are in machine learning and artificial intelligence, with a focus on computer vision and image processing, data analytics, and multimodal deep learning.', 'https://www.unlv.edu/people/bryar-shareef', 'research interests are in machine learning and artificial intelligence, with a focus on computer vision and image processing, data analytics, and multimodal deep learning.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f43', 'faculty', 'Junggab Son, Ph.D.', 'UNLV faculty profile: research interests include applied cryptography, blockchain and smart contracts, AI-powered cyber attacks and countermeasures, privacy preservation, and AI security.', 'https://www.unlv.edu/people/junggab-son', 'research interests include applied cryptography, blockchain and smart contracts, AI-powered cyber attacks and countermeasures, privacy preservation, and AI security.', '2026-11-18T12:00:00.000Z');
