INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f49', 'faculty', 'Zuobin Xiong', 'Profile: research interests in cybersecurity and privacy, including privacy-preserving machine learning and data mining, IoT, and data security.', 'https://www.unlv.edu/people/zuobin-xiong', 'research interests lie in a broad area of cybersecurity and privacy, including privacy-preserving machine learning, privacy-preserving data mining, the Internet of Things (IoT), and data security related topics.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f50', 'faculty', 'Shaikh Arifuzzaman', 'UNLV faculty profile: research interests are in algorithmic foundations of large-scale, data-intensive computing using high-performance computing (HPC) techniques, especially for data science, artificial intelligence (AI)/machine learning (ML), and security problems.', 'https://www.unlv.edu/people/shaikh-arifuzzaman', 'research interests are in algorithmic foundations of large-scale, data-intensive computing using high-performance computing (HPC) techniques, especially for data science, artificial intelligence (AI)/machine learning (ML), and security problems.', '2026-11-18T12:00:00.000Z');
