INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f57', 'faculty', 'Mingon Kang', 'UNLV faculty profile: research interests include Machine Learning, Big Data Analytics, Data Science, and Bioinformatics. Specifically, Kang has been focusing on developing novel computational methodologies for sparse learning, subspace learning, and integrative and interpretable deep learning.', 'https://www.unlv.edu/people/mingon-kang', 'research interests include Machine Learning, Big Data Analytics, Data Science, and Bioinformatics. Specifically, Kang has been focusing on developing novel computational methodologies for sparse learning, subspace learning, and integrative and interpretable deep learning.', '2026-11-18T12:00:00.000Z');
