INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f60', 'faculty', 'Prashant Modekurthy', 'UNLV faculty profile: research interests include Cyber Physical Systems (CPS), Real-Time and Embedded Systems, Parallel and Distributed Computing, Internet-of-Things (IoT), and Industrial Internet-of-Things (IIoT) / Industry 4.0.', 'https://www.unlv.edu/people/prashant-modekurthy', 'research interests include Cyber Physical Systems (CPS), Real-Time and Embedded Systems, Parallel and Distributed Computing, Internet-of-Things (IoT), and Industrial Internet-of-Things (IIoT) / Industry 4.0.', '2026-11-18T12:00:00.000Z');
