INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'e1', 'faculty', 'Sohini Roy', 'UNLV faculty profile: research interests include cyber-physical systems, smart grid resilience, and wireless sensor networks, and she is passionate about fostering a student-centered and engaging learning environment.', 'https://www.unlv.edu/people/sohini-roy', 'research interests include cyber-physical systems, smart grid resilience, and wireless sensor networks, and she is passionate about fostering a student-centered and engaging learning environment.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'e2', 'faculty', 'Yichi Zhang', 'UNLV faculty profile: His research focuses on scientific computing and high performance computing as well as computer science education.', 'https://www.unlv.edu/people/yichi-zhang', 'His research focuses on scientific computing and high performance computing as well as computer science education.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f63', 'overview', '2026-2027 catalog program title', 'The 2026-2027 Graduate Catalog program page title is Master of Science in Computer Science. This is the catalog URL that could not be fetched earlier because of an AWS WAF block.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', '2026-2027 Graduate Catalog Master of Science in Computer Science', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f64', 'requirement', 'Graduate College admission GPA (catalog)', 'On this 2026-2027 catalog program page, the Graduate College admission requirements ask for a minimum overall GPA of 2.75 for the bachelor''s degree, or a minimum 3.00 for the last two years (60 semester credits). This is close to department-admissions-page fact f22 (2.75 overall or 3.0 on the last two years). The same catalog page also has a stricter department line (fact f66).', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'You must have a minimum overall grade point average of 2.75 (4.00=A) for the bachelor''s degree or a minimum 3.00 (4.00=A) for the last two years (60 semester credits).', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f65', 'requirement', 'Integrated BS/MS: dual-count graduate courses', 'The Integrated BS/MS subplan lets high-achieving UNLV CS undergraduates take up to three graduate-level CS courses that can count toward both the B.S. and M.S. programs.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'The Integrated BS/MS subplan is designed to provide high-achieving UNLV CS undergraduate students with opportunity to take up to three graduate level CS courses that can count towards both BS and MS degree programs at UNLV.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f66', 'requirement', 'Department catalog GPA minimum 3.00', 'The Department Admission Requirements on the 2026-2027 catalog program page say applicants must submit a minimum GPA of 3.00. This is stricter than, and conflicts with, existing department-admissions-page fact f22, which quotes a minimal GPA of 2.75 overall or 3.0 on the last two years of undergraduate work. The same catalog page also states the Graduate College 2.75 / 3.00-last-60-credits rule (fact f64). Both catalog lines and f22 are kept; no winner is chosen.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'A minimum GPA of 3.00.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f67', 'requirement', 'GRE preferred minimum 297, five-year currency, BS-MS waiver', 'The 2026-2027 catalog program page requires GRE results current to within five years, sent directly to the department, with a preferred minimum score of 297, and waives the GRE for the Integrated BS-MS subplan. Existing department-admissions-page fact f25 already said GRE results are required but had no numeric cutoff, because this catalog page could not be fetched then. This catalog wording adds the preferred 297 figure, the five-year limit, and the BS-MS waiver; it does not state a hard cutoff. Both facts are kept.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'The results of the Graduate Record Examination current to within five years should be sent directly to the department. The preferred minimum score requirement is 297. The GRE requirement is waived for students participating in the Integrated BS-MS subplan.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f68', 'requirement', 'Named undergraduate background courses', 'The catalog names the expected undergraduate background, with an average grade of B or better: Programming Languages (CS 326), Operating Systems (CS 370), Discrete Mathematics II (MATH 351), and Statistical Methods I (STAT 411). This is more specific than existing department-admissions-page fact f23, which referred only to ''courses equivalent to our basic undergraduate courses.''', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'In addition, applicants must have completed courses and their prerequisites equivalent to our undergraduate Programming Languages (CS 326), Operating Systems (CS 370), Discrete Mathematics II (MATH 351), and Statistical Methods I (STAT 411) with an average grade of B or better.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f69', 'requirement', 'Conditional admission if background is incomplete', 'The Computer Science Admission Committee may admit an outstanding applicant who has not satisfied all background requirements on a conditional basis; those requirements must be completed before full admission is granted.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'The Computer Science Admission Committee may elect to admit an outstanding applicant who has not satisfied all of the background requirements on a conditional basis.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f70', 'requirement', 'CS 656, 660, and 677 as an admission condition', 'Students who have not completed CS 656 Automata and Formal Languages, CS 677 Analysis of Algorithms, and CS 660 Compiler Construction (or equivalents) as part of the bachelor''s degree may be required to complete them as a condition of admission; if taken in the master''s program, they may count toward the 30 credits required. Existing department-master''s-page fact f8 instead says that if equivalent courses have not been taken previously, CS 656, 660, and 677 must be included. The catalog frames this as an admission condition rather than a blanket degree-inclusion rule. Both wordings are kept; no winner is chosen.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Students who have not completed all the following courses (or equivalent courses) as part of their bachelor''s degree may be required to complete them as a condition of their admission. If taken as part of their master''s degree program, these courses may count toward the 30 credits required.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f71', 'requirement', 'Integrated BS-MS: nine senior-year credits may be waived', 'Up to nine credits of approved graduate-level coursework taken as technical electives for a grade of B or better during the senior year will be waived for the graduate degree.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Up to nine credits of approved graduate-level course work can be taken as technical electives for the grade of B or better during the senior year and those credits will be waived for the graduate degree.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f72', 'requirement', 'Integrated BS-MS eligibility and thesis-only rule', 'To enroll in the Integrated BS-MS program, a student needs at least two semesters of full-time enrollment in the B.S. in Computer Science, normally applies with two semesters remaining in the senior year, and must have completed at least 90 credits applicable to that B.S. with a cumulative GPA of 3.3 or higher. Students have to choose the thesis option, and should request a nomination letter from a Computer Science faculty member and submit it with a short resume (no more than two pages) to the department as well as apply through the Grad Rebel Gateway.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'A minimum of 90 credits of course work applicable to the B.S. of Computer Science degree with a cumulative GPA of 3.3 or higher must be completed before beginning the joint degree program.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f73', 'requirement', 'Integrated BS-MS must use the thesis option', 'Students in the Integrated BS-MS program have to choose the thesis option in the M.S. degree.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Students have to choose the thesis option in the MS degree.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f74', 'requirement', 'Thesis subplan credit split (catalog)', 'Thesis subplan (Subplan 1): total 30 credits, including 24 credits of 600- or 700-level Computer Science courses (students may complete up to 3 credits outside of CS, related to the research area and approved by the department graduate committee) plus 6 credits of CS 791 Thesis. This agrees with existing 2026-27 thesis plan-of-study facts f11 and f13.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Complete 24 credits of 600- or 700- level Computer Science (CS) courses. Students may complete up to 3 credits outside of CS.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f75', 'requirement', 'Thesis and Integrated BS-MS: 12 credits of 700-level CS excluding thesis', 'For the Thesis subplan and the Integrated BS-MS subplan, the 2026-2027 catalog says students must complete 12 credits of 700-level CS courses (excluding thesis). This is the official catalog wording that bears on the open 700-level hold. Existing department-page fact f7 says at least 18 credits of computer science courses must be at the 700 level (and does not say ''excluding thesis''). Existing plan-of-study fact f16 says a minimum of 50 percent of the degree program must be 700-level courses, excluding thesis, dissertation, or professional/scholarly paper. Twelve credits excluding a 6-credit thesis is 50 percent of the remaining 24 credits, so f16 is compatible with this catalog line. Whether f7 is compatible depends on whether the 6 credits of CS 791 Thesis count toward that 18-credit CS 700-level total (12 + 6 = 18). The catalog does not restate f7''s blanket 18-credit rule and does not use f16''s ''50 percent'' wording. All three are kept; no winner is chosen.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Students must complete 12 credits of 700-level CS courses (excluding thesis).', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f76', 'requirement', 'Project subplan credit split (catalog)', 'Project subplan (Subplan 2): total 30 credits, including 27 credits of 600- or 700-level Computer Science courses (up to 3 credits outside of CS, related to the research area and approved by the department graduate committee) plus 3 credits of CS 790 Master''s Project. This agrees with existing 2026-27 project plan-of-study fact f14.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Complete 27 credits of 600- or 700- level Computer Science (CS) courses. Students may complete up to 3 credits outside of CS.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f77', 'requirement', 'Project subplan: 15 credits of 700-level CS excluding the project', 'For the Project subplan, the 2026-2027 catalog says students must complete 15 credits of 700-level CS courses (excluding the project). This also bears on the open 700-level hold. Fifteen credits excluding a 3-credit project meets f16''s 50-percent-excluding-project reading (15 of the remaining 27). Compatibility with f7''s 18-credit 700-level CS rule depends on whether CS 790 Master''s Project credits count toward that 18 (15 + 3 = 18). The catalog does not restate f7 or f16 in those words. All three are kept; no winner is chosen.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Students must complete 15 credits of 700-level CS courses (excluding the project).', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f78', 'requirement', 'Exam subplans: 18 credits of 700-level CS courses', 'For the exam subplans (Subplans 4 to 11), the 2026-2027 catalog says students must complete 18 credits of 700-level CS courses. There is no thesis or project to exclude. This matches the number in department-page fact f7 and also satisfies plan-of-study fact f16 (18 of 30 is more than 50 percent). The catalog therefore uses different 700-level minima by subplan: 12 excluding thesis (thesis and Integrated BS-MS), 15 excluding the project (project), and 18 (exam).', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Students must complete 18 credits of 700-level CS courses.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f79', 'requirement', 'Exam subplans: 9-credit area list plus 21 other credits, up to 6 outside CS', 'Each exam subplan requires 9 credits from that subplan''s required-course list plus 21 credits of other 600- or 700-level Computer Science courses, and students may complete up to 6 credits outside of CS. Outside credits must be related to computer applications and approved by the CS graduate committee. The 6-credit outside allowance is looser than the 3-credit outside cap on the thesis and project subplans (and on existing plan-of-study facts f11 and f14).', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Complete 21 credits of 600- or 700- level Computer Science (CS) courses. Students may complete up to 6 credits outside of CS.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f80', 'requirement', 'Exam subplan must be declared before 19 CS credits', 'An exam subplan must be declared and approved before the student completes 19 credits of CS coursework.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Exam subplan must be declared and approved before completing 19 credits of CS coursework.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f81', 'requirement', 'Exam comprehensive oral exam, two attempts', 'On the exam subplans, students choose a specialized area covered by CS 600/700-level courses and approved by the graduate affairs committee, take 3 courses in that area, form a committee (one chair, two other departmental members, and one from outside), and take an oral exam on assigned papers or reading. Students have only two attempts to pass the comprehensive oral exam, and must pass a final comprehensive oral examination to graduate.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Students will have only two attempts to pass the comprehensive oral exam.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f82', 'requirement', 'In-program GPA and two-semester probation window (catalog)', 'The 2026-2027 catalog says a student''s total GPA must be 3.00 or higher while in the program. If it falls below 3.00, the student is placed on academic probation and must have an overall GPA of at least 3.00 by the end of two subsequent semesters, or be separated from the graduate program. This conflicts with existing department-master''s-page fact f10, whose detail said a student may be dropped if the GPA stays below 3.0 the next regular semester. The catalog wording (''two subsequent semesters'') is kept alongside f10; no winner is chosen.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'A student whose GPA falls below 3.00 will be placed on academic probation. That student must have an overall GPA of at least 3.00 by the end of two subsequent semesters; otherwise the student will be separated from the graduate program.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f83', 'course', 'Exam track Foundations and Theory required list (catalog)', 'Exam subplan 4, Foundations and Theory: complete a total of 9 credits from CS 656 Automata and Formal Languages, CS 677 Analysis of Algorithms, CS 715 Advanced Analysis of Algorithms, CS 758 Computational Geometry, and CS 789 Topics in Advanced Computer Science. This is the official catalog form of existing plan-of-study facts f17-f20, with course titles added.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Subplan 4 Requirements: Exam - Foundations and Theory Total Credits Required: 30 Course Requirements Required Courses - Credits: 9 Complete a total of 9 credits from the following courses.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f84', 'course', 'Exam track Cyber Security required list', 'Exam subplan 5, Cyber Security: complete a total of 9 credits from CS 643 Information Assurance, CS 645 Internet Security, CS 648 Computer Security, CS 649 Computer and Network Forensics, CS 665 Computer Networks I, and CS 789 Topics in Advanced Computer Science.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Subplan 5 Requirements: Exam - Cyber Security Total credits required: 30 Course Requirements Required Courses - Credits: 9 Complete a total of 9 credits from the following courses.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f85', 'course', 'Exam track AI and Machine Learning required list', 'Exam subplan 6, AI and Machine Learning: complete a total of 9 credits from CS 622 Introduction to Machine Learning, CS 682 Artificial Intelligence, CS 722 Advanced Machine Learning, CS 781 Automated Deduction, CS 782 Expert System Construction, CS 783 Genetic Algorithms and Neural Networks, and CS 789 Topics in Advanced Computer Science.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Subplan 6 Requirements: Exam - AI and Machine Learning Total credits required: 30 Course Requirements Required Courses - Credits: 9 Complete a total of 9 credits from the following courses.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f86', 'course', 'Exam track Software Engineering required list', 'Exam subplan 7, Software Engineering: complete a total of 9 credits from CS 620 Human-Computer Interaction, CS 672 Software Product Design and Development I, CS 682 Artificial Intelligence, CS 772 Empirical Software Engineering, and CS 789 Topics in Advanced Computer Science.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Subplan 7 Requirements: Exam - Software Engineering Total credits required: 30 Course Requirements Required Courses - Credits: 9 Complete a total of 9 credits from the following courses.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f87', 'course', 'Exam track Data Science and Big Data required list', 'Exam subplan 8, Data Science and Big Data: complete a total of 9 credits from CS 657 Database Management Systems, CS 658 Introduction to Data Mining, CS 672 Software Product Design and Development I, CS 682 Artificial Intelligence, CS 769 Advanced Data Base Management, and CS 783 Genetic Algorithms and Neural Networks.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Subplan 8 Requirements: Exam - Data Science and Big Data Total credits required: 30 Course Requirements Required Courses - Credits: 9 Complete a total of 9 credits from the following courses.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f88', 'course', 'Exam track Database and Information Retrieval required list', 'Exam subplan 9, Database and Information Retrieval: complete a total of 9 credits from CS 657 Database Management Systems, CS 658 Introduction to Data Mining, CS 682 Artificial Intelligence, and CS 769 Advanced Data Base Management.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Subplan 9 Requirements: Exam - Database and Information Retrieval Total credits required: 30 Course Requirements Required Courses - Credits: 9 Complete a total of 9 credits from the following courses.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f89', 'course', 'Exam track Graphics and Augmented Reality required list', 'Exam subplan 10, Graphics and Augmented Reality: complete a total of 9 credits from CS 669 Introduction to Digital Image Processing, CS 680 Computer Graphics, CS 682 Artificial Intelligence, and CS 689 Advanced Computer Science Topics.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Subplan 10 Requirements: Exam - Graphics and Augmented Reality Total credits required: 30 Course Requirements Required Courses - Credits: 9 Complete a total of 9 credits from the following courses.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f90', 'course', 'Exam track Programming Language and Systems required list', 'Exam subplan 11, Programming Language and Systems: complete a total of 9 credits from the following courses. The catalog list on this page names only two courses: CS 656 Automata and Formal Languages and CS 789 Topics in Advanced Computer Science.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Subplan 11 Requirements: Exam - Programming Language and Systems Total credits required: 30 Course Requirements Required Courses - Credits: 9 Complete a total of 9 credits from the following courses.', '2026-11-19T05:31:44.854Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f91', 'course', 'Integrated BS-MS required course list', 'Integrated BS-MS subplan: complete the following nine credits, or other courses approved by the Graduate Coordinator: CS 656 Automata and Formal Languages, CS 660 Compiler Construction, and CS 677 Analysis of Algorithms.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'Complete the following nine credits or other courses approved by the Graduate Coordinator.', '2026-11-19T05:31:44.854Z');
