INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('23-20261118', 'f118', 'course', 'CS 790 Master''s Project', '2026-2027 Graduate Catalog: CS 790 Master''s Project is the 3-credit culminating project course for Project subplan 2. This is the official catalog title; existing plan-of-study fact f15 already listed CS 790 as the 3-credit project requirement.', 'https://catalog.unlv.edu/preview_program.php?catoid=52&poid=14606', 'CS 790 - Master''s Project', '2026-11-19T05:31:44.854Z');
