INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f1', 'overview', 'On-campus delivery', 'The program page lists this M.S. as an on-campus graduate program.', 'https://www.csuchico.edu/academics/majors-programs/computer-science-ms.shtml', 'On Campus', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f2', 'overview', 'Open to any discipline', 'The program is open to applicants from any discipline and includes a computer science theory foundation plus project-based learning.', 'https://www.csuchico.edu/academics/majors-programs/computer-science-ms.shtml', 'Our program is open to applicants from any discipline and combines a strong foundation in computer science theory with practical, project-based learning opportunities.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f3', 'overview', 'Catalog welcome statement', 'The 2026-2027 catalog says the M.S. welcomes students from all undergraduate disciplines, including those without a CS background.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'The Master of Science in Computer Science welcomes students from all undergraduate disciplines. The program is designed to accommodate students with and without a computer science background.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f4', 'overview', 'Students without a CS background', 'The program page says students from any discipline can enter and can take background courses after enrolling.', 'https://www.csuchico.edu/academics/majors-programs/computer-science-ms.shtml', 'Students from any discipline can enter the program. Students without background courses can take all courses after enrolling.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f5', 'requirement', '30 units', 'The 2026-2027 catalog lists 30 total units required.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Total Units Required: 30', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f6', 'requirement', '600-level minimum', 'At least 18 of the units required for the degree must be in 600-level courses.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'At least 18 of the units required for the degree in 600-level courses.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f7', 'requirement', 'Core courses', 'Students complete three graduate core courses (nine units): CSCI 608, CSCI 611, or CSCI 612; plus CSCI 630 and CSCI 650.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Completion of three graduate core courses (nine units): CSCI 608, CSCI 611, or CSCI 612; CSCI 630 and CSCI 650.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f8', 'requirement', 'CSCI 605 excluded', 'CSCI 605 may not be taken to meet program requirements.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'CSCI 605 may not be taken to meet program requirements.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f9', 'requirement', 'Most common capstone', 'The most common culminating experience is the capstone course plan.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'The most common culminating experience for master''s students in Computer Science is to demonstrate competency in graduate study by completion of the capstone course using plan (a).', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f10', 'requirement', 'Capstone course CSCI 693', 'The capstone plan is 30 units of in-class coursework including a passing score in CSCI 693, taken in the last 9 units or last semester, with a maximum of three attempts.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'This plan includes 30 units of in-class coursework, including a passing score in the capstone course CSCI 693. CSCI 693 is to be taken as part of the last 9 units, or during the last semester of the graduate program.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f11', 'requirement', 'Project plan qualifications', 'The project plan requires a 3.5 GPA, a faculty nomination, and faculty approval of a project proposal by a 2/3 majority vote.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'maintaining a GPA of 3.5 or above in their post-baccalaureate coursework,', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f12', 'requirement', '3.0 GPA to remain in program', 'Students must maintain a minimum 3.0 GPA in specified coursework categories.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Students must maintain a minimum 3.0 grade point average in each of the following three categories: all coursework taken at any accredited institution subsequent to admission to the master''s program;', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f13', 'requirement', 'C-grade limit', 'No more than two courses with a grade of C may count toward the approved program.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'In addition, students may not count more than two courses in which they receive a grade of C toward the approved program.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f14', 'requirement', 'Five-year time limit', 'All degree requirements must be completed within five years, and the department says no course validation or program extensions will be granted.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Due to the rapid changes in the field of computer science, the Department of Computer Science requires all candidates to complete the program within five years, including projects and theses. No course validation will be allowed and no program extensions will be granted.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f16', 'requirement', 'GRE in catalog', 'The 2026-2027 catalog requires a combined GRE verbal and quantitative score of 300 and exempts graduates of an ABET-accredited program in computer science (it does not mention a related discipline).', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Completion of the Graduate Record Examination (GRE) with a combined score of 300 on the verbal and quantitative portions. Graduates of an ABET accredited program in computer science are exempt from this requirement.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f17', 'requirement', 'Statement of purpose', 'A statement of purpose is required; the program page lists a resume as optional.', 'https://www.csuchico.edu/academics/majors-programs/computer-science-ms.shtml', 'Statement of purpose, resume (optional)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f18', 'requirement', 'Letters of reference in catalog', 'The catalog lists submission of two letters of reference among classified-status prerequisites.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Submission of two letters of reference.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f19', 'requirement', 'Prerequisite courses for classified status', 'Classified status requires completion of program prerequisites equivalent to CSCI 111, 211, 217, 311, 370, 430, and 440, which do not count toward the M.S.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Courses taken for the purpose of advancement to classified status will not be used towards the MS degree.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f20', 'requirement', 'CSCI 211 and 311 restriction', 'Only courses from ABET-accredited programs may be used for CSCI 211 and CSCI 311.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Only courses from ABET accredited programs may be used for CSCI 211 and CSCI 311.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f21', 'course', 'CSCI 608', 'CSCI 608 Data Science for Graduate Studies (3 units), 2026-27 Chico catalog: This course covers foundational practices of data science emphasizing reproducibility and ethical practices at all stages of the data science lifecycle.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course covers foundational practices of data science emphasizing reproducibility and ethical practices at all stages of the data science lifecycle.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f22', 'course', 'CSCI 611', 'CSCI 611 Applied Machine Learning (3 units), 2026-27 Chico catalog: The course offers a practical exploration into machine learning and cutting-edge topics in neural networks, including modern techniques for deep learning. Students build deep learning models using sophisticated machine learning frameworks and scientific libraries. 3 hours lecture.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'The course offers a practical exploration into machine learning and cutting-edge topics in neural networks, including modern techniques for deep learning. Students build deep learning models using sophisticated machine learning frameworks and scientific libraries. 3 hours lecture.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f23', 'course', 'CSCI 612', 'CSCI 612 Applied Computer Vision (3 units), 2026-27 Chico catalog: Applied computer vision used in automation, robotics, physical security, surveillance, and inspection applications and systems.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'Applied computer vision used in automation, robotics, physical security, surveillance, and inspection applications and systems.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f24', 'course', 'CSCI 630', 'CSCI 630 Software Design and Maintenance (3 units), 2026-27 Chico catalog: Students conduct a study of designing and maintaining complex software. The course builds upon fundamental software engineering skills with an emphasis on: object-oriented software design patterns, anti-patterns, code review and refactoring, and tools for evaluating code quality.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'Students conduct a study of designing and maintaining complex software. The course builds upon fundamental software engineering skills with an emphasis on: object-oriented software design patterns, anti-patterns, code review and refactoring, and tools for evaluating code quality.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f25', 'course', 'CSCI 650', 'CSCI 650 Algorithms and Computability (3 units), 2026-27 Chico catalog: This course presents algorithm design techniques (such as divide-and-conquer, greedy algorithms, dynamic programming, and others), mathematical and empirical analysis of algorithms , computability, Rice''s theorem, P and NP classes, NP-completeness, and recent advances in algorithms. 3 hours lecture.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course presents algorithm design techniques (such as divide-and-conquer, greedy algorithms, dynamic programming, and others), mathematical and empirical analysis of algorithms , computability, Rice''s theorem, P and NP classes, NP-completeness, and recent advances in algorithms. 3 hours lecture.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f26', 'course', 'CSCI 693', 'CSCI 693 Research Methods in Computer Science (3 units), 2026-27 Chico catalog: This course interweaves three distinct themes (investigation, experimentation, and technical writing), that culminate in a comprehensive research project, written report, presentation, and oral defense. First, the students are immersed into the research process within Computer Science.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course interweaves three distinct themes (investigation, experimentation, and technical writing), that culminate in a comprehensive research project, written report, presentation, and oral defense. First, the students are immersed into the research process within Computer Science.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f27', 'course', 'CSCI 699P', 'CSCI 699P Master''s Project (3 units), 2026-27 Chico catalog: You must register directly with a supervising faculty member. Independent study and investigation of special problems in student''s area of concentration. Both registration and study plan must have approval of the instructor and the student''s graduate advisory committee chair.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'You must register directly with a supervising faculty member. Independent study and investigation of special problems in student''s area of concentration. Both registration and study plan must have approval of the instructor and the student''s graduate advisory committee chair.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f28', 'course', 'CSCI 699T', 'CSCI 699T Master''s Thesis (1-6 units), 2026-27 Chico catalog: This course is offered for 1.0-6.0 units. You must register directly with a supervising faculty member. Independent study and investigation of special problems in student''s area of concentration.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course is offered for 1.0-6.0 units. You must register directly with a supervising faculty member. Independent study and investigation of special problems in student''s area of concentration.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f29', 'course', 'CSCI 605', 'CSCI 605 Data Structures and Algorithms for Data Science (3 units), 2026-27 Chico catalog: This course focuses on object-oriented methodologies in designing and implementing a variety of data structures and algorithms using the Python programming language. Coverage includes recursion, trees, search structures, hashing, heaps, sorting algorithms, and graph algorithms.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course focuses on object-oriented methodologies in designing and implementing a variety of data structures and algorithms using the Python programming language. Coverage includes recursion, trees, search structures, hashing, heaps, sorting algorithms, and graph algorithms.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f30', 'course', 'Writing proficiency', 'Writing proficiency is demonstrated by passing CSCI 693, CSCI 699P, or CSCI 699T.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Computer science students will demonstrate their writing competence in the English language by successfully passing CSCI 693, CSCI 699P, or CSCI 699T.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f31', 'deadline', 'Fall deadline', 'The program page lists a Fall application deadline of April 1.', 'https://www.csuchico.edu/academics/majors-programs/computer-science-ms.shtml', 'Fall: April 1', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f32', 'deadline', 'Spring deadline', 'The program page lists a Spring deadline of December 1, and October 1 for international applicants.', 'https://www.csuchico.edu/academics/majors-programs/computer-science-ms.shtml', 'Spring: December 1 (October 1 for international applicants)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f33', 'deadline', 'Blended program deadlines', 'The blended BS + MS application deadlines are April 1 for fall start and November 1 for spring start; GRE is not required for the blended path.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/computer-science-ms/', 'Application deadlines: April 1 for fall start, November 1 for spring start.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f34', 'faculty', 'Department listing', 'The department faculty-and-staff page is a department-wide listing and does not include research blurbs.', 'https://www.csuchico.edu/academics/college/engineering/departments/computer-science/faculty-staff.shtml', 'Todd Gibson Chair and Professor', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f35', 'faculty', 'Todd Gibson', 'Listed as Chair and Professor; directory profile has no research description.', 'https://www.csuchico.edu/academics/college/engineering/departments/computer-science/faculty-staff.shtml', 'Todd Gibson Chair and Professor', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f36', 'faculty', 'Abbas Attarwala', 'Chico State Today news story: funded research project on the impact of AI on children (privacy, education, social development, misinformation, discrimination).', 'https://today.csuchico.edu/growing-pains-of-ai/', 'Attarwala will primarily look at what research has been done and synthesize his findings to speak meaningfully about the impact of AI on children''s privacy, education, social development, and even things like misinformation and discrimination within the AI models.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f37', 'faculty', 'Kevin Buffardi', 'Chico Graduate Studies faculty profile lists areas of interest: software engineering and educational research.', 'https://www.csuchico.edu/graduatestudies/about-us/grad-faculty-profiles.shtml', 'Kevin Buffardi Computer Science Associate Professor Specific Areas of Interest: Software Engineering Educational Research', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f38', 'faculty', 'Bryan Dixon', 'Personal faculty website (not a csuchico.edu page): research on smartphone security, lightweight malicious-code and anomaly detection.', 'https://www.bryancdixon.com/', 'Most of my research to this point has been about smartphone security. I have primarily investigated lightweight techniques for detection of malicious code or anomaly detection techniques as a mechanism for determining if something malicious or undesired is happening on a smartphone.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f39', 'faculty', 'Ben Juliano', 'Faculty research page (ecst.csuchico.edu) lists research interests in data visualization and predictive analytics (page also has a robotics and machine learning section).', 'https://www.ecst.csuchico.edu/~juliano/Research/index.html', 'research interests data visualization and predictive analytics', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f40', 'faculty', 'Bo Shen', 'Listed as Associate Professor; no research blurb on the department listing.', 'https://www.csuchico.edu/academics/college/engineering/departments/computer-science/faculty-staff.shtml', 'Bo Shen Associate Professor', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f41', 'faculty', 'Samuel B Siewert', 'Chico Graduate Studies faculty profile lists areas of interest: sensor fusion, physics-informed AI, high-performance computing.', 'https://www.csuchico.edu/graduatestudies/about-us/grad-faculty-profiles.shtml', 'Sam Siewert Computer Science Associate Professor Specific Areas of Interest: Sensor Fusion Physics Informed AI High-Performance Computing', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f42', 'faculty', 'Kun Tian', 'Chico Graduate Studies faculty profile lists areas of interest: peer review, token economy, CS teaching effectiveness, modeling and assessment.', 'https://www.csuchico.edu/graduatestudies/about-us/grad-faculty-profiles.shtml', 'Kun Tian Computer Science Associate Professor Specific Areas of Interest: Peer review Token Economy Computer Science Teaching Effectiveness Modeling and Assessment', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f43', 'faculty', 'Richard C Tillquist', 'Chico Graduate Studies faculty profile lists areas of interest: machine learning, graph theory ("Graphy theory" on page), data science; projects on metric dimension and source identification/network spread.', 'https://www.csuchico.edu/graduatestudies/about-us/grad-faculty-profiles.shtml', 'Richard Tillquist Computer Science Assistant Professor Specific Areas of Interest: Machine learning Graphy theory Data Science Recent Publications/Projects: Metric dimension and its applications Source identification and network spread', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f44', 'faculty', 'David Zeichick', 'Listed as Associate Professor; no research blurb on the department listing.', 'https://www.csuchico.edu/academics/college/engineering/departments/computer-science/faculty-staff.shtml', 'David Zeichick Associate Professor', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f45', 'faculty', 'Oleksiy Al-Saadi', 'Chico State announcement bio: works on theoretical computer science and faster algorithmic solutions under restrictions; interested in reductions.', 'https://www.csuchico.edu/announcements/2026-02/26-02-17-digital-humanities-series-oleksiy-al-saadi-what-is-computation-the-philosophy-of-turing-machines-march-th-pm-zoom.shtml', 'His work focuses on theoretical computer science and the study of finding faster, algorithmic solutions to challenging problems under certain restrictions. He also has great interest in reductions,', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f46', 'faculty', 'Kathleen Isenegger', 'Listed as Assistant Professor; no research blurb on the department listing.', 'https://www.csuchico.edu/academics/college/engineering/departments/computer-science/faculty-staff.shtml', 'Kathleen Isenegger Assistant Professor', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'f47', 'faculty', 'Jaime Raigoza', 'Chico CURE-E fellow page lists research interests: CS education, bringing quantum information science to undergraduates, mentoring undergraduate research.', 'https://www.csuchico.edu/curee/fellows-program/raigoza.shtml', 'Research Interests: Research Interests: Computer Science Education Bringing Quantum Information Science to Undergraduates Mentoring Undergraduate Research', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e1', 'course', 'CSCI 511', 'CSCI 511 Advanced Object-Oriented Programming (3 units), 2026-27 Chico catalog: This course is dedicated to the analysis, design, and implementation of programming problems using an object-oriented approach. Modern object-oriented languages are utilized.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course is dedicated to the analysis, design, and implementation of programming problems using an object-oriented approach. Modern object-oriented languages are utilized.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e2', 'course', 'CSCI 515', 'CSCI 515 Compiler Design (3 units), 2026-27 Chico catalog: The elements of lexical, syntactical, and semantic analysis including finite and push-down automata, top-down and bottom-up parsing, error detection and recovery, semantic actions and code generation. 3 hours discussion.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'The elements of lexical, syntactical, and semantic analysis including finite and push-down automata, top-down and bottom-up parsing, error detection and recovery, semantic actions and code generation. 3 hours discussion.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e3', 'course', 'CSCI 520', 'CSCI 520 Applied Quantum Computing for Computer Scientists (3 units), 2026-27 Chico catalog: This course introduces the practice of quantum computation and algorithms in computer science. Topics include the mathematics to understand the relationship between physical systems and quantum computation.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course introduces the practice of quantum computation and algorithms in computer science. Topics include the mathematics to understand the relationship between physical systems and quantum computation.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e4', 'course', 'CSCI 540', 'CSCI 540 Systems Programming (3 units), 2026-27 Chico catalog: A hands-on project course that examines the development of systems software. It provides an introduction to writing low level programs in the UNIX/Linux environment.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'A hands-on project course that examines the development of systems software. It provides an introduction to writing low level programs in the UNIX/Linux environment.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e5', 'course', 'CSCI 546', 'CSCI 546 Network Forensics (3 units), 2026-27 Chico catalog: This course provides an in-depth understanding of the principles and techniques used in network forensic, including the collection, preservation, analysis, and presentation of digital evidence from network-based incidents.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course provides an in-depth understanding of the principles and techniques used in network forensic, including the collection, preservation, analysis, and presentation of digital evidence from network-based incidents.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e6', 'course', 'CSCI 548', 'CSCI 548 Digital Forensics (3 units), 2026-27 Chico catalog: This course provides an understanding of foundational terms, concepts, elements, and the overarching goals that drive a digital forensic investigation.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course provides an understanding of foundational terms, concepts, elements, and the overarching goals that drive a digital forensic investigation.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e7', 'course', 'CSCI 551', 'CSCI 551 Numerical Methods and Parallel Programming (4 units), 2026-27 Chico catalog: Surveys numerical methods and parallel programming. Parallel architectures and algorithms for scientific programming applications, solution of simultaneous linear and non-linear equations, iterative techniques, matrix methods, and error analysis.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'Surveys numerical methods and parallel programming. Parallel architectures and algorithms for scientific programming applications, solution of simultaneous linear and non-linear equations, iterative techniques, matrix methods, and error analysis.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e8', 'course', 'CSCI 565', 'CSCI 565 Server Side App Development (3 units), 2026-27 Chico catalog: A hands-on project course emphasizing server-side full-stack development that examines languages, tools, protocols, and techniques for developing robust server-side interfaces and how to integrate them into cross-platform apps.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'A hands-on project course emphasizing server-side full-stack development that examines languages, tools, protocols, and techniques for developing robust server-side interfaces and how to integrate them into cross-platform apps.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e9', 'course', 'CSCI 566', 'CSCI 566 Computer Graphics Programming (3 units), 2026-27 Chico catalog: This course covers algorithms and data structures in computer graphics. Topics include output primitives and their attributes, 2-D and 3-D geometric transformations and viewing, 3-D object modeling, parallel and perspective projections, visible surface detection, illumination models, and rendering', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course covers algorithms and data structures in computer graphics. Topics include output primitives and their attributes, 2-D and 3-D geometric transformations and viewing, 3-D object modeling, parallel and perspective projections, visible surface detection, illumination models, and rendering', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e10', 'course', 'CSCI 567', 'CSCI 567 Client Side App Development (3 units), 2026-27 Chico catalog: A hands-on project course emphasizing client-side full-stack development that examines languages, tools, protocols, and techniques for developing robust client-side applications for mobile and web apps.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'A hands-on project course emphasizing client-side full-stack development that examines languages, tools, protocols, and techniques for developing robust client-side applications for mobile and web apps.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e11', 'course', 'CSCI 570', 'CSCI 570 Advanced Database Management Systems (3 units), 2026-27 Chico catalog: Course topics include database application programming using a high performance, high concurrency multi-user database management system. This course covers the SQL programming language including Data Definition Language, Data Manipulation Language, and Data Control Language.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'Course topics include database application programming using a high performance, high concurrency multi-user database management system. This course covers the SQL programming language including Data Definition Language, Data Manipulation Language, and Data Control Language.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e12', 'course', 'CSCI 580', 'CSCI 580 Artificial Intelligence (3 units), 2026-27 Chico catalog: This course introduces the basic principles, techniques, and applications of artificial intelligence. This course is organized in three sections: search, logic, and learning.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course introduces the basic principles, techniques, and applications of artificial intelligence. This course is organized in three sections: search, logic, and learning.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e13', 'course', 'CSCI 581', 'CSCI 581 Machine Learning (3 units), 2026-27 Chico catalog: This course introduces students to the concepts, theories, and experimental methods of machine learning. This course develops a broad understanding of the issues in implementing machine learning algorithms and systems, especially as they relate to modern data-intensive problems.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course introduces students to the concepts, theories, and experimental methods of machine learning. This course develops a broad understanding of the issues in implementing machine learning algorithms and systems, especially as they relate to modern data-intensive problems.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e14', 'course', 'CSCI 582', 'CSCI 582 Bioinformatics (3 units), 2026-27 Chico catalog: An introduction to computational methods for Next Generation Sequencing data analysis. Topics include mapping sequenced reads back to a reference genome; approximate string matching; intro to biostatistics; probability distribution, hypothesis testing; identification of SNPs (single polymorphisms);', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'An introduction to computational methods for Next Generation Sequencing data analysis. Topics include mapping sequenced reads back to a reference genome; approximate string matching; intro to biostatistics; probability distribution, hypothesis testing; identification of SNPs (single polymorphisms);', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e15', 'course', 'CSCI 585', 'CSCI 585 Robotics and Machine Intelligence (3 units), 2026-27 Chico catalog: This course introduces students to the field of robotics by emphasizing the use of software to model, task, localize, navigate, and control mobile and manipulator robot systems.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course introduces students to the field of robotics by emphasizing the use of software to model, task, localize, navigate, and control mobile and manipulator robot systems.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e16', 'course', 'CSCI 598', 'CSCI 598 Adv Topic in Computer Science (1-4 units), 2026-27 Chico catalog: This course is a special topic offered for 1.0-4.0 units. Exploration of selected topics in Computer Science. Consult semester schedules for specific listings. Standard letter grading only. 0 hours discussion.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course is a special topic offered for 1.0-4.0 units. Exploration of selected topics in Computer Science. Consult semester schedules for specific listings. Standard letter grading only. 0 hours discussion.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e17', 'course', 'CSCI 620', 'CSCI 620 Web Technology (3 units), 2026-27 Chico catalog: This course examines frameworks, libraries, languages, and tools for the development of full stack web applications that are progressive, responsive, and secure. Students propose, design, develop, test, and present a nontrivial full stack web application. 3 hours seminar.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course examines frameworks, libraries, languages, and tools for the development of full stack web applications that are progressive, responsive, and secure. Students propose, design, develop, test, and present a nontrivial full stack web application. 3 hours seminar.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e18', 'course', 'CSCI 640', 'CSCI 640 Scalable Software Systems (3 units), 2026-27 Chico catalog: This course offers a practical exploration of topics in scalable computing. Students gain hands-on experience building things to solve a multitude of topics in scalable computing. Students learn how to solve computationally complex problems involving big data.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course offers a practical exploration of topics in scalable computing. Students gain hands-on experience building things to solve a multitude of topics in scalable computing. Students learn how to solve computationally complex problems involving big data.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e19', 'course', 'CSCI 644', 'CSCI 644 DevOps Engineering (3 units), 2026-27 Chico catalog: This course introduces students to distributed system administration skills, setting up distributed computation environments, version control, build systems, dependency management, continuous integration, testing, cloud virtualization technologies, and setting up mobile, web, machine learning', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course introduces students to distributed system administration skills, setting up distributed computation environments, version control, build systems, dependency management, continuous integration, testing, cloud virtualization technologies, and setting up mobile, web, machine learning', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e20', 'course', 'CSCI 651', 'CSCI 651 Applied Graph Theory (3 units), 2026-27 Chico catalog: This course covers foundational aspects of network science, the study of graph representations and the patterns they contain, along with tools and techniques for analyzing network data.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course covers foundational aspects of network science, the study of graph representations and the patterns they contain, along with tools and techniques for analyzing network data.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e21', 'course', 'CSCI 682', 'CSCI 682 Topics in Artificial Intelligence (3 units), 2026-27 Chico catalog: Further study of selected advanced topics in artificial intelligence as presented in recently published journals; possible emphasis on research interests and/or projects of faculty in the department. Consult the Graduate Coordinator to determine how many units may be counted toward your major.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'Further study of selected advanced topics in artificial intelligence as presented in recently published journals; possible emphasis on research interests and/or projects of faculty in the department. Consult the Graduate Coordinator to determine how many units may be counted toward your major.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e22', 'course', 'CSCI 697', 'CSCI 697 Independent Study (1-6 units), 2026-27 Chico catalog: This course is an independent study offered for 1.0-6.0 units. You must register directly with a supervising faculty member. Independent study and investigation of special problems in student''s area of concentration.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course is an independent study offered for 1.0-6.0 units. You must register directly with a supervising faculty member. Independent study and investigation of special problems in student''s area of concentration.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('4-20261118', 'e23', 'course', 'CSCI 698', 'CSCI 698 Seminar in Advanced Topics (3 units), 2026-27 Chico catalog: This course is a seminar offered for 1.0-3.0 units. Typical subjects in past semesters have included microprogramming theory, operating system development, software engineering principles, data communications, analysis of algorithms, and program optimization.', 'https://catalog.csuchico.edu/colleges-departments/college-engineering-computer-science-construction-management/computer-science/#coursestext', 'This course is a seminar offered for 1.0-3.0 units. Typical subjects in past semesters have included microprogramming theory, operating system development, software engineering principles, data communications, analysis of algorithms, and program optimization.', '2026-11-19T05:32:43.276Z');
INSERT INTO program_snapshots (snapshot_id, school_id, verified_at) VALUES ('5-20261118', '5', '2026-11-18T20:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f1', 'overview', '30-unit program', 'The prospective-students page describes a 30-unit (10-course) M.S., with 5 required courses, 4 electives, and a capstone.', 'https://www.csueastbay.edu/cs/prospective-students/index.html', 'The M.S. Computer Science degree program is 30 units equivalent to 10 courses. Of these, 5 courses (15 units) are required by all students in the program, 4 courses (12 units) are elective courses, and once course is a capstone experience (3-6 units).', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f2', 'overview', 'Three concentrations', 'Applicants select a concentration: Computer Science, Computer Networking, or Artificial Intelligence and Machine Learning.', 'https://www.csueastbay.edu/cs/prospective-students/index.html', 'When you apply you will be asked to select a concentration. We currently have three concentrations that allow specialization in a particular area.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f3', 'overview', 'Typical load', 'Enrolled M.S. students typically take 1-4 courses (3-12 units) each semester.', 'https://www.csueastbay.edu/cs/prospective-students/index.html', 'Students enrolled in the M.S. graduate program typically take 1-4 courses (3-12 units) each semester, depending on their situation.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f4', 'requirement', 'Admissions review path', 'Applications go first to the university Office of Admissions and are then forwarded to the Computer Science department for an admit or reject decision.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'After the Office of Admissions has completed their review, applications are forwarded to the Computer Science department which makes the decision whether to accept or reject the applicant.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f5', 'requirement', 'GRE required on start page', 'The assigned start page still says GRE general test scores are required, with preferred percentiles above the 20th verbal and 60th quantitative.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'GRE general test scores are required.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f7', 'requirement', 'Undergraduate GPA 3.0', 'Applicants normally need an undergraduate CS or related degree, a 3.0 GPA in all undergraduate work, and a B or better in listed CS and math courses.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'must have a grade point average of 3.0 in all undergraduate work, and must have earned a "B" or better in the Computer Science and Mathematics courses listed below.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f8', 'requirement', 'Preferred B+ in important courses', 'The start page says the department prefers at least a B+ average in the important courses.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'Currently, to be eligible for admission into the M.S. program, we prefer at least a B+ average in the important courses.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f9', 'requirement', 'International class standing', 'For international applicants, the department looks for students who graduated first class or first class with distinction.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'For international applicants, we look for students who have graduated first class or first class with distinction.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f10', 'requirement', 'Conditional admission', 'Applicants missing some course prerequisites may be admitted as Conditionally Classified if they have completed at least Data Structures and most lower-division prerequisites.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'may be admitted to the program at the discretion of the department as a "Conditionally Classified Graduate" student, provided the student''s record clearly demonstrates the capability of completing all the course requirements after admission.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f11', 'requirement', 'Deficiency grades on start page', 'The start page says course deficiencies or remediation must be completed with grades of B or better before enrolling in graduate CS courses, and those courses do not count toward the master''s degree.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'Students must complete any course deficiencies or remediation with grades of "B" or better. Course deficiencies or remediation must be completed before enrolling in graduate Computer Science courses.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f12', 'requirement', 'Prerequisite grade on first-year page', 'The first-year master''s page says each prerequisite must be passed with a B- or better and does not count toward the M.S. degree.', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'Each prerequisite must be passed with a B− or better and does not count toward the MS degree.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f13', 'requirement', 'Most students conditionally classified', 'The first-year page says nearly all incoming students are admitted as Conditionally Classified.', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'Nearly all incoming students are admitted as Conditionally Classified, which means your admission letter lists prerequisite or remediation courses to complete in addition to your graduate coursework.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f14', 'requirement', 'Lower-division CS prerequisites', 'Required lower-division equivalents include CS 101, CS 201, CS 211, and CS 221.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'CS 101 Computer Science I', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f15', 'requirement', 'Upper-division CS prerequisites', 'Required upper-division equivalents include CS 301, CS 311, CS 321, CS 411, CS 413, and CS 421.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'CS 301 Data Structures and Algorithms', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f16', 'requirement', 'Math prerequisites', 'Mathematics admission requirements include MATH 130, MATH 131, MATH 225, and STAT 316.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'MATH 130 Calculus I', '2026-11-19T05:32:45.088Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f17', 'requirement', 'Junior college limit', 'Junior-college courses may fulfill lower-division but not upper-division admission prerequisites.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'Courses from junior colleges can be used to fulfill lower division admission prerequisites (100 and 200 level) but not upper division admission prerequisites (300 or 400 level.)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f18', 'requirement', 'Open University note', 'Students who lack enough prerequisites may use Open University; the page says Open University students have last registration priority and no student visa is sponsored by that program.', 'https://www.csueastbay.edu/cs/degrees-programs1/csms.html', 'While Open University allows students to take courses before being accepted to the Master''s program, Open University students have the last registration priority and no student visa are sponsored by the Open University program.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f19', 'requirement', 'Graduate GPA', 'The first-year page requires 30 units of 600-level coursework, each passed with a C or better, and an overall 3.0 graduate GPA.', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'The MS in Computer Science requires 30 units of 600-level coursework, each passed with a C or better and an overall 3.0 graduate GPA.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f20', 'course', 'Five required core courses', 'Every student completes five required core courses: CS 601, CS 611, CS 621, CS 651, and CS 671.', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'Every student completes five required core courses: CS 601, CS 611, CS 621, CS 651, and CS 671.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f21', 'course', 'Capstone options', 'The capstone is the Comprehensive Exam (CS 692), a Project (CS 693), or a Thesis (CS 699).', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'You also complete a concentration and a capstone — the Comprehensive Exam (CS 692), a Project (CS 693), or a Thesis (CS 699).', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f22', 'course', 'CS 601', 'CS 601 Advanced Algorithms (3 units), CSUEB CS department course list: Design, analysis, and implementation of algorithms; asymptotic notation and efficiency classes; recurrence relations; advanced searching and sorting techniques; string matching; heaps and priority queues; linked structures; balanced and threaded trees; graph algorithms; heuristics;', 'https://www.csueastbay.edu/cs/courses/index.html', 'Design, analysis, and implementation of algorithms; asymptotic notation and efficiency classes; recurrence relations; advanced searching and sorting techniques; string matching; heaps and priority queues; linked structures; balanced and threaded trees; graph algorithms; heuristics;', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f23', 'course', 'CS 621', 'CS 621 Operating Systems Design (3 units), CSUEB CS department course list: Advanced concepts in operating systems theory and practice. Topics may include process synchronization, concurrency, resource management, security, performance evaluation, analytic models, human interfaces, and implementation issues.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Advanced concepts in operating systems theory and practice. Topics may include process synchronization, concurrency, resource management, security, performance evaluation, analytic models, human interfaces, and implementation issues.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f24', 'course', 'CS 651', 'CS 651 Web Systems (3 units), CSUEB CS department course list: Current practices and trends in software design, development, and deployment of web-based systems, with particular emphasis on e-commerce. Projects incorporating the latest technologies and techniques used by the Internet community. Review of literature.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Current practices and trends in software design, development, and deployment of web-based systems, with particular emphasis on e-commerce. Projects incorporating the latest technologies and techniques used by the Internet community. Review of literature.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f25', 'course', 'CS 611', 'CS 611 Theory of Computation (3 units), CSUEB CS department course list: Alphabets, strings and languages, regular languages and finite automata, context-free languages, grammars, context-sensitivity, Turing machines and Turing-Completeness, decidability, Church-Turing thesis, reducibility, time and space complexity classes, P versus NP, NP-Completeness and NP-Hard', 'https://www.csueastbay.edu/cs/courses/index.html', 'Alphabets, strings and languages, regular languages and finite automata, context-free languages, grammars, context-sensitivity, Turing machines and Turing-Completeness, decidability, Church-Turing thesis, reducibility, time and space complexity classes, P versus NP, NP-Completeness and NP-Hard', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f26', 'course', 'CS 671', 'CS 671 Cybersecurity (3 units), CSUEB CS department course list: Security principles, scope and vulnerabilities of Cyberspace, the problem of identity, privacy, malicious software, data security, cryptography, authentication in distributed systems, e-mail security, network security, wireless security, offensive security.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Security principles, scope and vulnerabilities of Cyberspace, the problem of identity, privacy, malicious software, data security, cryptography, authentication in distributed systems, e-mail security, network security, wireless security, offensive security.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f27', 'course', 'AI/ML concentration courses', 'The AI/ML roadmap adds CS 661 Advanced Artificial Intelligence, CS 667 Machine Learning, and CS 663 Computer Vision. The form is dated July 31, 2015.', 'https://www.csueastbay.edu/cs/files/docs/ms-cs-aiml-concentration-roadmap.pdf', 'CS 661      Advanced Artificial Intelligence', '2026-11-19T05:32:45.088Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f28', 'course', 'CS 692', 'CS 692 Capstone Examinations (3 units), CSUEB CS department course list: A synthesis of important areas of Computer Science, culminating in comprehensive examinations covering three required courses in the Master''s degree: Advanced Algorithms, Theory of Computation, and Operating System Design.', 'https://www.csueastbay.edu/cs/courses/index.html', 'A synthesis of important areas of Computer Science, culminating in comprehensive examinations covering three required courses in the Master''s degree: Advanced Algorithms, Theory of Computation, and Operating System Design.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f29', 'course', 'CS 692 attempts', 'CS 692 is 3 units, graded CR/NC; students must pass all three exams and have a maximum of three attempts.', 'https://www.csueastbay.edu/cs/graduate-capstone/faq-cs-692-capstone-exam.html', 'CS 692 Capstone Exams is a three (3) unit class. Grading is CR/NC. Students need to pass all three exams to earn a credit for the class.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f30', 'course', 'CS 693', 'CS 693 Capstone Project (1-4 units), CSUEB CS department course list: Implementation of a substantial project in an advanced area of computer science. Supervision by a departmental committee, at least one of whom must be a California State University East Bay Computer Science faculty member.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Implementation of a substantial project in an advanced area of computer science. Supervision by a departmental committee, at least one of whom must be a California State University East Bay Computer Science faculty member.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f31', 'course', 'CS 699', 'CS 699 Capstone Thesis (1-6 units), CSUEB CS department course list: Development and completion of a formal research paper in an advanced area of computer science for submission to the department, which specifies its format. Supervision by a departmental committee, at least one of whom must be a California State University East Bay Computer Science faculty member.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Development and completion of a formal research paper in an advanced area of computer science for submission to the department, which specifies its format. Supervision by a departmental committee, at least one of whom must be a California State University East Bay Computer Science faculty member.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f32', 'deadline', 'Pay fees by the deadline', 'The first-year page warns students to pay fees by the deadline, even if waitlisted, or they can be dropped from all classes.', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'Pay your fees by the deadline — even if you are waitlisted. Unpaid fees can drop you from all classes.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f33', 'deadline', 'International full-time enrollment', 'F-1 students must enroll in at least 8 units each fall and spring and may take only one fully online course per semester.', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'International (F-1) students must enroll in at least 8 units each fall and spring.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f34', 'deadline', 'Financial aid and prerequisites', 'Financial aid is based on degree-applicable 600-level units; prerequisites alone do not establish aid eligibility. The page advises including at least 4 units of 600-level coursework each term.', 'https://www.csueastbay.edu/cs/first-year-masters-students/index.html', 'Because prerequisites are undergraduate courses that do not count toward the degree, enrolling in prerequisites alone — even a full load — does not establish aid eligibility.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f35', 'faculty', 'Department listing is department-wide', 'The Faculty & Staff page is a department-wide directory, not limited to this M.S. program.', 'https://www.csueastbay.edu/cs/faculty-staff/index.html', 'CSUEB Computer Science Professors', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f36', 'faculty', 'Varick Erickson', 'Listed as Graduate Coordinator on the department faculty page. His directory profile did not include a research blurb in the extracted text.', 'https://www.csueastbay.edu/cs/faculty-staff/index.html', 'Erickson, Varick', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f37', 'faculty', 'Levent Ertaul research', 'His directory profile lists cybersecurity and related research areas. The listing is department-wide.', 'https://www.csueastbay.edu/directory/profiles/cs/ertaullevent.html', 'Research: Cyber Security & Privacy, Cyber War, Hacking Technoligies, Cyber Security Policies, Computer Networks Security, Cryptology, Wireless Security, Cloud Security, International Governance of Cyber Space', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f38', 'faculty', 'Lynne Grewe research', 'Her directory profile lists computer vision, machine learning and AI, and media in social and mobile applications.', 'https://www.csueastbay.edu/directory/profiles/cs/grewelynne.html', 'Computer Vision, Machine Learning & Artificial Intelligence, Media in Social and Mobile Applications', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f39', 'faculty', 'Matt Johnson research', 'His directory profile lists genetic algorithms and artificial intelligence.', 'https://www.csueastbay.edu/directory/profiles/cs/johnsonmatthew.html', 'Research: Genetic Algorithms, Artificial Intelligence', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f40', 'faculty', 'Farzan Roohparvar research', 'His directory profile lists system-on-chip design and related areas. The department page also lists him as Interim Department Chair.', 'https://www.csueastbay.edu/directory/profiles/cs/roohparvarfarzan.html', 'Research: System On Chip (SOC) Design', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f41', 'faculty', 'Yashas Hariprasad research', 'His directory profile describes research at the intersection of AI, cybersecurity, digital forensics, and quantum-safe communication.', 'https://www.csueastbay.edu/directory/profiles/cs/hariprasadyashas.html', 'My expertise lies at the convergence of artificial intelligence, cybersecurity, digital forensics, and quantum-safe communication.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f42', 'faculty', 'Jiaofei Zhong focus', 'Her directory profile lists a professional focus in extended reality, data engineering, and STEM education.', 'https://www.csueastbay.edu/directory/profiles/cs/zhongfay.html', 'Extended Reality, Data Engineering, STEM Education', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f43', 'faculty', 'Farzan Roohparvar title', 'The department faculty page lists Farzan (Bobby) Roohparvar as Interim Department Chair and Professor.', 'https://www.csueastbay.edu/cs/faculty-staff/index.html', 'Roohparvar, Farzan (Bobby)- Interim Department Chair', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'f44', 'faculty', 'Levent Ertaul title', 'The department faculty page lists Levent Ertaul as Department Chair and Professor.', 'https://www.csueastbay.edu/cs/faculty-staff/index.html', 'Ertaul, Levent - Department Chair', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e1', 'course', 'CS 603', 'CS 603 Advanced Software Engineering (3 units), CSUEB CS department course list: Advanced concepts of object-oriented design; software development life-cycle models; software modeling; requirements gathering and analysis; pattern-based design of software; patterns as re-usable architecture; implementation of layered architecture code; software testing.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Advanced concepts of object-oriented design; software development life-cycle models; software modeling; requirements gathering and analysis; pattern-based design of software; patterns as re-usable architecture; implementation of layered architecture code; software testing.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e2', 'course', 'CS 605', 'CS 605 Information Coding and Cryptography (3 units), CSUEB CS department course list: The study of data coding and cryptography. Topics may include: information content, Markov models, data compression codes, error correction and detection codes, symmetric and asymmetric key exchange, and other cryptographic techniques. Programming assignments and review of literature.', 'https://www.csueastbay.edu/cs/courses/index.html', 'The study of data coding and cryptography. Topics may include: information content, Markov models, data compression codes, error correction and detection codes, symmetric and asymmetric key exchange, and other cryptographic techniques. Programming assignments and review of literature.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e3', 'course', 'CS 607', 'CS 607 Parallel Programming (3 units), CSUEB CS department course list: Parallel programming fundamental principles and programming techniques. Topics may include: parallel architectures, principles of parallel algorithm design, programming shared-address space systems and scalable systems, non-numerical and numerical algorithms, GPU Programming, Visualization tools.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Parallel programming fundamental principles and programming techniques. Topics may include: parallel architectures, principles of parallel algorithm design, programming shared-address space systems and scalable systems, non-numerical and numerical algorithms, GPU Programming, Visualization tools.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e4', 'course', 'CS 615', 'CS 615 Compiler Design (3 units), CSUEB CS department course list: Overview of compilation, lexical analysis, regular expressions, context-free grammars, top-down parsing and bottom-up parsing, semantic analysis, attribute grammars, ASTs, type-checking, intermediate representations, and constructing simple compilers.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Overview of compilation, lexical analysis, regular expressions, context-free grammars, top-down parsing and bottom-up parsing, semantic analysis, attribute grammars, ASTs, type-checking, intermediate representations, and constructing simple compilers.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e5', 'course', 'CS 623', 'CS 623 Cloud Computing (3 units), CSUEB CS department course list: Cloud computing theory and protocols. Topics may include: Infrastructure/Platform/Software - as-a-service, cloud OS, architectures including Federated Clouds, principles of Virtualization platforms, security / privacy issues, Internet of things / data-intensive computing.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Cloud computing theory and protocols. Topics may include: Infrastructure/Platform/Software - as-a-service, cloud OS, architectures including Federated Clouds, principles of Virtualization platforms, security / privacy issues, Internet of things / data-intensive computing.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e6', 'course', 'CS 625', 'CS 625 Advanced Computer Architecture (3 units), CSUEB CS department course list: Analysis and design of computer architecture. Topics may include: Processor: instruction set principles, building data path, Instruction Pipelining: data/control hazards, Memory Hierarchy: caches, virtual memory, data/thread-level parallelism, multicore and distributed processors.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Analysis and design of computer architecture. Topics may include: Processor: instruction set principles, building data path, Instruction Pipelining: data/control hazards, Memory Hierarchy: caches, virtual memory, data/thread-level parallelism, multicore and distributed processors.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e7', 'course', 'CS 631', 'CS 631 Database Systems (3 units), CSUEB CS department course list: Design issues in current database systems. Topics may include: data models, storage management and access, distributed systems, query languages and query optimization, database integrity and security, encryption and decryption, concurrency control. Programming projects and review of literature.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Design issues in current database systems. Topics may include: data models, storage management and access, distributed systems, query languages and query optimization, database integrity and security, encryption and decryption, concurrency control. Programming projects and review of literature.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e8', 'course', 'CS 641', 'CS 641 Advanced Computer Networks (3 units), CSUEB CS department course list: Advanced concepts in computer network theory and practice. Specific emphasis on protocols, services, design issues and performance. Topics may include routing, software-defined networks, data-centers, overlay networks, and wireless technologies.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Advanced concepts in computer network theory and practice. Specific emphasis on protocols, services, design issues and performance. Topics may include routing, software-defined networks, data-centers, overlay networks, and wireless technologies.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e9', 'course', 'CS 643', 'CS 643 Distributed Systems (3 units), CSUEB CS department course list: Distributed Systems theory and semantics. Topics may include: temporal logic, proof of program properties, time (logical clocks), state (distributed snapshots), fault-tolerance, replication, rollback recovery, processes and threads, Remote Procedure Calls, file systems.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Distributed Systems theory and semantics. Topics may include: temporal logic, proof of program properties, time (logical clocks), state (distributed snapshots), fault-tolerance, replication, rollback recovery, processes and threads, Remote Procedure Calls, file systems.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e10', 'course', 'CS 645', 'CS 645 Network Analysis and Design (3 units), CSUEB CS department course list: The practice of network analysis and design. Topics may include estimation of traffic demand, requirements specification, topology design, network cost analysis, routing, wired and wireless technologies, design tools, and fault tolerance. Programming assignments and review of literature.', 'https://www.csueastbay.edu/cs/courses/index.html', 'The practice of network analysis and design. Topics may include estimation of traffic demand, requirements specification, topology design, network cost analysis, routing, wired and wireless technologies, design tools, and fault tolerance. Programming assignments and review of literature.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e11', 'course', 'CS 661', 'CS 661 Advanced Artificial Intelligence (3 units), CSUEB CS department course list: Intelligence, rational agent design, state-spaces, search, heuristic functions and A*, game playing, knowledge representation, formal logic, reasoning, expert systems, machine learning paradigms including neural networks and genetic algorithms, introduction to Lisp and Scheme.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Intelligence, rational agent design, state-spaces, search, heuristic functions and A*, game playing, knowledge representation, formal logic, reasoning, expert systems, machine learning paradigms including neural networks and genetic algorithms, introduction to Lisp and Scheme.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e12', 'course', 'CS 663', 'CS 663 Computer Vision (3 units), CSUEB CS department course list: Mathematical and algorithmic approaches to the problem of computing properties of the 3-D world from one or more digital images. Topics may include imaging, image processing, feature detection, calibration, stereopsis, motion, object recognition, tracking.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Mathematical and algorithmic approaches to the problem of computing properties of the 3-D world from one or more digital images. Topics may include imaging, image processing, feature detection, calibration, stereopsis, motion, object recognition, tracking.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e13', 'course', 'CS 665', 'CS 665 Human-Computer Interaction (3 units), CSUEB CS department course list: Human-centered software design, interface paradigms, prototyping, performance models, usability testing, software logging, user observation, interaction styles, aesthetics, diversity and engagement, HCI in multimedia systems, collaboration, and communication systems.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Human-centered software design, interface paradigms, prototyping, performance models, usability testing, software logging, user observation, interaction styles, aesthetics, diversity and engagement, HCI in multimedia systems, collaboration, and communication systems.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e14', 'course', 'CS 667', 'CS 667 Machine Learning (4 units), CSUEB CS department course list: Introduction to machine learning with an emphasis on the underlying mathematics. Topics such as VC dimension, central limit theorem, gradient descent. Applications such as SVM and neural nets.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Introduction to machine learning with an emphasis on the underlying mathematics. Topics such as VC dimension, central limit theorem, gradient descent. Applications such as SVM and neural nets.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e15', 'course', 'CS 681', 'CS 681 Digital Signal Processing (3 units), CSUEB CS department course list: Digital Signal Processing techniques and applications. Topics may include: Discrete Time Signals and Systems, Discrete Time Networks, Input-Output Relationships, Discrete Time Fourier Transform, Discrete Fourier Transform, IIR and FIR filter design, Power Spectrum Computation.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Digital Signal Processing techniques and applications. Topics may include: Discrete Time Signals and Systems, Discrete Time Networks, Input-Output Relationships, Discrete Time Fourier Transform, Discrete Fourier Transform, IIR and FIR filter design, Power Spectrum Computation.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e16', 'course', 'CS 683', 'CS 683 Computer Simulation (3 units), CSUEB CS department course list: Introduction to construction and analysis of models by computer simulation. Study of discrete and/or continuous simulation languages. Applications to modeling technological, biological, industrial, and physical processes. Programming projects and review of literature.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Introduction to construction and analysis of models by computer simulation. Study of discrete and/or continuous simulation languages. Applications to modeling technological, biological, industrial, and physical processes. Programming projects and review of literature.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e17', 'course', 'CS 690', 'CS 690 Independent Study (3 units), CSUEB CS department course list: Selected research topics agreed on between the student and the faculty supervising the course. A plan of work completion must be approved prior to proceeding with the project. Progress reports, and a final report are required.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Selected research topics agreed on between the student and the faculty supervising the course. A plan of work completion must be approved prior to proceeding with the project. Progress reports, and a final report are required.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('5-20261118', 'e18', 'course', 'CS 698', 'CS 698 Internship (1-3 units), CSUEB CS department course list: Advanced supervised work experience in which student completes academic assignments integrated with off-campus paid or volunteer activities.', 'https://www.csueastbay.edu/cs/courses/index.html', 'Advanced supervised work experience in which student completes academic assignments integrated with off-campus paid or volunteer activities.', '2026-11-18T12:00:00.000Z');
