INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261119', 'f101', 'requirement', 'No personal statement/SOP required for MS CS', 'ECS college graduate admissions page, which Achsah confirms governs CS-specific requirements. Achsah confirms CSUF does not require a personal statement/SOP for the MS Computer Science program. Also lists letters of recommendation, resumes, and GRE/GMAT as not required.', 'https://www.fullerton.edu/ecs/academics/graduate-admissions.html', 'Please do not submit any of the following items as they are not required for admission: Personal Statements Letter of Recommendations High School Transcripts Certificates of Accomplishments / Trainings Resumes / Work Experience GRE or GMAT Scores', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261119', 'f102', 'requirement', 'Official documents and ELP scores before document deadlines', 'ECS college graduate admissions page, which Achsah confirms governs CS-specific requirements.', 'https://www.fullerton.edu/ecs/academics/graduate-admissions.html', 'Official documents and required English Language Proficiency test scores must be submitted and processed before document deadlines.', '2026-11-08T21:51:46.613Z');
