INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261119', 'f106', 'requirement', 'University minimum GPA 2.5', 'Office of Graduate Studies, institution-wide baseline requirement that applies alongside the CS-specific list above (not in conflict; general eligibility floor, not a materials requirement).', 'https://www.fullerton.edu/graduate/apply/', 'University requirements include having a minimum GPA of 2.5 (cumulative or last 60 semester GPA units), a bachelor’s degree from an institutionally accredited college or university, and good standing with the last attended institution.', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261119', 'f107', 'requirement', '4-year degree or equivalent', 'Office of Graduate Studies, institution-wide baseline requirement that applies alongside the CS-specific list above. 3-year degrees may use a WES/IEE equivalency report.', 'https://www.fullerton.edu/graduate/apply/', 'CSUF will only accept 4-year degrees or equivalent.', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261119', 'f108', 'requirement', 'English Language Proficiency test for non-US attendees', 'Office of Graduate Studies, institution-wide baseline requirement that applies alongside the CS-specific list above. Duolingo accepted.', 'https://www.fullerton.edu/graduate/apply/', 'Students who attended a university outside of the United States and do not qualify for a waiver must take an English Language Proficiency (ELP) test', '2026-11-08T21:51:46.613Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261119', 'f109', 'requirement', 'One program per campus per semester', 'Office of Graduate Studies, institution-wide baseline requirement that applies alongside the CS-specific list above.', 'https://www.fullerton.edu/graduate/apply/', 'You can only apply to one program per campus, for a given semester.', '2026-11-08T21:51:46.613Z');
