INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261119', 'f305', 'requirement', 'Prerequisite programming course', 'Current (2026-2027) CSUF catalog page for Computer Science, M.S. (catoid=101, poid=47271) — the exact page our automated fetch is bot-blocked on; Achsah confirmed this content directly by saving the live page as a PDF from her own browser.', 'https://catalog.fullerton.edu/preview_program.php?catoid=101&poid=47271', 'Students without an undergraduate degree in computer science must have completed at least one course in computer programming with a grade of at least “B-” within the past 2 years.', '2026-11-08T21:51:46.613Z');
