INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('6-20261119', 'f358', 'requirement', 'Culminating experience requirement', 'Current (2026-2027) CSUF catalog page for Computer Science, M.S. (catoid=101, poid=47271) — the exact page our automated fetch is bot-blocked on; Achsah confirmed this content directly by saving the live page as a PDF from her own browser. Culminating Experience (6 units) section; renamed from "Required Courses" in the archived catalog (same 3 courses).', 'https://catalog.fullerton.edu/preview_program.php?catoid=101&poid=47271', 'The culminating experience marks the end of a graduate program. It demonstrates mastery of disciplinary materials and meets requirements from Section 40510 of Title 5 of the California Code of Regulations.', '2026-11-08T21:51:46.613Z');
