INSERT INTO program_snapshots (snapshot_id, school_id, verified_at) VALUES ('7-20261118', '7', '2026-11-18T20:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f1', 'overview', 'Online MSE purpose', 'The about page describes the online M.S. in Software Engineering as preparation for careers as software engineers and software project managers.', 'https://www.fullerton.edu/ecs/mse/about/', 'The Master of Science in Software Engineering (MSE) is an online program that prepares individuals for careers as software engineers and software project managers in industry and government agencies.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f2', 'overview', 'Process-oriented curriculum', 'The curriculum is described as a process-oriented approach grounded in software engineering research, theory, principles, and practice, including CMMI, ISO, agile, Scrum, XP, and architecture/design patterns.', 'https://www.fullerton.edu/ecs/mse/about/', 'The program emphasizes a comprehensive and thorough process-oriented approach to software development, and its curriculum is fundamentally grounded in software engineering research, theory, principles, and practice', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f3', 'overview', 'Designed for working professionals', 'The program is designed for professionals working in computer science who want graduate education in software engineering.', 'https://www.fullerton.edu/ecs/mse/about/', 'The program is designed for professionals working in the field of computer science who wish to further their skills and pursue graduate level education in Software Engineering.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f4', 'overview', 'Culminating practicum project', 'The culminating activity is a practicum project on a large-scale software project, not a thesis.', 'https://www.fullerton.edu/ecs/mse/about/', 'The culminating activity of the M.S. will be a practicum project where each student applies his or her knowledge and skills to a large-scale software project.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f5', 'overview', '100% online asynchronous', 'The home page states that all courses are 100% online with asynchronous delivery.', 'https://www.fullerton.edu/ecs/mse/', 'All courses 100% online', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f6', 'overview', 'No I-20 for this program', 'The FAQ says an I-20 cannot be issued because the program is offered entirely online.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'An I-20 cannot be issued for the MSE program, since it is offered entirely online. U.S. immigration policy prohibits the student visa for entirely online programs.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f7', 'overview', 'Distinct from on-campus AMSE', 'CSUF also offers an on-campus Accelerated M.S. in Software Engineering (AMSE), operated by Extension and International Programs; the online MSE is operated by the Computer Science department.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'CSUF offers two software engineering programs: the online MSE program and the on-campus Accelerated Master of Science in Software Engineering (AMSE) program.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f8', 'overview', 'Degree title has no ''Online''', 'The FAQ says the word Online will not appear on the diploma; the degree is Master of Science in Software Engineering.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'No. Although this is a fully online program, the degree itself is a "Master of Science in Software Engineering." The word "Online" will not appear on your degree.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f9', 'overview', 'Program length', 'The FAQ says the online MSE regularly takes 22 months; AMSE takes 17 months.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'Regularly MSE takes 22 months, while AMSE takes 17 months to complete.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f10', 'requirement', 'University GPA', 'Applicants need an acceptable baccalaureate degree with a minimum cumulative GPA of 2.5 for Computer Science undergraduates or 3.0 for other degree holders.', 'https://www.fullerton.edu/ecs/mse/requirements/', 'The applicant must have completed four-year college course of study and hold an acceptable baccalaureate degree with a minimum/cumulative grade point average of 2.5 for applicants having an undergraduate degree in Computer Science or 3.0 for other degree holders.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f11', 'requirement', 'Transcripts', 'An official transcript is required from each university or college attended.', 'https://www.fullerton.edu/ecs/mse/requirements/', 'An official transcript is required from each university or college you have attended.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f12', 'requirement', 'International English scores', 'International students must meet a minimum of 550 paper or 80 TOEFL, 6.5 Academic IELTS, or 58 PTE.', 'https://www.fullerton.edu/ecs/mse/requirements/', 'For international students: a minimum score of 550 (paper) or 80 in TOEFL or 6.5 Academic in IELTS or 58 in PTE.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f13', 'requirement', 'Software engineering background', 'Applicants should have taken an introductory software engineering course equivalent to CPSC 362 or have work experience in software development.', 'https://www.fullerton.edu/ecs/mse/requirements/', 'The applicant should have taken an Introductory Software Engineering course (equivalent with CPSC 362 at CSUF) or should have work experience in software development.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f14', 'requirement', 'Work-experience alternative', 'The FAQ says at least one year of software development experience is expected if the applicant has not completed CPSC 362 or an equivalent course, and a resume should be emailed to the program.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'To apply, at least one year of experience in software development is expected.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f15', 'requirement', 'GRE not required', 'The FAQ says the GRE is not required.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'No, we do not require the GRE.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f16', 'requirement', 'TOEFL/IELTS when needed', 'TOEFL/IELTS is needed if the applicant has not earned at least 72 college-level units in the U.S. or another majority English-speaking country.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'Yes, if you have not earned at least 72 college-level units in the U.S. or another majority English-speaking country. Residency/citizenship is irrelevant to this requirement.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f17', 'requirement', 'No exit exam or thesis', 'There is no exit exam; students complete a terminal project in CPSC 597, and there is no thesis option.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'No, there is no exit exam. Students are required to complete a significant terminal project as part of the curriculum (CPSC 597). There is no thesis option.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f19', 'requirement', 'No program-level scholarship', 'The FAQ says there is no scholarship at the program level and points to university financial aid.', 'https://www.fullerton.edu/ecs/mse/faq.php', 'There is no scholarship at the program level. However, you may check the university Financial Aid website for available funding opportunities.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f20', 'course', 'CPSC 541', 'CPSC 541 Systems and Software Standards and Requirements (3 units), prerequisite CPSC 362 or equivalent work experience.', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'CPSC 541 - Systems and Software Standards and Requirements (3 units)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f21', 'course', 'CPSC 542', 'CPSC 542 Software Verification and Validation (3 units).', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'CPSC 542 - Software Verification and Validation (3 units)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f22', 'course', 'CPSC 543', 'CPSC 543 Software Maintenance (3 units).', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'CPSC 543 - Software Maintenance (3 units)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f23', 'course', 'CPSC 544', 'CPSC 544 Advanced Software Process (3 units).', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'CPSC 544 - Advanced Software Process (3 units)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f24', 'course', 'CPSC 545', 'CPSC 545 Software Design and Architecture (3 units).', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'CPSC 545 - Software Design and Architecture (3 units)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f25', 'course', 'CPSC 546', 'CPSC 546 Modern Software Management (3 units).', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'CPSC 546 - Modern Software Management (3 units)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f26', 'course', 'CPSC 547', 'CPSC 547 Software Measurement (3 units).', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'CPSC 547 - Software Measurement (3 units)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f27', 'course', 'CPSC 548', 'CPSC 548 Professional, Ethical and Legal Issues for Software Engineers (3 units).', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'CPSC 548 - Professional, Ethical and Legal Issues for Software Engineers (3 units)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f28', 'course', 'CPSC 589', 'CPSC 589 Seminar in Computer Science is the online version offered to MSE students only, used to survey related work and build a project proposal.', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'The online version of CPSC 589, offered to MSE students only. Prepare for the graduate project - survey related work and build a project proposal.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f29', 'course', 'CPSC 597', 'CPSC 597 Project is the online version offered to MSE students only, used to perform the graduate project proposed in CPSC 589.', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'The on-line version of CPSC 597, offered to MSE students only. Perform a graduate project as you proposed in CPSC 589 and write a project report.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f30', 'course', 'First-year fall schedule', 'First year Fall courses are CPSC 541 and CPSC 544, totaling 6 units.', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'CPSC 541', '2026-11-19T05:32:54.490Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f31', 'course', 'Schedule by semester', 'The courses page includes a term-by-term schedule with 6 units each term through second-year Spring.', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'Schedule by Semester', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f32', 'course', 'Second-year spring', 'Second year Spring courses are CPSC 543 and CPSC 597, totaling 6 units.', 'https://www.fullerton.edu/ecs/mse/programs/courses.php', 'Second Year: Spring', '2026-11-19T05:32:54.490Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f43', 'faculty', 'Bin Cong', 'Program Coordinator and Professor of Computer Science; expertise listed includes CMMI and software architecture and engineering. This is a program faculty listing for the online MSE.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'Bin Cong, Ph.D.', '2026-11-19T05:32:54.490Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f44', 'faculty', 'Bin Cong expertise', 'His listed expertise includes SEI CMM/CMMI roles, internet and enterprise computing, and software architecture and engineering.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'SEI Authorized CMM Lead Assessor', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f45', 'faculty', 'Ning Chen', 'Professor of Computer Science; expertise includes embedded systems, software testing, and enterprise software architecture.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'Ning Chen, Ph.D.', '2026-11-19T05:32:54.490Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f46', 'faculty', 'Ning Chen expertise', 'His listed expertise includes embedded systems and wireless sensor networks, software testing and QA, and enterprise software architecture.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'Embedded Systems and Wireless Sensor Network (Linux Kernel, Contiki, TinyOS)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f47', 'faculty', 'James Choi', 'Professor of Computer Science; expertise includes software development methodology, reverse engineering, and configuration management.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'James Choi, Ph.D.', '2026-11-19T05:32:54.490Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f48', 'faculty', 'James Choi expertise', 'His listed expertise includes software development methodology, reverse engineering, and configuration management.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'Software Development Methodology', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f49', 'faculty', 'Christopher Ryu', 'Professor of Computer Science; expertise includes software design and architecture plus machine learning and AI.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'Christopher Ryu, Ph.D.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f50', 'faculty', 'Christopher Ryu expertise', 'His listed expertise includes software design and architecture, machine learning, artificial intelligence, and computational finance.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'Software Design and Architecture', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f51', 'faculty', 'Chang-Hyun Jo', 'Professor of Computer Science; expertise includes agile software process and CMMI/ISO and object-oriented and agent-oriented software engineering.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'Chang-Hyun Jo, Ph.D.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('7-20261118', 'f52', 'faculty', 'Chang-Hyun Jo expertise', 'His listed expertise includes agile software process and CMMI/ISO, process assessment, and object-oriented and agent-oriented software engineering.', 'https://www.fullerton.edu/ecs/mse/faculty/index.php', 'Agile Software Process & CMMI/ISO', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_snapshots (snapshot_id, school_id, verified_at) VALUES ('8-20261118', '8', '2026-11-18T20:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f1', 'overview', 'Program audience and curriculum focus', 'Program page: the M.S. is tailored to working professionals and is described as offering a current computing curriculum.', 'https://www.csulb.edu/hung-family-college-of-engineering/master-of-science-computer-science', 'Tailored to the schedules of working professionals, the CSULB Master of Science in Computer Science program offers the most relevant and up-to-date curriculum to meet the demands of the rapidly changing world of computing.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f2', 'overview', 'Advanced study areas', 'Program page: the M.S. provides advanced study in software development and engineering, networking, operating systems, distributed computing, AI, and algorithm analysis.', 'https://www.csulb.edu/hung-family-college-of-engineering/master-of-science-computer-science', 'The M.S. in Computer Science provides advanced study in software development and engineering, networking, operating systems, distributed computing, artificial intelligence, and analysis of algorithms.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f3', 'overview', 'Concentrations', 'Students can pursue concentrations in Advanced Systems or Software Development.', 'https://www.csulb.edu/hung-family-college-of-engineering/master-of-science-computer-science', 'Students can pursue concentrations in Advanced Systems or Software Development.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f4', 'requirement', 'Culminating experience', 'Students finish with a comprehensive exam or a thesis research project.', 'https://www.csulb.edu/hung-family-college-of-engineering/master-of-science-computer-science', 'Complete your graduate degree with a comprehensive exam or thesis research project.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f5', 'requirement', 'Bachelor''s degree and GPA', 'MSCS admissions: bachelor''s in computer engineering or computer science, or sufficient background, with a minimum 2.7 GPA in the last 60 semester or 90 quarter upper-division major units.', 'https://www.csulb.edu/hung-family-college-of-engineering/mscs-admissions', 'Hold a bachelor''s degree in computer engineering or computer science or have sufficient background in computer engineering or computer science from a college or university with a minimum grade point average (GPA) of 2.7 in the last 60 semester or 90 quarter upper-division major units attempted.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f6', 'requirement', 'University graduate admission requirements', 'The MSCS admissions page also requires applicants to satisfy university requirements for graduate admission.', 'https://www.csulb.edu/hung-family-college-of-engineering/mscs-admissions', 'Satisfy university requirements for graduate admission', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f7', 'requirement', 'University minimum GPA options (university-wide)', 'University-wide graduate standing page: a baccalaureate with a cumulative GPA of at least 2.5, with no rounding. This is a university rule, not an MSCS-only rule.', 'https://www.csulb.edu/admissions/graduate-programs-admission-eligibility', 'Hold a baccalaureate degree with a cumulative GPA of at least 2.5. (No Rounding)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f8', 'deadline', 'University master''s application latest dates (not MSCS-specific)', 'University Key Dates page: master''s program deadlines vary by program. This is a university-wide latest-date rule, not an MSCS-only deadline.', 'https://www.csulb.edu/enrollment-services/key-dates-and-deadlines', 'Master’s programs and certificates application deadline', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f9', 'deadline', 'Spring 2027 master''s latest date (university-wide)', 'University-wide latest date for master''s applications for Spring 2027 admission: no later than Nov. 1, 2026; the page says dates vary by program.', 'https://www.csulb.edu/enrollment-services/key-dates-and-deadlines', 'Varies by program (no later than Nov. 1, 2026)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f10', 'deadline', 'Fall 2027 master''s latest date (university-wide)', 'University-wide latest date for master''s applications for Fall 2027 admission: no later than June 1, 2027; the page says dates vary by program.', 'https://www.csulb.edu/enrollment-services/key-dates-and-deadlines', 'Varies by program (no later than June 1, 2027)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f11', 'overview', 'Department faculty research areas (department-wide)', 'CECS department page (not MSCS-specific): faculty research areas include data science, AI, cybersecurity, software engineering, IoT, and embedded systems.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science', 'Our faculty are actively involved in advanced research across areas such as data science (with various applications including health), artificial intelligence, cybersecurity, software engineering, internet of things, embedded systems, and more.', '2026-11-14T07:29:27.152108Z');
