INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f23', 'faculty', 'Dr. Tracy Bradley Maples', 'Named on the Computer Engineering & Computer Science faculty listing (department-wide, not MSCS-specific). The listing card does not state a research blurb.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/faculty-staff?page=1', 'Dr. Tracy Bradley Maples', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f24', 'faculty', 'Ju Cheol Moon', 'CSULB profile: The focus of his research lies in designing interpretable machine learning algorithms, building highly accurate deep neural networks on prediction, and in applying computational frameworks to solve interdisciplinary problems.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-ju-cheol-moon', 'The focus of his research lies in designing interpretable machine learning algorithms, building highly accurate deep neural networks on prediction, and in applying computational frameworks to solve interdisciplinary problems.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f25', 'faculty', 'Dr. Frank Murgolo', 'Named on the Computer Engineering & Computer Science faculty listing (department-wide, not MSCS-specific). The listing card does not state a research blurb.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/faculty-staff?page=1', 'Dr. Frank Murgolo', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f26', 'faculty', 'Oscar Morales Ponce', 'CSULB profile: His research interests include theoretical and practical aspects of distributed computing, wireless sensor networks, distributed control of robotic networks, computational geometry, graph theory, vehicular networks and intelligent transportation systems.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-oscar-morales-ponce', 'His research interests include theoretical and practical aspects of distributed computing, wireless sensor networks, distributed control of robotic networks, computational geometry, graph theory, vehicular networks and intelligent transportation systems.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f27', 'faculty', 'Xin Qin', 'CSULB college page: Dr. Xin Qin''s research interests are in ensuring the safety of cyber-physical systems through formal methods, predictive monitoring, verification, and machine learning.', 'https://www.csulb.edu/hung-family-college-of-engineering/article/new-faculty-2024', 'Dr. Xin Qin''s research interests are in ensuring the safety of cyber-physical systems through formal methods, predictive monitoring, verification, and machine learning.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f28', 'faculty', 'Muhammad Abdul Basit Ur Rahim', 'CSULB profile: Dr. Basit''s research focuses on formal modeling and analysis of industrial systems. His multidisciplinary research applies to industrial and cybersecurity systems to verify the design in earlier design phases.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-muhammad-abdul-basit-ur-rahim', 'Dr. Basit''s research focuses on formal modeling and analysis of industrial systems. His multidisciplinary research applies to industrial and cybersecurity systems to verify the design in earlier design phases.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f29', 'faculty', 'Arash Sarshar', 'CSULB profile: His research interests span the theory and applications of machine learning and numerical methods for scientific simulations. He is also interested in using data science to inform public health and policy decisions.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-arash-sarshar', 'His research interests span the theory and applications of machine learning and numerical methods for scientific simulations. He is also interested in using data science to inform public health and policy decisions.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f30', 'faculty', 'Dr. Hossein Sayadi', 'Named on the Computer Engineering & Computer Science faculty listing (department-wide, not MSCS-specific). The listing card does not state a research blurb.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/faculty-staff?page=1', 'Dr. Hossein Sayadi', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f31', 'faculty', 'Dr. Shabnam Sodagari', 'Named on the Computer Engineering & Computer Science faculty listing (department-wide, not MSCS-specific). The listing card does not state a research blurb.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/faculty-staff?page=2', 'Dr. Shabnam Sodagari', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f32', 'faculty', 'Dr. Jelena Trajkovic', 'Named on the Computer Engineering & Computer Science faculty listing (department-wide, not MSCS-specific). The listing card does not state a research blurb.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/faculty-staff?page=2', 'Dr. Jelena Trajkovic', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f33', 'faculty', 'Wei Wei', 'Named on the Computer Engineering & Computer Science faculty listing (department-wide, not MSCS-specific). The listing card does not state a research blurb.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/faculty-staff?page=2', 'Wei Wei', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f34', 'faculty', 'Xiaolong Wu', 'CSULB profile: Dr. Wu''s research interests include network on chip/system on chip design, IC design, interconnection network, and reliability modeling.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-xiaolong-wu', 'Dr. Wu''s research interests include network on chip/system on chip design, IC design, interconnection network, and reliability modeling.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f35', 'faculty', 'Hailu Xu', 'CSULB profile: His research interests include AI/ML systems, human-robot collaboration, distributed computing, federated learning, cloud and edge computing, and big data systems.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-hailu-xu', 'His research interests include AI/ML systems, human-robot collaboration, distributed computing, federated learning, cloud and edge computing, and big data systems.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f36', 'faculty', 'Yutong Zhao', 'CSULB profile: Dr. Zhao''s research interests span Software Engineering, Performance Analysis, Machine and Deep Learning, and Natural Language Processing.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-yutong-zhao', 'Dr. Zhao''s research interests span Software Engineering, Performance Analysis, Machine and Deep Learning, and Natural Language Processing.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f37', 'faculty', 'Shadnaz Asgari', 'CECS chair; profile states research integrating AI, signal processing, and computational modeling in clinical and biomedical contexts.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-shadnaz-asgari', 'Dr. Asgari’s research integrates artificial intelligence, signal processing, and computational modeling to solve problems in clinical and biomedical contexts.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f38', 'faculty', 'Todd Ebert', 'Profile: research interests in constraint programming.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-todd-ebert', 'research interests lie in constraint programming, including high-level languages for stating constraint problems, and robust algorithms for solving them.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f39', 'faculty', 'Bo Fu', 'Profile: research intersects Web Semantics, Human Data Interaction, and Visual Analytics.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-bo-fu', 'Dr. Fu’s research intersects Web Semantics, Human Data Interaction, and Visual Analytics.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f40', 'faculty', 'Amir Ghasemkhani', 'Profile: research interests in AI privacy and security for cyber-physical system applications.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-amir-ghasemkhani', 'research interests revolve around AI privacy and security for cyber physical system (CPS) applications.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f41', 'faculty', 'Darin Goldstein', 'Profile: interests include algorithms and data structures, games, distributed computation, and computational complexity.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-darin-goldstein', 'Dr. Goldstein''s interests include algorithms and data structures, games, distributed computation, computational complexity', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f42', 'faculty', 'Min He', 'Profile: research interests include embedded systems, hardware/software codesign, software engineering for embedded systems, parallel algorithms, and optical interconnection networks.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-min-he', 'research interests include embedded systems, hardware/software codesign for embedded systems, software engineering for embedded systems, parallel algorithms and models, and optical interconnection networks.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f43', 'faculty', 'Tracy Bradley Maples', 'Profile: research interests in computer networking and modeling and simulation.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-tracy-bradley-maples', 'research interests lie in the areas of computer networking, modeling and simulation.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f44', 'faculty', 'Jelena Trajkovic', 'Profile: research interests include multicore embedded systems, pervasive computing, and IoT for critical biomedical and control applications.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-jelena-trajkovic', 'research interests include multicore embedded systems, pervasive computing, and Internet of Things technologies for critical biomedical and control applications.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f45', 'faculty', 'Hossein Sayadi', 'Profile: research interests span hardware security, AI and machine learning, cybersecurity, computer architecture, cyber-physical systems, and CS education.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-hossein-sayadi', 'His research interests span hardware security, AI and machine learning, cybersecurity, computer architecture, cyber-physical systems, and computer science education.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f46', 'faculty', 'Shabnam Sodagari', 'personal faculty website (not csulb.edu): Her current research interests include quantum computing, applications of data science, AI, and machine learning in various domains, such as health, education, etc.', 'https://shabnamso.github.io/webpage/', 'Her current research interests include quantum computing, applications of data science, AI, and machine learning in various domains, such as health, education, etc.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f47', 'faculty', 'Daniel Commey', 'personal faculty website (not csulb.edu): My research examines the security and privacy of federated, decentralized, and edge AI, particularly when devices or participants cannot be fully trusted.', 'https://danielcommey.com/research', 'My research examines the security and privacy of federated, decentralized, and edge AI, particularly when devices or participants cannot be fully trusted.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f48', 'faculty', 'Michael Hoffman', '', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-michael-hoffman', 'Dr. Michael Hoffman', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f49', 'faculty', 'Amin Rezaei', 'Profile lists research interests in hardware security, machine learning, and computer architecture.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-amin-rezaei', 'Hardware Security', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f50', 'faculty', 'Wenlu Zhang', 'CSULB college page: Her research interests include machine learning, data mining, computational biology, and computational neuroscience.', 'https://www.csulb.edu/hung-family-college-of-engineering/computing', 'Her research interests include machine learning, data mining, computational biology, and computational neuroscience.', '2026-11-18T12:00:00.000Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f51', 'faculty', 'Forouzan Golshani', 'Profile emphasizes career honors; it does not state a compact current research-area sentence.', 'https://www.csulb.edu/college-of-engineering/computer-engineering-computer-science/page/dr-forouzan-golshani', 'Forouzan Golshani is a Fellow of the National Academy of Inventors, a Life Time Fellow of IEEE and a Fellow of AAIA.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f52', 'overview', 'Catalog heading', 'The 2026-2027 University Catalog program heading is Computer Science, M.S.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'Computer Science, M.S.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f53', 'overview', 'Program mission', 'The catalog describes a graduate program meant to prepare leaders in industry and also students who later pursue advanced degrees, with advanced courses in software and hardware analysis and design.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'The mission of the graduate program in Computer Science at CSULB is to provide a high-quality educational experience and the technical specialization required to become successful leaders in industry.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f54', 'requirement', 'Thesis or comprehensive examination', 'Students may finish with a thesis or a comprehensive examination.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'The students may choose to do a thesis or take a comprehensive examination as the culmination of their program.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f55', 'requirement', 'Admission degree background', 'Applicants need a bachelor''s degree in computer engineering or computer science, or sufficient background in those fields, from a college or university.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'To be considered for admission the graduate applicant must have earned a bachelor''s degree in computer engineering, computer science or sufficient background in computer engineering or computer science from a college or university', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f56', 'requirement', 'Admission GPA of 2.7 in last 60 semester units', 'The minimum GPA is 2.7 in the last 60 semester or 90 quarter upper-division major units attempted.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'a minimum grade point average (GPA) of 2.7 in the last 60 semester or 90 quarter upper division major units attempted.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f57', 'requirement', 'Apply through Cal State Apply, not the department', 'Applications go through Cal State Apply; the page says not to send an application to the department. International students also apply at Cal State Apply.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'The student should apply online at www.calstate.edu/apply . Do not send an application to the Department.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f58', 'requirement', 'Remove deficiencies before graduate-level courses', 'All deficiencies must be removed before a student attempts graduate-level courses.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'All deficiencies must be removed before attempting graduate-level courses.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f59', 'requirement', 'Advancement to candidacy: deficiencies and overall GPA', 'Students applying for advancement to candidacy must have completed all undergraduate deficiencies with grades of C or better and have an overall GPA of 3.0.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'Students applying for advancement to candidacy must: have completed all undergraduate deficiencies with grades of "C" or better; have attained an overall grade point average (GPA) of 3.0;', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f60', 'requirement', 'Advancement to candidacy: 9 units and advisor approval', 'They must also complete at least 9 units of required degree-applicable courses with a 3.0 GPA in those units, and have a plan of study approved by the CECS department graduate advisor.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'have completed at least 9 units of required courses applicable to the degree with a GPA of at least 3.0 for the completed units; and have their plans of studies approved by the CECS department graduate advisor.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f61', 'requirement', 'Degree unit total', 'The degree requires 30 units.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'Degree Requirements (30 units)', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f62', 'requirement', 'First-semester plan of study', 'Students must meet the Graduate Program Adviser at the start of the first semester to make a tentative plan of study. The page also says a detailed required-and-elective list is kept on the Graduate Program website.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'Students must meet with the Graduate Program Adviser at the beginning of their first semester to create a tentative plan of study.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f63', 'requirement', 'Culminating options and 400-level cap', 'Students must choose the Thesis Option or the Comprehensive Exam Option. At most 9 units of 400-level coursework may count toward the degree.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'As a culminating activity, students must elect either the Thesis Option or the Comprehensive Exam Option. A maximum of 9 units of 400-level coursework may be applied toward the degree.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f64', 'requirement', 'Comprehensive exam option unit split', 'The exam option requires 30 graduate hours in computer science, a passing comprehensive exam, 15 units of required core courses, and 15 units of allowed electives, with no more than 9 units from 400-level courses.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'Student must complete 30 graduate hours credit in computer science and pass the comprehensive exam. 15 units of required core courses', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f65', 'requirement', 'Exam-option elective units', 'Under the comprehensive exam option, students take 15 units from the allowed electives, with no more than 9 units from 400-level courses.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', '15 units from allowed electives (No more than 9 units may be from the 400 level courses.)', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f66', 'requirement', 'Comprehensive exam covered courses', 'The comprehensive exam covers CECS 524, CECS 528, and CECS 543. The page does not list CECS 530 or CECS 558 among the covered courses, even though those two are in the required core.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'Comprehensive examination covering the following required courses: CECS 524 - Advanced Topics in Programming Languages (3 units) CECS 528 - Advanced Analysis of Algorithms (3 units) CECS 543 - Advanced Software Engineering (3 units)', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f67', 'requirement', 'Thesis option unit split', 'The thesis option requires 15 units of required courses, 9 units of allowed electives (no more than 9 units from 400-level courses), and 6 units of research and thesis.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', '15 units of required courses', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f68', 'requirement', 'Thesis-option elective units', 'Under the thesis option, students take 9 units from allowed electives, with no more than 9 units from 400-level courses.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', '9 units from allowed electives (No more than 9 units may be from the 400 level courses.);', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f69', 'requirement', 'Thesis research and report', 'The thesis option includes 6 units of research and thesis with a written report and oral presentation approved by the thesis committee. At least 3 of those units must be CECS 698; the remaining 3 units may be CECS 697 or CECS 698.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', '6 units of research and thesis with written report and oral presentation approved by the thesis committee.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f70', 'requirement', 'Thesis minimum from CECS 698', 'At least 3 of the 6 thesis-option research units must be taken from CECS 698 Thesis or Industrial Project.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'At least 3 units must be taken from the following course CECS 698 - Thesis or Industrial Project (3-6 units)', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f71', 'requirement', 'Thesis remaining 3 units', 'The remaining 3 thesis research units may be CECS 697 Directed Research or CECS 698 Thesis or Industrial Project.', 'https://catalog.csulb.edu/preview_program.php?catoid=12&poid=6290', 'Remaining 3 units may be taken from either of the following courses CECS 697 - Directed Research (1-3 units) CECS 698 - Thesis or Industrial Project (3-6 units)', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f72', 'course', 'CECS 524', 'CECS 524 Advanced Topics in Programming Languages, CSULB 2026-27 catalog: Intensive study of languages of current interest which support object-oriented, client-server, and multimedia applications (e.g. JAVA). Master''s students register in CECS 524 or CECS 624 ; Ph.D. students register in CECS 624 .', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109084', 'Intensive study of languages of current interest which support object-oriented, client-server, and multimedia applications (e.g. JAVA). Master''s students register in CECS 524 or CECS 624 ; Ph.D. students register in CECS 624 .', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f73', 'course', 'CECS 528', 'CECS 528 Advanced Analysis of Algorithms, CSULB 2026-27 catalog: Theoretical analysis of algorithms. Divide and conquer, dynamic programming and greedy algorithms; basic search and traversal techniques including search trees; sorting; matrix manipulations; NP-completeness. Master''s students register in CECS 528 or CECS 628 ; Ph.D. students register in CECS 628 .', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109086', 'Theoretical analysis of algorithms. Divide and conquer, dynamic programming and greedy algorithms; basic search and traversal techniques including search trees; sorting; matrix manipulations; NP-completeness. Master''s students register in CECS 528 or CECS 628 ; Ph.D. students register in CECS 628 .', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f74', 'course', 'CECS 530', 'CECS 530 Advanced Computer Architecture I, CSULB 2026-27 catalog: Fundamentals of computer architecture. Parallelism, Instruction Level Parallelism, Pipelining. Hazards and their management, Branch Prediction, Dynamic Scheduling, Multiple Instructions, Multithreading, Data Level Parallelism, SIMD, Graphic Processing Units, Memory Hierarchy, Cache, Virtual Memory', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109088', 'Fundamentals of computer architecture. Parallelism, Instruction Level Parallelism, Pipelining. Hazards and their management, Branch Prediction, Dynamic Scheduling, Multiple Instructions, Multithreading, Data Level Parallelism, SIMD, Graphic Processing Units, Memory Hierarchy, Cache, Virtual Memory', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f75', 'course', 'CECS 543', 'CECS 543 Advanced Software Engineering, CSULB 2026-27 catalog: Study of software engineering as a broad, problem-solving discipline. Includes structured programming and software project management. Master''s students register in CECS 543 or CECS 643 ; Ph.D. students register in CECS 643 . Additional projects required for CECS 643 .', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109092', 'Study of software engineering as a broad, problem-solving discipline. Includes structured programming and software project management. Master''s students register in CECS 543 or CECS 643 ; Ph.D. students register in CECS 643 . Additional projects required for CECS 643 .', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f76', 'course', 'CECS 558', 'CECS 558 Deep Learning, CSULB 2026-27 catalog: Foundational and advanced deep learning concepts. Introduction to neural networks, backpropagation, specialized neural network architectures, deep reinforcement learning, and large language models. Programming assignments to reinforce understanding.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=124439', 'Foundational and advanced deep learning concepts. Introduction to neural networks, backpropagation, specialized neural network architectures, deep reinforcement learning, and large language models. Programming assignments to reinforce understanding.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f77', 'course', 'CECS 698', 'CECS 698 Thesis or Industrial Project, CSULB 2026-27 catalog: Computer Engineering MS, Computer Science MS, and Engineering MS students only. Planning, preparation, completion of thesis or equivalent industrial project report on a suitable topic in computer engineering and computer science following the library''s prescribed format.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109130', 'Computer Engineering MS, Computer Science MS, and Engineering MS students only. Planning, preparation, completion of thesis or equivalent industrial project report on a suitable topic in computer engineering and computer science following the library''s prescribed format.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f78', 'course', 'CECS 697', 'CECS 697 Directed Research, CSULB 2026-27 catalog: Theoretical and experimental problems in computer science and engineering requiring extensive research. Advancement to candidacy and program GPA of at least 3.0 are required. Graduate advisor and project supervisor must be consulted prior to registration. Independent Study.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109129', 'Theoretical and experimental problems in computer science and engineering requiring extensive research. Advancement to candidacy and program GPA of at least 3.0 are required. Graduate advisor and project supervisor must be consulted prior to registration. Independent Study.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f79', 'course', 'CECS 519', 'CECS 519 Theory of Computation, CSULB 2026-27 catalog: Advanced topics in computability theory and computational complexity theory. Topics include Turing Machines, coverage of the standard complexity classes P, NP, IP, and PSPACE, hierarchy, decidability, and recognizability theorems. Additional projects required for CECS 519.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109082', 'Advanced topics in computability theory and computational complexity theory. Topics include Turing Machines, coverage of the standard complexity classes P, NP, IP, and PSPACE, hierarchy, decidability, and recognizability theorems. Additional projects required for CECS 519.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f80', 'course', 'CECS 521', 'CECS 521 Database Architecture, CSULB 2026-27 catalog: Relational database design theory-a rigorous approach. Security, recovery, transaction management, distributed databases and query optimization. Master''s students register in CECS 521 or CECS 621 ; Ph.D. students register in CECS 621 . Additional projects required for CECS 621 .', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109083', 'Relational database design theory-a rigorous approach. Security, recovery, transaction management, distributed databases and query optimization. Master''s students register in CECS 521 or CECS 621 ; Ph.D. students register in CECS 621 . Additional projects required for CECS 621 .', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f81', 'course', 'CECS 526', 'CECS 526 Advanced Operating Systems, CSULB 2026-27 catalog: Theoretical foundations of concepts applied in the design of operating systems. Control of concurrent processes, deadlocks, mutual exclusion, virtual memory, resource management and scheduling. Master''s students register in CECS 526 or CECS 626 ; Ph.D. students register in CECS 626 .', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109085', 'Theoretical foundations of concepts applied in the design of operating systems. Control of concurrent processes, deadlocks, mutual exclusion, virtual memory, resource management and scheduling. Master''s students register in CECS 526 or CECS 626 ; Ph.D. students register in CECS 626 .', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f82', 'course', 'CECS 529', 'CECS 529 Search Engine Technology, CSULB 2026-27 catalog: Models, algorithms, and evaluation of the retrieval of information from a collection of documents. Document preprocessing. Indexing and searching. Retrieval evaluation. Search engines. Additional projects required for CECS 529.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109087', 'Models, algorithms, and evaluation of the retrieval of information from a collection of documents. Document preprocessing. Indexing and searching. Retrieval evaluation. Search engines. Additional projects required for CECS 529.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f83', 'course', 'CECS 532', 'CECS 532 Memory Design and Implementation, CSULB 2026-27 catalog: Logic design and operation, physical design and operation, performance characteristics, design trade-offs, energy consumption of modern memory hierarchies, memory errors and error correction.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109090', 'Logic design and operation, physical design and operation, performance characteristics, design trade-offs, energy consumption of modern memory hierarchies, memory errors and error correction.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f84', 'course', 'CECS 544', 'CECS 544 Software Testing and Verification, CSULB 2026-27 catalog: Testing/verification techniques for software development including black box, white box, incremental, top-down and bottom-up, static and dynamic, performance, regression, thread, and stress testing. Object-oriented software testing with a hierarchical approach.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109093', 'Testing/verification techniques for software development including black box, white box, incremental, top-down and bottom-up, static and dynamic, performance, regression, thread, and stress testing. Object-oriented software testing with a hierarchical approach.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f85', 'course', 'CECS 545', 'CECS 545 Software Architecture, CSULB 2026-27 catalog: Includes architectural styles, pipes and filters, data abstraction and object-oriented organization, event-based, implicit invocation, layered systems, repositories, interpreters, process control, distributed processes, domain-specific software & heterogeneous architectures.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109094', 'Includes architectural styles, pipes and filters, data abstraction and object-oriented organization, event-based, implicit invocation, layered systems, repositories, interpreters, process control, distributed processes, domain-specific software & heterogeneous architectures.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f86', 'course', 'CECS 546', 'CECS 546 Fault Tolerant Computing Systems, CSULB 2026-27 catalog: Fault tolerant techniques are studied as tools to assure the reliability and continuous availability of computing systems. Case studies of modern fault tolerant systems reviewed.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109095', 'Fault tolerant techniques are studied as tools to assure the reliability and continuous availability of computing systems. Case studies of modern fault tolerant systems reviewed.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f87', 'course', 'CECS 547', 'CECS 547 Software Maintenance, Reengineering and Reuse, CSULB 2026-27 catalog: Introduction to software maintenance, defect management, corrective, adaptive and perfective maintenance. Evolution of legacy software systems. Program comprehension techniques, reverse engineering, restructuring, refactoring of software systems. Software re-engineering, data reverse engineering.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109096', 'Introduction to software maintenance, defect management, corrective, adaptive and perfective maintenance. Evolution of legacy software systems. Program comprehension techniques, reverse engineering, restructuring, refactoring of software systems. Software re-engineering, data reverse engineering.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f88', 'course', 'CECS 550', 'CECS 550 Pattern Recognition, CSULB 2026-27 catalog: General concepts of pattern recognition and trainable classifiers, decision theory, supervised learning, non-parametric techniques, rule-based systems and neural networks. Master''s students register in CECS 550; Ph.D. students register in CECS 650 . Additional projects required for CECS 650 .', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109097', 'General concepts of pattern recognition and trainable classifiers, decision theory, supervised learning, non-parametric techniques, rule-based systems and neural networks. Master''s students register in CECS 550; Ph.D. students register in CECS 650 . Additional projects required for CECS 650 .', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f89', 'course', 'CECS 551', 'CECS 551 Advanced Artificial Intelligence, CSULB 2026-27 catalog: Advanced concepts in artificial intelligence. Topics include knowledge acquisition and representation, fuzzy logic, logical reasoning, multi-sensor integration, Dempster-Shafer''s theory of evidential reasoning, real-time expert systems and neural networks.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109098', 'Advanced concepts in artificial intelligence. Topics include knowledge acquisition and representation, fuzzy logic, logical reasoning, multi-sensor integration, Dempster-Shafer''s theory of evidential reasoning, real-time expert systems and neural networks.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f90', 'course', 'CECS 552', 'CECS 552 Computer Simulation and Modeling, CSULB 2026-27 catalog: Studies of general purpose and special simulation software. Model verification including graphical models Applications in various areas. Master''s students register in CECS 552', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109099', 'Studies of general purpose and special simulation software. Model verification including graphical models Applications in various areas. Master''s students register in CECS 552', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f91', 'course', 'CECS 553', 'CECS 553 Machine Vision, CSULB 2026-27 catalog: Discussion and laboratory implementation of current research in vision and image understanding. Topics include image formation, early processing, segmentation, relational structures in 2-D and 3-D, motion, stereo, 3-D reconstruction, morphological methods and computer architecture for machine', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109100', 'Discussion and laboratory implementation of current research in vision and image understanding. Topics include image formation, early processing, segmentation, relational structures in 2-D and 3-D, motion, stereo, 3-D reconstruction, morphological methods and computer architecture for machine', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f92', 'course', 'CECS 561', 'CECS 561 Hardware/Software Co-design, CSULB 2026-27 catalog: Introduction to top-down methods for hardware/software system-on- chip co-design. Design flow - system specification, software implementation, hardware synthesis, system design, and verification. Process optimization with various design decisions emphasized.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109101', 'Introduction to top-down methods for hardware/software system-on- chip co-design. Design flow - system specification, software implementation, hardware synthesis, system design, and verification. Process optimization with various design decisions emphasized.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f93', 'course', 'CECS 570', 'CECS 570 Concurrent Parallel Programming, CSULB 2026-27 catalog: Introduction to concurrent and parallel programming for multiprocessing and distributed systems. Computational models and paradigms. Parallel programming languages and programming tools. Portable parallel programming and mapping techniques. Heterogeneous concurrent programming.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109102', 'Introduction to concurrent and parallel programming for multiprocessing and distributed systems. Computational models and paradigms. Parallel programming languages and programming tools. Portable parallel programming and mapping techniques. Heterogeneous concurrent programming.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f94', 'course', 'CECS 571', 'CECS 571 Fundamentals of Semantic Web technologies, CSULB 2026-27 catalog: Introduction to key Semantic Web technologies that extend the current Web. Semantic-driven applications, structured data, ontologies, knowledge modeling and engineering, linked data, logic and inference, XML, XML Schema, RDF, RDFS, OWL (Full, DL, Lite).', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109103', 'Introduction to key Semantic Web technologies that extend the current Web. Semantic-driven applications, structured data, ontologies, knowledge modeling and engineering, linked data, logic and inference, XML, XML Schema, RDF, RDFS, OWL (Full, DL, Lite).', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f95', 'course', 'CECS 572', 'CECS 572 Advanced Computer Networking, CSULB 2026-27 catalog: Advanced concepts in computer network theory and practice. Computer network design and standards for local area networks (LANs) and wide area networks (WANs). Computer network configuration and performance issues. Master''s students register in CECS 572 or CECS 672 ; Ph.D.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109104', 'Advanced concepts in computer network theory and practice. Computer network design and standards for local area networks (LANs) and wide area networks (WANs). Computer network configuration and performance issues. Master''s students register in CECS 572 or CECS 672 ; Ph.D.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f96', 'course', 'CECS 574', 'CECS 574 Distributed Computing, CSULB 2026-27 catalog: Master''s students register in CECS 574; Ph.D. students register in CECS 674 . Additional projects required for CECS 674 .', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109105', 'Master''s students register in CECS 574; Ph.D. students register in CECS 674 . Additional projects required for CECS 674 .', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f97', 'course', 'CECS 575', 'CECS 575 Object-Oriented Analysis and Design, CSULB 2026-27 catalog: An object-oriented approach to software development based on modeling objects from the real world. Object-oriented methodology from problem statement through analysis, system design, and object design. Implementation of object-oriented designs in various target environments. Case studies.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109106', 'An object-oriented approach to software development based on modeling objects from the real world. Object-oriented methodology from problem statement through analysis, system design, and object design. Implementation of object-oriented designs in various target environments. Case studies.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f98', 'course', 'CECS 577', 'CECS 577 Blockchain Technology, CSULB 2026-27 catalog: Overview of fundamentals, a survey of contributing fields and some simple hands-on activities toward understanding the fundamentals of blockchain technology, its transactions and protocols, and its applications. Projects assigned.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=114298', 'Overview of fundamentals, a survey of contributing fields and some simple hands-on activities toward understanding the fundamentals of blockchain technology, its transactions and protocols, and its applications. Projects assigned.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f99', 'course', 'CECS 579', 'CECS 579 Information Security, CSULB 2026-27 catalog: Symmetric cryptosystems, stream ciphers, pseudorandom functions, message authentication codes (MACs), collision resistant hash functions, number theory and cryptographic hardness assumptions, public-key encryption (El- Gamaland RSA), digital signature schemes.', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109107', 'Symmetric cryptosystems, stream ciphers, pseudorandom functions, message authentication codes (MACs), collision resistant hash functions, number theory and cryptographic hardness assumptions, public-key encryption (El- Gamaland RSA), digital signature schemes.', '2026-11-19T05:33:11.761Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('8-20261118', 'f100', 'course', 'CECS 590', 'CECS 590 Selected Topics in Computer Science, CSULB 2026-27 catalog: Each offering is based on an area in computer science and technology in which recent advances have been made. Additional projects required for CECS 690 .', 'https://catalog.csulb.edu/preview_course_nopop.php?catoid=12&coid=109108', 'Each offering is based on an area in computer science and technology in which recent advances have been made. Additional projects required for CECS 690 .', '2026-11-19T05:33:11.761Z');
