INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f1', 'overview', 'Program description', 'Department graduate page: the master''s program offers a comprehensive education in Computer Science and prepares students to enter the technology industry.', 'https://www.calstatela.edu/ecst/cs/graduate', 'Our Master''s Program at Cal State LA offers a comprehensive education in the rapidly changing and emerging field of Computer Science and prepares students to enter the competitive technology industry.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f5', 'requirement', 'GRE and letters not required', 'Graduate page: GRE and recommendation letters are not required.', 'https://www.calstatela.edu/ecst/cs/graduate', 'GRE and Recommendation letters are NOT required', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f6', 'requirement', 'Conditional admission GPA range', 'Graduate page: promising applicants with a GPA between 2.5 and 2.99 may be conditionally admitted.', 'https://www.calstatela.edu/ecst/cs/graduate', 'Promising applicants with a GPA between 2.5 and 2.99 may be conditionally admitted and are encouraged to apply', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f8', 'requirement', 'Special action / conditional GPA 2.5-2.99', 'Admission page: a promising applicant with GPA 2.5-2.99 may be conditionally admitted as a special action student and must earn a 3.0 in four department-approved qualifying courses.', 'https://www.calstatela.edu/ecst/cs/admission-prerequisites', 'A promising applicant with a GPA between 2.5 and 2.99 may be conditionally admitted as a special action student.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f9', 'requirement', 'Prerequisite cap for non-CS or non-ABET applicants', 'Admission page: promising non-CS or non-ABET CS applicants may be given up to three prerequisites.', 'https://www.calstatela.edu/ecst/cs/admission-prerequisites', 'These students are given up to three prerequisites (based on the evaluation of their transcripts).', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f10', 'requirement', 'Application is two steps', 'Admission page: the application process is centralized and requires two steps.', 'https://www.calstatela.edu/ecst/cs/admission-prerequisites', 'The application process is centralized at the university and requires TWO steps as described below:', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f12', 'requirement', 'Advance to candidacy', 'Planner: students ready for a thesis or the comprehensive exam should advance after at least 12 units and a 3.0 GPA.', 'https://www.calstatela.edu/ecst/cs/planner', 'The minimum requirement for candidacy advancement are the completion of 12 units and a minimum GPA of 3.0.', '2026-11-14T07:29:27.152108Z');
