INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f37', 'faculty', 'Navid Amini', 'Profile research interests include glaucoma-related work and mHealth app development.', 'https://www.calstatela.edu/faculty/navid-amini', 'Research Interests: Glaucoma and Quality of Life, Structure-Function Relationships in Glaucoma, mHealth App Development', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f38', 'faculty', 'Huiping Guo', 'Profile research interests: database and network security, privacy and digital rights protection, blockchains and IoT security.', 'https://www.calstatela.edu/faculty/huiping-guo', 'Research Interests: Database security and network security Privacy and digital rights protection Blockchains and IoT security', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f39', 'faculty', 'Jiang Guo', 'Profile research areas: machine learning, AI, data science, software engineering.', 'https://www.calstatela.edu/faculty/jiang-guo', 'RESEARCH AREAS Machine Learning Artificial Intelligence Data Science Software Engineering', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f40', 'faculty', 'Eun-Young (Elaine) Kang', 'Profile: research interests in computer vision, computer graphics, AR/MR, and game programming.', 'https://www.calstatela.edu/faculty/elaine-kang', 'research interests are in Computer Vision, Computer Graphics, Augmented/Mixed Reality, and Game Programming.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f41', 'faculty', 'Manveen Kaur', 'Profile lists research areas including CPS, IoT, and named data networking.', 'https://www.calstatela.edu/faculty/manveen-kaur', 'Research areas of interest: Cyber-physical systems (CPS), Internet-of-Things (IoT), Named Data Networking (NDN)', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f42', 'faculty', 'David Krum', 'Profile: research interests include HCI, 3D interaction, and virtual/augmented reality.', 'https://www.calstatela.edu/faculty/david-krum', 'research interests include human-computer interaction, 3D interaction, and virtual/augmented reality.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f43', 'faculty', 'Jungsoo Lim', 'Profile: research interests in IoT, cyber-physical systems, wireless networking, wireless sensor networking, and software engineering.', 'https://www.calstatela.edu/faculty/jung-lim', 'research interests are the Internet of Things, Cyber-Physical systems, wireless networking, wireless sensor networking, and software engineering.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f44', 'faculty', 'Mohammad Pourhomayoun', 'Profile: research focuses on AI, machine learning, and data science for sustainability, environment, healthcare, traffic, and other social-good applications.', 'https://www.calstatela.edu/faculty/mohammad-pourhomayoun', 'My research focuses on Artificial Intelligence, Machine Learning, and Data Science for various applications including sustainability, environment (wildfire, air quality), healthcare, traffic management, and other social good applications.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f45', 'faculty', 'Zilong Ye', 'Profile: research interests in algorithm and system design for computer networking.', 'https://www.calstatela.edu/faculty/zilong-ye', 'research interests focus on algorithm and system design in the computer networking areas, including optical networking and sensing, satellite networking, fog computing, IoT, SDN/NFV, and information-centric networking.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f46', 'faculty', 'Armando Beltran Verdugo', 'Homepage linked from the department listing: research explores AI for computational biology, health informatics, and HCI.', 'https://sites.google.com/view/armandobeltran/', 'My research explores AI for computational biology, health informatics, and human-computer interaction, with a focus on augmenting human capabilities and decision-making.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f47', 'faculty', 'Negin Forouzesh', 'Profile describes doctoral work on computational models of protein-ligand binding.', 'https://www.calstatela.edu/faculty/negin-forouzesh', 'I received my Ph.D. in computer science from Virginia Tech in 2020 where I developed computational models to better understand protein-ligand binding.', '2026-11-14T07:29:27.152108Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f48', 'overview', 'Catalog heading and campus', 'The selected catalog is University Catalog 2026-2027. The program heading is Computer Science, M.S., and the page lists Location(s): Main Campus.', 'https://ecatalog.calstatela.edu/preview_program.php?catoid=77&poid=35252', 'University Catalog 2026-2027 Computer Science, M.S. Location(s): Main Campus', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f49', 'overview', 'Program purpose', 'The catalog says the M.S. is structured to prepare students for advancement in employment as a computer scientist and for later doctoral study.', 'https://ecatalog.calstatela.edu/preview_program.php?catoid=77&poid=35252', 'The program is structured to prepare students for advancement in employment as a computer scientist as well as for further study at the doctoral level.', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f50', 'requirement', '3.0 GPA for conditional admission', 'Applicants with a bachelor''s in Computer Science or a closely related field and an overall GPA of 3.0 or better are considered for conditional admission. An earlier department-page fact quoted similar wording but said ''full admission'' instead of ''conditional admission.'' Both quotes are kept and no winner is chosen.', 'https://ecatalog.calstatela.edu/preview_program.php?catoid=77&poid=35252', 'Applicants must possess a Bachelor''s Degree in Computer Science or a closely related field with overall GPA of 3.0 or better to be considered for conditional admission.', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f51', 'requirement', 'Special action admission at 2.5-2.99 GPA', 'A promising applicant with a GPA between 2.5 and 2.99 may be admitted as a special action student and must then earn a 3.0 GPA in four qualifying courses approved in advance by the department.', 'https://ecatalog.calstatela.edu/preview_program.php?catoid=77&poid=35252', 'A promising applicant with a GPA between 2.5 and 2.99 may be admitted as a special action student. Special action students must achieve an overall GPA of 3.0 for four qualifying courses as approved in advance by the department.', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f52', 'requirement', 'Prerequisites for non-CS or non-ABET backgrounds', 'Prerequisite courses may be required for non-CS students or for students from non-ABET-accredited CS programs.', 'https://ecatalog.calstatela.edu/preview_program.php?catoid=77&poid=35252', 'Prerequisite courses may be required for non-CS students or for students from non-ABET-accredited CS programs.', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f53', 'requirement', 'Classified students and 4000-level prerequisites', 'Classified Master of Science students are not required to take prerequisites below the 4000-level when they use 4000-level courses to satisfy the degree requirement.', 'https://ecatalog.calstatela.edu/preview_program.php?catoid=77&poid=35252', 'Classified Master of Science students are not required to take any prerequisites below the 4000-level when they take 4000-level courses to satisfy the degree requirement.', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f54', 'requirement', '30 units with 18-unit 5000-level core', 'The degree requires 30 units, including 18 units in 5000-level core courses. This 2026-2027 catalog page is a later official curriculum source than the department curriculum page earlier tagged as 2023-2024; both sources are kept and no winner is chosen.', 'https://ecatalog.calstatela.edu/preview_program.php?catoid=77&poid=35252', 'The Master of Science degree in Computer Science degree requires completion of 30 units, with 18 units in 5000-level core courses.', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f55', 'requirement', 'Pre-classified coursework cap', 'Up to 6 units of acceptable post-baccalaureate coursework completed before classified standing may be included in the master''s program.', 'https://ecatalog.calstatela.edu/preview_program.php?catoid=77&poid=35252', 'Up to 6 units of acceptable post-baccalaureate coursework completed before entrance into classified standing may be included in the master''s degree program.', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f56', 'requirement', 'Thesis or comprehensive examination required', 'A thesis or a comprehensive examination satisfies the Culminating Experiences requirement.', 'https://ecatalog.calstatela.edu/preview_program.php?catoid=77&poid=35252', 'A thesis or comprehensive examination is required to satisfy the Culminating Experiences requirement.', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f57', 'requirement', 'Core course structure', 'The 18 core units are met by selecting two courses from each of three areas of study (6 units each).', 'https://ecatalog.calstatela.edu/preview_program.php?catoid=77&poid=35252', 'Requirement for Core Courses (18 units) Select two courses from each of the three areas of study:', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f58', 'requirement', 'Software Design and Implementation core area', 'Area I is Software Design and Implementation (6 units); students select two courses from that list.', 'https://ecatalog.calstatela.edu/preview_program.php?catoid=77&poid=35252', 'I. Software Design and Implementation (6 units) Select two courses.', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f59', 'requirement', 'System Infrastructure core area', 'Area II is System Infrastructure (6 units); students select two courses from that list.', 'https://ecatalog.calstatela.edu/preview_program.php?catoid=77&poid=35252', 'II. System Infrastructure (6 units) Select two courses.', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f60', 'requirement', 'Computing in the World core area', 'Area III is Computing in the World (6 units); students select two courses from that list.', 'https://ecatalog.calstatela.edu/preview_program.php?catoid=77&poid=35252', 'III. Computing in the World (6 units) Select two courses.', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f61', 'requirement', 'Directed electives 6 or 12 units', 'Directed electives are 6 or 12 units: CS 5960 (comprehensive exam) students must select 12 units; CS 5990 (thesis) students select 6 units.', 'https://ecatalog.calstatela.edu/preview_program.php?catoid=77&poid=35252', 'Requirements for Directed Electives (6 or 12 units) CS 5960 students must select 12 units to satisfy the degree requirement. CS 5990 students select 6 units.', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f62', 'requirement', 'Culminating experience courses', 'Students select one culminating path: CS 5960 Comprehensive Examination (0 units) or CS 5990 Thesis at 3 units, completed for 6 units. Students who take CS 5960 must complete 12 units of electives.', 'https://ecatalog.calstatela.edu/preview_program.php?catoid=77&poid=35252', 'Culminating Experiences (0 or 6 units) Select one course. CS 5960 - Comprehensive Examination [0] * CS 5990 - Thesis [3] (complete 6 units) * Students who take CS 5960 must complete a total of 12 units of electives.', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f63', 'course', 'CS 5035', 'CS 5035 Topics in Functional Programming, Cal State LA 2026-27 catalog: Evaluating expressions vs. executing statements; functions as first class objects; higher-order functions; currying; partial evaluation; closures; mutable and immutable variables; comprehensions; referential transparency; lazy evaluation.', 'https://ecatalog.calstatela.edu/preview_course_nopop.php?catoid=77&coid=573601', 'Evaluating expressions vs. executing statements; functions as first class objects; higher-order functions; currying; partial evaluation; closures; mutable and immutable variables; comprehensions; referential transparency; lazy evaluation.', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f64', 'course', 'CS 5112', 'CS 5112 Design and Analysis of Algorithms, Cal State LA 2026-27 catalog: Design of complex algorithms. Algorithms for solving frequently occurring problems in computer applications. Computationally intractable problems, heuristics and partial solutions. Optimization techniques. Analysis of algorithms for specific problems of interest.', 'https://ecatalog.calstatela.edu/preview_course_nopop.php?catoid=77&coid=570855', 'Design of complex algorithms. Algorithms for solving frequently occurring problems in computer applications. Computationally intractable problems, heuristics and partial solutions. Optimization techniques. Analysis of algorithms for specific problems of interest.', '2026-11-19T05:33:20.773Z');
INSERT INTO program_facts (snapshot_id, fact_id, kind, name, detail, source_url, quote, fetched_at) VALUES ('9-20261118', 'f65', 'course', 'CS 5220', 'CS 5220 Advanced Topics in Web Programming, Cal State LA 2026-27 catalog: Technologies, architectures, methodologies, design patterns, and frameworks that help create scalable, robust, and maintainable web applications and web services.', 'https://ecatalog.calstatela.edu/preview_course_nopop.php?catoid=77&coid=570856', 'Technologies, architectures, methodologies, design patterns, and frameworks that help create scalable, robust, and maintainable web applications and web services.', '2026-11-19T05:33:20.773Z');
